comms.text:
@1 וּשְׁמַע יִתְרוֹ רַבָּא דְמִדְיָן חֲמוּהִי דְמשֶׁה יַת כָּל דִי עֲבַד יְיָ לְמשֶׁה וּלְיִשְׂרָאֵל עַמֵהּ אֲרֵי אַפִּיק יְיָ יָת יִשְׂרָאֵל מִמִצְרָיִם:
@2 וּדְבַר יִתְרוֹ חֲמוּהִי דְמשֶׁה יָת צִפֹּרָה אִתַּת משֶׁה בָּתַר דְפַטְרַהּ:
@3 וְיָת תְּרֵין בְּנָהָא דִי שׁוּם חַד גֵרְשֹׁם אֲרֵי אֲמַר דַיָר הֲוֵיתִי בְּאַרְעָא נוּכְרָאָה:
@4 וְשׁוּם חַד אֱלִיעֶזֶר אֲרֵי אֱלָהָא דְאַבָּא הֲוָה בְסַעְדִי וְשֵׁזְבַנִי מֵחַרְבָּא דְפַרְעֹה:
@5 וַאֲתָא יִתְרוֹ חֲמוּהִי דְמשֶׁה וּבְנוֹהִי וְאִתְּתֵהּ לְוָת משֶׁה לְמַדְבְּרָא דִי הוּא שָׁרֵי תַמָן לְטוּרָא דְאִתְגְלֵי עֲלוֹהִי יְקָרָא דַיְיָ:
@6 וַאֲמַר לְמשֶׁה אֲנָא חֲמוּךְ יִתְרוֹ אָתֵי לְוָתָךְ וְאִתְּתָךְ וּתְרֵין בְּנָהָא עִמַהּ:
@7 וּנְפַק משֶׁה לְקַדָמוּת חֲמוּהִי וּסְגִיד וּנְשִׁיק לֵהּ וּשְׁאִילוּ גְבַר לְחַבְרֵהּ לִשְׁלָם וְעַלוּ לְמַשְׁכְּנָא:
@8 וְאִשְׁתָּעִי משֶׁה לַחֲמוּהִי יָת כָּל דִי עֲבַד יְיָ לְפַרְעֹה וּלְמִצְרָאֵי עַל עֵסַק יִשְׂרָאֵל יָת כָּל עַקְתָא דִי אַשְׁכַּחְתִּנוּן בְּאָרְחָא וְשֵׁזְבָנוּן יְיָ:
@9 וַחֲדִי יִתְרוֹ עַל כָּל טַבְתָא דִי עֲבַד יְיָ לְיִשְׂרָאֵל דִי שֵׁזְבָנוּן מִידָא דְמִצְרָאֵי:
@10 וַאֲמַר יִתְרוֹ בְּרִיךְ יְיָ דִי שֵׁזִיב יָתְכוֹן מִידָא דְמִצְרָאֵי וּמִידָא דְפַרְעֹה דִי שֵׁזִיב יָת עַמָא מִתְּחוֹת מַרְוַת מִצְרָאֵי:
@11 כְּעַן יְדַעְנָא אֲרֵי רַב יְיָ וְלֵית אֱלָּהּ בַּר מִנֵהּ אֲרֵי בְּפִתְגָמָא דִי חַשִׁיבוּ מִצְרָאֵי לְמִדַן יָת יִשְׂרָאֵל בֵּהּ דָנִנוּן:
@12 וְקָרִיב יִתְרוֹ חֲמוּהִי דְמשֶׁה עֲלָוָן וְנִכְסַת קוּדְשִׁין קֳדָם יְיָ וַאֲתָא אַהֲרֹן וְכֹל סָבֵי יִשְׂרָאֵל לְמֵיכַל לַחְמָא עִם חֲמוּהִי דְמשֶׁה קֳדָם יְיָ:
@13 וַהֲוָה מִיוֹמָא דְבַתְרוֹהִי וִיתֵיב משֶׁה לְמִדַן יָת עַמָא וְקָם עַמָא עִלָוֹהִי דְמשֶׁה מִן צַפְרָא עַד רַמְשָׁא:
@14 וַחֲזָא חֲמוּהִי דְמשֶׁה יָת כָּל דִי הוּא עָבֵד לְעַמָא וַאֲמַר מָא פִתְגָמָא הָדֵין דִי אַתְּ עָבֵד לְּעַמָא מָה דֵין אַתְּ יָתֵב בִּלְחוֹדָךְ וְכָל עַמָא קָיְמִין עִלָוָךְ מִן צַפְרָא עַד רַמְשָׁא:
@15 וַאֲמַר משֶׁה לַחֲמוּהִי אֲרֵי אָתָן לְוָתִי עַמָא לְמִתְבַּע אוּלְפַן מִן קֳדָם יְיָ:
@16 כַּד הֲוֵי לְהוֹן דִינָא אָתָן לְוָתִי וְדָאִינְנָא בֵּין גַבְרָא וּבֵין חַבְרֵהּ וּמְהוֹדַעְנָא לְהוֹן יָת קְיָמַיָא דַיְיָ וְיָת אוֹרָיָתֵהּ:
@17 וַאֲמַר חֲמוּהִי דְמשֶׁה לֵהּ לָא תַקִין פִּתְגָמָא דְאַתְּ עָבֵד:
@18 מִלְאָה תִלְאֶה אַף אַתְּ אַף עַמָא הָדֵין דִעִמָךְ אֲרֵי יַקִיר מִנָךְ פִּתְגָמָא לָא תִכּוֹל לְמֶעְבְּדֵהּ בִּלְחוֹדָךְ:
@19 כְּעַן קַבֵּל מִנִי אֲמַלְכִנָךְ וִיהֵי מֵימְרָא דַיְיָ בְּסַעְדָךְ הֱוֵי אַתְּ לְעַמָא (תְּבַע) אוּלְפַן מִן קֳדָם יְיָ וּתְהֵי מַיְתִי אַתְּ יָת פִּתְגָמַיָא לִקֳדָם יְיָ:
@20 וְתַזְהַר יָתְהוֹן יָת קְיָמַיָא וְיָת אוֹרַיְתָא וּתְהוֹדַע לְהוֹן יָת אוֹרְחָא דִיְהָכוּן בַּהּ וְיָת עוֹבָדָא דִיַעְבְּדוּן:
@21 וְאַתְּ תֶּחֶזֵי מִכָּל עַמָא גֻבְרִין דְחֵילָא דַחֲלַיָא דַיְיָ גֻבְרִין דִקְשׁוֹט דְסָנָן לְקַבָּלָא מָמוֹן וּתְמַנֵי עֲלֵיהוֹן רַבָּנֵי אַלְפִין רַבָּנֵי מָאוָתָא רַבָּנֵי חַמְשִׁין וְרַבָּנֵי עִשׂוֹרְיָתָא:
@22 וִידוּנוּן יָת עַמָא בְּכָל עִדַן וִיהֵי כָּל פִּתְגַם רַב יַיְתוּן לְוָתָךְ וְכָל פִּתְגַם זְעֵיר יְדוּנוּן אִנוּן וְיִקְלוּן מִנָךְ וִיסוֹבְרוּן עִמָךְ:
@23 אִם יָת פִּתְגָמָא הָדֵין תַּעְבֵּד וִיפַקְדִנָךְ יְיָ וְתִכּוֹל לְמֵיקָם וְאַף כָּל עַמָא הָדֵין עַל אַתְרֵהּ יְהַךְ בִּשְׁלָם:
@24 וְקַבִּיל משֶׁה לְמֵימְרָא דַחֲמוּהִי וַעֲבַד כֹּל דִי אֲמָר:
@25 וּבְחַר משֶׁה גֻבְרִין דְחֵילָא מִכָּל יִשְׂרָאֵל וּמַנִי יָתְהוֹן רֵישִׁין עַל עַמָא רַבָּנֵי אַלְפִין רַבָּנֵי מָאוָתָא רַבָּנֵי חַמְשִׁין וְרַבָּנֵי עִשׂוֹרְיָתָא:
@26 וְדַיְנִין יָת עַמָא בְּכָל עִדָן יָת פִתְגַם קָשֵׁי מַיְתִין לְוָת משֶׁה וְכָל פִּתְגַם זְעֵיר דָיְנִין אִנוּן:
@27 וְשַׁלַח משֶׁה יָת חֲמוּהִי וַאֲזַל לֵהּ לְאַרְעֵהּ:
@28 בְּיַרְחָא תְּלִיתָאָה לְמִפַּק בְּנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרָיִם בְּיוֹמָא הָדֵין אֲתוֹ לְמַדְבְּרָא דְסִינָי:
@29 וּנְטָלוּ מֵרְפִידִים וַאֲתוֹ לְמַדְבְּרָא דְסִינָי וּשְׁרוֹ בְּמַדְבְּרָא וּשְׁרָא תַמָן יִשְׂרָאֵל לָקֳבֵל טוּרָא:
@30 וּמשֶׁה סְלֵק לִקֳדָם יְיָ וּקְרָא לֵהּ יְיָ מִן טוּרָא לְמֵימַר כִּדְנַן תֵּימַר לְבֵית יַעֲקֹב וּתְחַוִי לִבְנֵי יִשְׂרָאֵל:
@31 אַתּוּן חֲזִתּוּן דִי עֲבָדִית לְמִצְרָיִם וּנְטָלִית (נ''א וְאַטְּלִית) יָתְכוֹן כִּדְעַל גַדְפֵי נִשְׁרִין וְקָרֵבִית יָתְכוֹן לְפָלְחָנִי:
@32 וּכְעַן אִם קַבָּלָא תְקַבְּלוּן לְמֵימְרִי וְתִטְרוּן יָת קְיָמִי וּתְהוֹן קֳדָמַי חַבִּיבִין מִכָּל עַמְמַיָא אֲרֵי דִי לִי כָּל אַרְעָא:
@33 וְאַתּוּן תְּהוֹן קֳדָמַי מַלְכִין כָּהֲנִין וְעַם קַדִישׁ אִלֵין פִּתְגָמַיָא דִי תְמַלֵל עִם בְּנֵי יִשְׂרָאֵל:
@34 וַאֲתָא משֶׁה וּקְרָא לְסָבֵי עַמָא וְסַדַר קֳדָמֵיהוֹן יָת כָּל פִּתְגָמַיָא הָאִלֵין דִפַקְדֵיהּ יְיָ:
@35 וַאֲתִיבוּ כָל עַמָא כַּחֲדָא וַאֲמָרוּ כֹּל דִי מַלִיל יְיָ נַעְבֵּד וַאֲתֵיב משֶׁה יָת פִּתְגָמֵי עַמָא קֳדָם יְיָ:
@36 וַאֲמַר יְיָ לְמשֶׁה הָא אֲנָא מִתְגְלִי לָךְ בְּעֵיבָא דַעֲנָנָא בְּדִיל דְיִשְׁמַע עַמָא בְּמַלָלוּתִי עִמָךְ וְאַף בָּךְ יְהֵימְנוּן לְעָלָם וְחַוִי משֶׁה יָת פִּתְגָמֵי עַמָא קֳדָם יְיָ:
@37 וַאֲמַר יְיָ לְמשֶׁה אִזֵיל לְוָת עַמָא וּתְזַמִנוּן יוֹמָא דֵין וּמְחָר וִיחַוְרוּן לְבוּשֵׁיהוֹן:
@38 וִיהוֹן זְמִינִין לְיוֹמָא תְלִיתָאָה אֲרֵי בְּיוֹמָא תְלִיתָאָה יִתְגְלִי יְיָ לְעֵינֵי כָל עַמָא עַל טוּרָא דְסִינָי:
@39 וּתְתַחֵם יָת עַמָא סְחוֹר סְחוֹר לְמֵימַר אִסְתַּמָרוּ לְכוֹן מִלְמִסַק בְּטוּרָא וּלְמִקְרַב בְּסוֹפֵהּ כָּל דְיִקְרַב בְּטוּרָא אִתְקְטָלָא יִתְקְטֵל:
@40 לָא תִקְרַב בֵּהּ יְדָא אֲרֵי אִתְרְגָמָא יִתְרְגֵם אוֹ אִשְׁתְּדָאָה יִשְׁתְּדִי אִם בְּעִירָא אִם אֱנָשָׁא לָא יִתְקַיָם בְּמֵיגַד שׁוֹפָרָא אִנוּן מְרָשָׁן לְמִסַק בְּטוּרָא:
@41 וּנְחַת משֶׁה מִן טוּרָא לְוָת עַמָא וְזַמִין יָת עַמָא וְחַוָרוּ לְבוּשֵׁיהוֹן:
@42 וַאֲמַר לְעַמָא הֱווֹ זְמִינִין לִתְלָתָא יוֹמִין לָא תִקְרְבוּן לְצַד אִתְּתָא:
@43 וַהֲוָה בְיוֹמָא תְלִיתָאָה בְּמֶהֱוֵי צַפְרָא וַהֲוָה קָלִין וּבַרְקִין וַעֲנָנָא תַקִיף עַל טוּרָא וְקַל שׁוֹפָרָא תַּקִיף לַחֲדָא וְזָע כָּל עַמָא דִי בְמַשְׁרִיתָא:
@44 וְאַפֵיק משֶׁה יָת עַמָא לְקַדָמוּת מֵימְרָא דַיְיָ מִן מַשְׁרִיתָא וְאִתְעַתָּדוּ בְּשִׁפּוֹלֵי טוּרָא:
@45 וְטוּרָא דְסִינַי תָּנַן כֻּלֵהּ מִן קֳדָם דְאִתְגְלִי עֲלוֹהִי יְיָ בְּאֶשָׁתָא וּסְלִיק תְּנָנֵהּ כִּתְנָנָא דְאַתּוּנָא וְזָע כָּל טוּרָא לַחֲדָא:
@46 וַהֲוָה קַל שׁוֹפָרָא אָזֵל וְתָקֵף לַחֲדָא משֶׁה מְמַלֵל וּמִן קֳדָם יְיָ מִתְעֲנֵי לֵהּ בְקָל:
@47 וְאִתְגְלִי יְיָ עַל טוּרָא דְסִינַי לְרֵישׁ טוּרָא וּקְרָא יְיָ לְמשֶׁה לְרֵישׁ טוּרָא וּסְלִיק משֶׁה:
@48 וַאֲמַר יְיָ לְמשֶׁה חוּת אַסְהֵיד בְּעַמָא דִילְמָא יְפַגְרוּן קֳדָם יְיָ לְמֶחֱזֵי וְיִפֵּל מִנְהוֹן סַגִי:
@49 וְאַף כָּהֲנַיָא דִקְרִיבִין לְשַׁמָשָׁא קֳדָם יְיָ יִתְקַדְשׁוּן דִילְמָא יִקְטוֹל בְּהוֹן יְיָ:
@50 וַאֲמַר משֶׁה קֳדָם יְיָ לָא יִכּוֹל עַמָא לְמִסַק לְטוּרָא דְסִינַי אֲרֵי אַתְּ אַסְהֵדְתָּ בָּנָא לְמֵימַר תַּחִים יָת טוּרָא וְקַדְשֵׁהּ:
@51 וַאֲמַר לֵהּ יְיָ אִזֵיל חוּת וְתִסַק אַתְּ וְאַהֲרֹן עִמָךְ וְכָהֲנַיָא וְעַמָא לָא יְפַגְרוּן לְמִסַק לִקֳדָם יְיָ דִילְמָא יִקְטוֹל בְּהוֹן:
@52 וּנְחַת משֶׁה לְעַמָא וַאֲמַר לְהוֹן:
@53 וּמַלִיל יְיָ יָת כָּל פִּתְגָמַיָא הָאִלֵין לְמֵימָר:
@54 אֲנָא יְיָ אֱלָהָךְ דִי אַפֵּיקְתָּךְ מֵאַרְעָא דְמִ צְרַיִם מִבֵּית עַבְדוּתָא:
@55 לָא יְהֵי לָךְ אֱלָהּ אָחֳרָן בַּר מִנִי:
@56 לָא תַעְבֵּד לָךְ צֶלֶם וְכָל דְמוּת דִי בִשְׁמַיָא מִלְעֵלָא וְדִי בְאַרְעָא מִלְרָע וְדִי בְמַיָא מִלְרַע לְאַרְעָא:
@57 לָא תִסְגֻד לְהוֹן וְלָא תִפְלְחִנוּן אֲרֵי אֲנָא יְיָ אֱלָהָךְ אֵל קַנָא מַסְעַר חוֹבֵי אֲבָהָן עַל בְּנִין מָרָדִין עַל דַר תְּלִיתַי וְעַל דַר רְבִיעַי לְשָׂנְאָי כַּד מְשַׁלְמִין בְּנַיָא לְמֶחֱטֵי בָּתַר אֲבָהָתְהוֹן:
@58 וְעָבֵד טִּיבוּ לְאַלְפֵי דָרִין לְרַחֲמַי וּלְנָטְרֵי פִקוֹדָי:
@59 לָא תֵימֵי יָת שְׁמָא דַיְיָ אֱלָהָךְ לְמַגָנָא אֲרֵי לָא יִזַכֵּי יְיָ יָת דִיֵימֵי בִשְׁמֵהּ לְשִׁקְרָא:
@60 הֲוֵי דְכִיר יָת יוֹמָא דְשַׁבְּתָא לְקַדָשׁוּתֵהּ:
@61 שִׁתָּא יוֹמִין תִּפְלָח וְתַעְבֵּד כָּל עִבִדְתָּךְ:
@62 וְיוֹמָא שְׁבִיעָאָה שַׁבְּתָא קֳדָם יְיָ אֱלָהָךְ לָא תַעְבֵּד כָּל עִבִדְתָּא אַתְּ וּבְרָךְ וּבְרַתָּךְ עַבְדָךְ וְאַמְתָךְ וּבְעִירָךְ וְגִיוֹרָךְ דִי בְקִרְוָךְ:
@63 אֲרֵי שִׁתָּא יוֹמִין עֲבַד יְיָ יָת שְׁמַיָא וְיָת אַרְעָא יָת יַמָא וְיָת כָּל דִי בְהוֹן וְנָח בְּיוֹמָא שְׁבִיעָאָה עַל כֵּן בָּרִיךְ יְיָ יָת יוֹמָא דְשַׁבְּתָא וְקַדְשֵׁהּ:
@64 יַקַר יָת אָבוּךְ וְיָת אִמָךְ בְּדִיל דְיוֹרְכוּן יוֹמָיךְ עַל אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@65 לָא תִקְטוֹל נְפָשׁ לָא תְגוּף לָא תִגְנוּב לָא תַסְהֵד בְּחַבְרָךְ סַהֲדוּתָא דְשִׁקְרָא:
@66 לָא תַחְמֵד בֵּית חַבְרָךְ לָא תַחְמֵד אִתַּת חַבְרָךְ וְעַבְדֵהּ וְאַמְתֵהּ וְתוֹרֵהּ וַחֲמָרֵהּ וְכֹל דִי לְחַבְרָךְ:
@67 וְכָל עַמָא חָזָן יָת קָלַיָא וְיָת בָּעוֹרַיָא וְיָת קַל שׁוֹפָרָא וְיָת טוּרָא תָּנֵן וַחֲזָא עַמָא וְזָעוּ וְקָמוּ מֵרָחִיק:
@68 וַאֲמָרוּ לְמשֶׁה מַלֵל אַתְּ עִמָנָא וּנְקַבֵּל וְלָא יִתְמַלֵל עִמָנָא מִן קֳדָם יְיָ דִילְּמָא נְמוּת:
@69 וַאֲמַר משֶׁה לְעַמָא לָא תִדְחֲלוּן אֲרֵי בְּדִיל לְנַסָאָה יָתְכוֹן אִתְגְלִי לְכוֹן יְקָרָא דַיְיָ וּבְדִיל דִתְהֵי דַחַלְתֵּהּ עַל אַפֵּיכוֹן בְּדִיל דְלָא תְחוּבוּן:
@70 וְקָם עַמָא מֵרָחִיק וּמשֶׁה קָרֵב לְצַד אַמִיטְּתָא דִתַמָן יְקָרָא דַיְיָ:
@71 וַאֲמַר יְיָ לְמשֶׁה כִּדְנַן תֵּימַר לִבְנֵי יִשְׂרָאֵל אַתּוּן חֲזִיתּוּן אֲרֵי מִן שְׁמַיָא מַלֵילִית עִמְכוֹן:
@72 לָא תַעְבְּדוּן קֳדָמָי דַחֲלָן דִכְסַף וְדַחֲלָן דִדְהַב לָא תַעְבְּדוּן לְכוֹן:
@73 מַדְבַּח אַדְמְתָא תַּעְבֵּד קֳדָמַי וּתְהֵי דַבָּח עֲלוֹהִי יָת עֲלָוָתָךְ וְיָת נְכַס קוּדְשָׁךְ מִן עָנָךְ וּמִן תּוֹרָךְ בְּכָל אַתְרָא דִי אַשְׁרֵי יָת שְׁכִנְתִּי לְתַמָן אֶשְׁלַח בִּרְכְּתִי לָךְ וֶאֱבָרֵכִנָךְ:
@74 וְאִם מַדְבַּח אַבְנִין תַּעְבֵּד קֳדָמַי לָא תִבְנֵי יָתְהוֹן פְּסִילָן לָא תְרִים חַרְבָּךְ עֲלַהּ וּתְחַלְלִנַהּ:
@75 וְלָא תִסַק בְּדַרְגִין עַל מַדְבְּחִי דְלָא תִתְגְלֵי עֶרְיְתָךְ עֲלוֹהִי: פפפ:

@1 **וישמע יתרו.** מה שמועה שמע ובא, קריעת ים סוף ומלחמת עמלק: **יתרו.** שבע שמות נקראו לו רעואל, יתר, יתרו, חובב, חבר, קני, פוטיאל. יתר, על שם שיתר פרשה אחת בתורה (להלן פסוק כא) ואתה תחזה. יתרו לכשנתגיר וקים המצות הוסיפו לו אות אחת על שמו. חובב שחבב את התורה. וחובב הוא יתרו, שנאמר (שופטים ד יא) מבני חובב חותן משה. ויש אומרים רעואל אביו של יתרו היה, ומה הוא אומר (שמות ב יח) ותבאנה אל רעואל אביהן, שהתינוקות קורין לאבי אביהן אבא. בספרי: **חתן משה.** כאן היה יתרו מתכבד במשה, אני חותן המלך ולשעבר היה משה תולה הגדלה בחמיו, שנאמר (שמות ד יח) וישב אל יתר חותנו: **למשה ולישראל.** שקול משה כנגד כל ישראל: **את כל אשר עשה.** להם בירידת המן ובבאר ובעמלק: **כי הוציא ה'** וגו' **.** זו גדולה על כלם:
@2 **אחר שלוחיה.** כשאמר לו הקדוש ברוך הוא במדין (שמות ד יט) לך שוב מצרים, (שם כ) ויקח משה את אשתו ואת בניו גו' ויצא אהרן לקראתו, (שם כז) ויפגשהו בהר האלהים. אמר לו מי הם הללו. אמר לו זו היא אשתי שנשאתי במדין ואלו בני. אמר לו והיכן אתה מוליכן. אמר לו למצרים. אמר לו על הראשונים אנו מצטערים ואתה בא להוסיף עליהם. אמר לה לכי אל בית אביך, נטלה שני בניה והלכה לה:
@4 **ויצלני מחרב פרעה.** כשגלו דתן ואבירם על דבר המצרי ובקש להרג את משה, נעשה צוארו כעמוד של שיש:
@5 **אל המדבר.** אף אנו יודעין שבמדבר היו, אלא בשבחו של יתרו דבר הכתוב, שהיה יושב בכבודו של עולם ונדבו לבו לצאת אל המדבר, מקום תהו, לשמוע דברי תורה:
@6 **ויאמר אל משה.** על ידי שליח: **אני חתנך יתרו** וגו' **.** אם אין אתה יוצא בגיני צא בגין אשתך, ואם אין אתה יוצא בגין אשתך צא בגין שני בניה:
@7 **ויצא משה.** כבוד גדול נתכבד יתרו באותה שעה, כיון שיצא משה יצא אהרן נדב ואביהוא, ומי הוא שראה את אלו יוצאין ולא יצא: **וישתחו וישק לו.** איני יודע מי השתחוה למי, כשהוא אומר איש לרעהו, מי הקרוי איש, זה משה, שנאמר (במדבר יב ג) והאיש משה:
@8 **ויספר משה לחתנו.** למשוך את לבו לקרבו לתורה: **את כל התלאה.** שעל הים ושל עמלק: **התלאה.** למ''ד אל''ף מן היסוד של התבה והתי''ו הוא תקון ויסוד הנופל ממנו לפרקים, וכן תרומה, תנופה, תקומה, תנואה:
@9 **ויחד יתרו.** וישמח יתרו, זהו פשוטו ומדרשו נעשה בשרו חדודין חדודין, מצר על אבוד מצרים, הינו דאמרי אינשי גיורא עד עשרה דרי לא תבזי ארמאה באפיה: **על כל הטובה.** טובת המן והבאר והתורה. ועל כלן אשר הצילו מיד מצרים, עד עכשיו לא היה עבד יכול לברוח ממצרים, שהיתה הארץ מסגרת, ואלו יצאו ששים רבוא:
@10 **אשר הציל אתכם מיד מצרים.** אמה קשה: **ומיד פרעה.** מלך קשה: **מתחת יד מצרים.** כתרגומו לשון רדוי ומרות היד שהיו מכבידים עליהם, היא העבודה:
@11 **עתה ידעתי.** מכירו הייתי לשעבר ועכשיו ביותר: **מכל האלהים.** מלמד שהיה מכיר בכל עבודה זרה שבעולם שלא הניח עבודה זרה שלא עבדה: **כי בדבר אשר זדו עליהם.** כתרגומו במים דמו לאבדם והם נאבדו במים: **אשר זדו.** אשר הרשיעו. ורבותינו דרשוהו לשון (בראשית כה כט) ויזד יעקב נזיד, בקדרה אשר בשלו בה, נתבשלו:
@12 **עלה.** כמשמעה שהיא עולה כליל: **וזבחים.** שלמים: **ויבא אהרן** וגו' **.** ומשה היכן הלך, והלא הוא שיצא לקראתו וגרם לו את כל הכבוד, אלא שהיה עומד ומשמש לפניהם: **לפני האלהים.** מכאן שהנהנה מסעודה שתלמידי חכמים מסבין בה כאלו נהנה מזיו השכינה:
@13 **ויהי ממחרת.** מוצאי יום הכפורים היה, כך שנינו בספרי, ומהו ממחרת, למחרת רדתו מן ההר. ועל כרחך אי אפשר לומר אלא ממחרת יום הכפורים, שהרי קודם מתן תורה אי אפשר לומר (פסוק טז) והודעתי את חקי וגו' , ומשנתנה תורה עד יום הכפורים לא ישב משה לשפוט את העם, שהרי בשבעה עשר בתמוז ירד ושבר את הלוחות, ולמחר עלה בהשכמה ושהה שמונים יום וירד ביום הכפורים. ואין פרשה זו כתובה כסדר, שלא נאמר ויהי ממחרת עד שנה שניה, אף לדברי האומר יתרו קדם מתן תורה בא, שלוחו אל ארצו לא היה אלא עד שנה שניה, שהרי נאמר כאן (פסוק כז) וישלח משה את חתנו ומצינו במסע הדגלים שאמר לו משה (במדבר י כט) נוסעים אנחנו אל המקום וגו' , (שם לא) אל נא תעזוב אותנו, ואם זו קדם מתן תורה, מששלחו והלך היכן מצינו שחזר ואם תאמר שם לא נאמר יתרו אלא חובב, ובנו של יתרו היה, הוא חובב הוא יתרו, שהרי כתיב (שופטים ד יא) מבני חובב חותן משה: **וישב משה** וגו' **ויעמד העם.** יושב כמלך וכלן עומדים, והקשה הדבר ליתרו שהיה מזלזל בכבודן של ישראל והוכיחו על כך, שנאמר (פסוק יד) מדוע אתה יושב לבדך וכלם נצבים: **מן הבקר עד הערב.** אפשר לומר כן, אלא כל דין שדן דין אמת לאמתו אפלו שעה אחת, מעלה עליו הכתוב כאלו עוסק בתורה כל היום, וכאלו נעשה שותף להקדוש ברוך הוא במעשה בראשית, שנאמר בו (בראשית א ה) ויהי ערב ויהי בקר יום אחד:
@15 **כי יבא.** כמו כי בא, לשון הוה: **לדרש אלהים.** כתרגומו למתבע אלפן, לשאול תלמוד מפי הגבורה:
@16 **כי יהיה להם דבר בא.** מי שיהיה לו דבר בא אלי:
@17 **ויאמר חתן משה.** דרך כבוד קוראו הכתוב חותנו של מלך:
@18 **נבל תבל.** כתרגומו. ולשונו לשון כמישה פליישטרי''ר בלעז . כמו (ירמיה ח יג) והעלה נבל, (ישעיה לד ד) כנבול עלה מגפן וגו' , שהוא כמוש על ידי חמה ועל ידי קרח, וכחו תש ונלאה: **גם אתה.** לרבות אהרן וחור ושבעים זקנים: **כי כבד ממך.** כבדו רב יותר מכחך:
@19 **איעצך ויהי אלהים עמך.** בעצה, אמר לו צא המלך בגבורה: **היה אתה לעם מול האלהים.** שליח ומליץ בינותם למקום, ושואל משפטים מאתו: **את הדברים.** דברי ריבותם:
@21 **ואתה תחזה.** ברוח הקדש שעליך: **אנשי חיל.** עשירים, שאין צריכין להחניף ולהכיר פנים: **אנשי אמת.** אלו בעלי הבטחה, שהם כדאי לסמוך על דבריהם, שעל ידי כן יהיו דבריהם נשמעין: **שנאי בצע.** ששונאין את ממונם בדין כההיא דאמרינן כל דינא דמפקין ממונא מניה בדינא לאו דינא הוא: **שרי אלפים.** הם היו שש מאות שרים לשש מאות אלף: **שרי מאות.** ששת אלפים היו: **שרי חמשים.** שנים עשר אלף: **ושרי עשרת.** ששים אלף:
@22 **ושפטו.** וידונון, לשון צווי: **והקל מעליך.** דבר זה להקל מעליך. והקל, כמו (שמות ח יא) והכבד את לבו, (מלכים ב ג כד) והכות את מואב, לשון הוה:
@23 **וצוך אלהים ויכלת עמד.** המלך בגבורה אם יצוה אותך לעשות כך תוכל עמוד, ואם יעכב על ידך לא תוכל לעמוד: **וגם כל העם הזה.** אהרן נדב ואביהוא ושבעים זקנים הנלוים עתה עמך:
@26 **ושפטו.** ודינין ית עמא: **יביאון.** מיתן: **ישפוטו הם.** כמו ישפוטו וכן (רות ב ח) לא תעבורי, כמו לא תעברי ותרגומו דינין אנון. מקראות העליונים הם לשון צווי, לכך מתרגמין וידונון ייתון, ידונון, ומקראות הללו לשון עשיה:
@27 **וילך לו אל ארצו.** לגיר בני משפחתו:
@28 **ביום הזה.** בראש חדש. לא היה צריך לכתוב אלא ביום ההוא, מהו ביום הזה, שיהיו דברי תורה חדשים עליך כאלו היום נתנו:
@29 **ויסעו מרפידים.** למה הצרך לחזור ולפרש מהיכן נסעו, והלא כבר כתב שברפידים היו חונים, בידוע שמשם נסעו, אלא להקיש נסיעתן מרפידים לביאתן למדבר סיני, מה ביאתן למדבר סיני בתשובה, אף נסיעתן מרפידים בתשובה: **ויחן שם ישראל.** כאיש אחד בלב אחד, אבל שאר כל החניות בתרעומת ובמחלוקת: **נגד ההר.** למזרחו, וכל מקום שאתה מוצא נגד, פנים למזרח:
@30 **ומשה עלה.** ביום השני. וכל עליותיו בהשכמה היו, שנאמר (שמות לד ד) וישכם משה בבקר: **כה תאמר.** בלשון הזה וכסדר הזה: **לבית יעקב.** אלו הנשים, תאמר להן בלשון רכה: **ותגיד לבני ישראל.** ענשין ודקדוקין פרש לזכרים. דברים הקשין כגידין:
@31 **אתם ראיתם.** לא מסרת היא בידכם, ולא בדברים אני משגר לכם, לא בעדים אני מעיד עליכם, אלא אתם ראיתם אשר עשיתי למצרים, על כמה עברות היו חיבין לי קדם שנזדוגו לכם, ולא נפרעתי מהם אלא על ידכם: **ואשא אתכם.** זה יום שבאו ישראל לרעמסס, שהיו ישראל מפזרין בכל ארץ גושן, ולשעה קלה כשבאו לסע ולצאת נקבצו כלם לרעמסס. ואונקלוס תרגם ואשא, ונטלית יתכון, כמו ואסיע אתכם, תקן את הדבר דרך כבוד למעלה: **על כנפי נשרים.** כנשר הנושא גוזליו על כנפיו, שכל שאר העופות נותנים את בניהם בין רגליהם, לפי שמתיראין מעוף אחר שפורח על גביהם, אבל הנשר הזה אינו מתירא אלא מן האדם, שמא יזרוק בו חץ, לפי שאין עוף אחר פורח על גביו, לכך נותנן על כנפיו, אומר מוטב יכנס החץ בי, ולא בבני. אף אני עשיתי כן, (שמות יד יט) ויסע מלאך האלהים וגו' (שם כ) ויבא בין מחנה מצרים וגו' , והיו מצרים זורקים חצים ואבני בליסטראות והענן מקבלם: **ואבא אתכם אלי.** כתרגומו:
@32 **ועתה.** אם עתה תקבלו עליכם יערב לכם מכאן ואלך, שכל התחלות קשות: **ושמרתם את בריתי.** שאכרות עמכם על שמירת התורה: **סגלה.** אוצר חביב, כמו (קהלת ב ח) וסגלת מלכים, כלי יקר ואבנים טובות שהמלכים גונזים אותם. כך אתם תהיו לי סגלה משאר אמות, ולא תאמרו אתם לבדכם שלי ואין לי אחרים עמכם, ומה יש לי עוד שתהא חבתכם נכרת: **כי לי כל הארץ.** והם בעיני ולפני לכלום:
@33 **ואתם תהיו לי ממלכת כהנים.** שרים כמה דאת אמר (שמואל ב' ח יח) ובני דוד כהנים היו: **אלה הדברים.** לא פחות ולא יותר:
@35 **וישב משה את דברי העם** וגו' **.** ביום המחרת, שהוא יום שלישי, שהרי בהשכמה עלה. וכי צריך היה משה להשיב, אלא בא הכתוב ללמדך דרך ארץ ממשה שלא אמר, הואיל ויודע מי ששלחני, איני צריך להשיב:
@36 **בעב הענן.** במעבה הענן וזהו ערפל: **וגם בך.** גם בנביאים הבאים אחריך: **ויגד משה.** ביום המחרת שהוא רביעי לחדש: **את דברי העם** וגו' **.** תשובה על דבר זה שמעתי מהם שרצונם לשמוע ממך אינו דומה השומע מפי השליח לשומע מפי המלך, רצוננו לראות את מלכנו:
@37 **ויאמר ה' אל משה.** אם כן, שמזקיקין לדבר עמם, לך אל העם: **וקדשתם.** וזמנתם, שיכינו עצמם היום ומחר:
@38 **והיו נכנים.** מבדלים מאשה: **ליום השלישי.** שהוא ששה בחדש. ובחמישי בנה משה את המזבח תחת ההר ושתים עשרה מצבה, כל הענין האמור בפרשת ואלה המשפטים, (שמות כד ד) ואין מקדם ומאחר בתורה: **לעיני כל העם.** מלמד שלא היה בהם סומא, שנתרפאו כלם:
@39 **והגבלת.** קבע להם תחומין לסימן, שלא יקרבו מן הגבול והלאה: **לאמר.** הגבול אומר להם, השמרו מעלות מכאן והלאה, ואתה תזהירם על כך: **ונגע בקצהו.** אפלו בקצהו:
@40 **ירה יירה.** מכאן לנסקלין שהם נדחין למטה מבית הסקילה, שהיה גבוה שתי קומות: **יירה.** ישלך למטה לארץ, כמו (שמות טו ד) ירה בים: **במשך היבל.** כשימשוך היובל קול ארוך הוא סימן סלוק שכינה והפסקת הקול, וכיון שנסתלק הם רשאין לעלות: **היבל.** הוא שופר של איל, שכן בערביא קורין לדכרא יובלא, ושופר של אילו של יצחק היה:
@41 **מן ההר אל העם.** מלמד שלא היה משה פונה לעסקיו אלא מן ההר אל העם:
@42 **היו נכנים לשלשת ימים.** לסוף שלשה ימים, הוא יום רביעי שהוסיף משה יום אחד מדעתו, כדברי רבי יוסי, ולדברי האומר בששה בחדש נתנו עשרת הדברות לא הוסיף משה כלום. לשלשת ימים, כמו (פסוק יא) ליום השלישי: **אל תגשו אל אשה.** כל שלשת ימים הללו כדי שיהו הנשים טובלות ליום השלישי ותהיינה טהורות לקבל תורה שאם ישמשו תוך שלשת ימים, שמא תפלוט האשה שכבת זרע לאחר טבילתה ותחזור ותטמא, אבל מששהתה שלושה ימים כבר הזרע מסריח ואינו ראוי להזריע וטהור מלטמא את הפולטת:
@43 **בהית הבקר.** מלמד שהקדים על ידם מה שאין דרך בשר ודם לעשות כן, שיהא הרב ממתין לתלמיד, וכן מצינו ביחזקאל (יחזקאל ג כב) קום צא אל הבקעה וגו' , (שם כג) ואקום ואצא אל הבקעה והנה שם כבוד ה' עומד:
@44 **לקראת האלהים.** מגיד שהשכינה יצאה לקראתם, כחתן היוצא לקראת כלה, וזהו שנאמר (דברים לג ב) ה' מסיני בא, ולא נאמר לסיני בא: **בתחתית ההר.** לפי פשוטו ברגלי ההר. ומדרשו שנתלש ההר ממקומו ונכפה עליהם כגיגית:
@45 **עשן כלו.** אין עשן זה שם דבר, שהרי נקוד השי''ן פת''ח, אלא לשון פעל, כמו אמר, שמר, שמע, לכך תרגומו תנן כליה, ולא תרגם תננא, וכל עשן שבמקרא נקודים קמ''ץ מפני שהם שם דבר: **הכבשן.** של סיד, יכול ככבשן זה ולא יותר, תלמוד לומר (דברים ד יא) בער באש עד לב השמים. ומה תלמוד לומר כבשן, לשבר את האזן, מה שהיא יכולה לשמוע, נותן לבריות סימן הנכר להם. כיוצא בו (הושע יא י) כאריה ישאג, וכי מי נתן כח בארי, אלא הוא, והכתוב מושלו כאריה, אלא אנו מכנין ומדמין אותו לבריותיו, כדי לשבר את האזן מה שיכולה לשמוע. וכיוצא בו (יחזקאל מג ב) וקולו כקול מים רבים, וכי מי נתן קול למים, אלא הוא, ואתה מכנה אותו לדמותו לבריותיו, כדי לשבר את האזן:
@46 **הולך וחזק מאד.** מנהג הדיוט, כל זמן שהוא מאריך לתקע קולו מחליש וכוהה, אבל כאן הולך וחזק מאד. ולמה כך, מתחלה לשבר אזניהם מה שיכולין לשמוע: **משה ידבר.** כשהיה משה מדבר ומשמיע הדברות לישראל שהרי לא שמעו מפי הגבורה אלא (שמות כ ב) אנכי ולא יהיה לך והקדוש ברוך הוא מסיעו לתת בו כח להיות קולו מגביר ונשמע: **יעננו בקול.** יעננו על דבר הקול, כמו (מלכים א' יח כד) אשר יענה באש, על דבר האש להורידו:
@47 **וירד ה' על הר סיני.** יכול ירד עליו ממש, תלמוד לומר (שמות כ יט) כי מן השמים דברתי עמכם. מלמד שהרכין שמים העליונים והתחתונים והציען על גבי ההר, כמצע על המטה, וירד כסא הכבוד עליהם:
@48 **העד בעם.** התרה בהם שלא לעלות בהר: **פן יהרסו** וגו' **.** שלא יהרסו את מצבם על ידי שתאותם אל ה' לראות ויקרבו לצד ההר: **ונפל ממנו רב.** כל מה שיפול מהם ואפלו הוא יחידי חשוב לפני רב: **יהרסו.** כל הריסה מפרדת אסיפת הבנין, אף הנפרדין ממצב אנשים הורסים את המצב:
@49 **וגם הכהנים.** אף הבכורות שהעבודה בהם: **הנגשים אל ה'.** להקריב קרבנות, אף הם אל יסמכו על חשיבותם לעלות: **יתקדשו.** יהיו מזמנים להתיצב על עמדם: **פן יפרץ.** לשון פרצה, יהרוג בהם ויעשה בהם פרצה:
@50 **לא יוכל העם.** איני צריך להעיד בהם שהרי מתרין ועומדין הם היום שלשת ימים, ולא יוכלו לעלות שאין להם רשות:
@51 **לך רד.** והעד בהם שנית, שמזרזין את האדם קדם מעשה, וחוזרין ומזרזין אותו בשעת מעשה: **ועלית אתה ואהרן עמך והכהנים.** יכול אף הם עמך, תלמוד לומר ועלית אתה. אמור מעתה, אתה מחצה לעצמך ואהרן מחצה לעצמו והם מחצה לעצמם. משה נגש יותר מאהרן, ואהרן יותר מן הכהנים, והעם כל עיקר אל יהרסו את מצבם לעלות אל ה': **פן יפרץ בם.** אף על פי שהוא נקוד חטף קמ''ץ אינו זז מגזרתו, כך דרך כל תבה שנקדתה מלאפו''ם כשהיא סמוכה במקף משתנה הנקוד לחטף קמ''ץ:
@52 **ויאמר אליהם.** התראה זו:
@53 **וידבר אלהים.** אין אלהים אלא דין. לפי שיש פרשיות בתורה שאם עשאן אדם מקבל שכר, ואם לאו אינו מקבל עליהם פרענות, יכול אף עשרת הדברות כן, תלמוד לומר וידבר אלהים, דיין לפרע: **את כל הדברים האלה.** מלמד שאמר הקדוש ברוך הוא עשרת הדברות בדבור אחד, מה שאי אפשר לאדם לומר כן. אם כן מה תלמוד לומר עוד אנכי ולא יהיה לך, שחזר ופרש על כל דבור ודבור בפני עצמו: **לאמר.** מלמד שהיו עונין על הן הן ועל לאו לאו:
@54 **אשר הוצאתיך מארץ מצרים.** כדאי היא ההוצאה שתהיו משעבדים לי. דבר אחר לפי שנגלה בים כגבור מלחמה, ונגלה כאן כזקן מלא רחמים, שנאמר (שמות כד י) ויראו את אלהי ישראל ותחת רגליו כמעשה לבנת הספיר, זו היתה לפניו בשעת השעבוד, (שם) וכעצם השמים, משנגאלו, הואיל ואני משתנה במראות אל תאמרו שתי רשויות הן, אנכי הוא אשר הוצאתיך ממצרים ועל הים. דבר אחר לפי שהיו שומעין קולות הרבה, שנאמר, (להלן פסוק טו) את הקולות, קולות באין מארבע רוחות ומן השמים ומן הארץ, אל תאמרו רשויות הרבה הן. ולמה אמר לשון יחיד, אלהיך, לתן פתחון פה למשה ללמד סנגוריא במעשה העגל, וזהו שאמר (שמות לב יא) למה ה' יחרה אפך בעמך, לא להם צוית, לא יהיה לכם אלהים אחרים, אלא לי לבדי: **מבית עבדים.** מבית פרעה שהייתם עבדים לו. או אינו אומר אלא מבית עבדים, שהיו עבדים לעבדים, תלמוד לומר (דברים ז ח) ויפדך מבית עבדים מיד פרעה מלך מצרים, אמור מעתה עבדים למלך היו, ולא עבדים לעבדים:
@55 **לא יהיה לך.** למה נאמר, לפי שנאמר (פסוק ד) לא תעשה לך, אין לי אלא שלא יעשה, העשוי כבר מנין שלא יקים, תלמוד לומר לא יהיה לך: **אלהים אחרים.** שאינן אלהות אלא אחרים עשאום אלהים עליהם, ולא יתכן לפרש אלהים אחרים זולתי, שגנאי הוא כלפי מעלה לקרותם אלהות אצלו. דבר אחר אלהים אחרים, שהם אחרים לעובדיהם, צועקים אליהם ואינן עונין אותם, ודומה כאלו הוא אחר שאינו מכירו מעולם: **על פני.** כל זמן שאני קים, שלא תאמר לא נצטוו על עבודה זרה אלא אותו הדור:
@56 **פסל.** על שם שנפסל: **וכל תמונה.** תמונת כל דבר אשר בשמים:
@57 **אל קנא.** מקנא לפרע ואינו עובר על מדתו למחול על עוון עבודה זרה, כל לשון קנא אינפרינמינ''ט בלעז , נותן לב לפרע: **לשנאי.** כתרגומו, כשאוחזין מעשה אבותיהם בידיהם:
@58 **ועשה חסד.** נוצר חסד שאדם עושה, לשלם שכר עד לאלפים דור, נמצאת מדה טובה יתרה על מדת פרענות אחת על חמש מאות, שזו לארבעה דורות וזו לאלפים:
@59 **לשוא.** (השני לשון שקר כתרגומו) כמא דתימר (שבועות כט א) אי זהו שבועת שוא, נשבע לשנות את הידוע, על עמוד של אבן שהוא של זהב. (הראשון לשון מגן, כתרגומו) זה הנשבע לחנם ולהבל, על של עץ עץ ועל אבן אבן:
@60 **זכור.** זכור ושמור בדבור אחד נאמרו. וכן (שמות לא יד) מחלליה מות יומת, (במדבר כח ט) וביום השבת שני כבשים, וכן (דברים כב יא) לא תלבש שעטנז, (שם יב) גדילים תעשה לך, וכן (ויקרא יח טז) ערות אשת אחיך, (דברים כה ה) יבמה יבא עליה, הוא שנאמר (תהלים סב יב) אחת דבר אלהים שתים זו שמעתי. זכור לשון פעול הוא, כמו (ישעיה כב יג) אכול ושתו, (שמואל ב ג טז) הלוך ובכה, וכן פתרונו תנו לב לזכור תמיד את יום השבת, שאם נזדמן לך חפץ יפה תהא מזמינו לשבת:
@61 **ועשית כל מלאכתך.** כשתבא שבת, יהא בעיניך כאלו מלאכתך עשויה, שלא תהרהר אחר מלאכה:
@62 **אתה ובנך ובתך.** אלו קטנים. או אינו אלא גדולים, אמרת הרי כבר מזהרים הם, אלא לא בא אלא להזהיר גדולים על שביתת הקטנים, וזו ששנינו (שבת קכא א) קטן שבא לכבות אין שומעין לו, מפני ששביתתו עליך:
@63 **וינח ביום השביעי.** כביכול הכתיב בעצמו מנוחה ללמד המנו קל וחמר לאדם, שמלאכתו בעמל וביגיעה, שיהא נח בשבת: **ברך ויקדשהו.** ברכו במן לכפלו בששי לחם משנה, וקדשו במן שלא היה יורד בו:
@64 **למען יאריכון ימיך.** אם תכבד יאריכון, ואם לאו יקצרון, שדברי תורה נוטריקון הם נדרשין מכלל הן לאו ומכלל לאו הן:
@65 **לא תנאף.** אין ניאוף אלא באשת איש, שנאמר (ויקרא כ י) מות יומת הנואף והנואפת, ואומר (יחזקאל טז לב) האשה המנאפת תחת אישה תקח את זרים: **לא תגנב.** בגונב נפשות הכתוב מדבר. לא תגנבו (ויקרא יט יא) בגונב ממון. או אינו אלא זה בגונב ממון, ולהלן בגונב נפשות, אמרת דבר הלמד מענינו, מה לא תרצח, לא תנאף, מדבר בדבר שחייבין עליהם מיתת בית דין, אף לא תגנוב דבר שחיב עליו מיתת בית דין:
@67 **וכל העם ראים.** מלמד שלא היה בהם אחד סומא. ומנין שלא היה בהם אלם, תלמוד לומר (שמות יט ח) ויענו כל העם. ומנין שלא היה בהם חרש, תלמוד לומר (שמות כד ז) נעשה ונשמע: **ראים את הקולות.** רואין את הנשמע, שאי אפשר לראות במקום אחר: **את הקולת.** (מכילתא בחדש פ''ט) היוצאין מפי הגבורה: **וינעו.** (שם) אין נוע אלא זיע: **ויעמדו מרחק.** היו נרתעין לאחוריהם שנים עשר מיל כאורך מחניהם ומלאכי השרת באין ומסיעין אותן להחזירם, שנאמר (תהלים סח יג) מלכי צבאות ידדון ידדון:
@69 **לבעבור נסות אתכם.** לגדל אתכם בעולם שיצא לכם שם באמות שהוא בכבודו נגלה עליכם: **נסות.** לשון הרמה וגדלה, כמו (ישעיה סב י) הרימו נס, ארים נסי (ישעיה מט כב) , וכנס על הגבעה (ישעיה ל, יז) , שהוא זקוף: **ובעבור תהיה יראתו.** על ידי שראיתם אותו יראוי ומאים, תדעו כי אין זולתו ותיראו מפניו:
@70 **נגש אל הערפל.** לפנים משלש מחיצות, חשך ענן וערפל שנאמר (דברים ד יא) וההר בוער באש עד לב השמים חשך ענן וערפל, ערפל הוא עב הענן, שנאמר לו (שמות יט ט) הנה אנכי בא אליך בעב הענן:
@71 **כה תאמר.** בלשון הזה: **אתם ראיתם.** יש הפרש בין מה שאדם רואה למה שאחרים משיחין לו, שמה שאחרים משיחין לו פעמים שלבו חלוק מלהאמין: **כי מן השמים דברתי.** וכתוב אחד אומר וירד ה' על הר סיני, בא הכתוב השלישי והכריע ביניהם (דברים ד לו) מן השמים השמיעך את קולו ליסרך ועל הארץ הראך את אשו הגדולה, כבודו בשמים ואשו וגבורתו על הארץ. דבר אחר הרכין שמים ושמי השמים והציען על ההר, וכן הוא אומר (תהלים יח י) ויט שמים וירד:
@72 **לא תעשון אתי.** לא תעשון דמות שמשי המשמשים לפני במרום: **אלהי כסף.** בא להזהיר על הכרובים, שאתה עושה לעמוד אתי, שלא יהיו של כסף, שאם שניתם לעשותם של כסף הרי הן לפני כאלהות: **ואלהי זהב.** בא להזהיר שלא יוסיף על שנים, שאם עשית ארבעה, הרי הן לפני כאלהי זהב: **לא תעשו לכם.** לא תאמר הריני עושה כרובים בבתי כנסיות ובבתי מדרשות כדרך שאני עושה בבית עולמים, לכך נאמר לא תעשו לכם:
@73 **מזבח אדמה.** מחבר באדמה, שלא יבננו על גבי עמודים או על גבי כפים. דבר אחר שהיה ממלא את חלל מזבח הנחשת אדמה בשעת חניתן: **תעשה לי.** שתהא תחלת עשייתו לשמי: **וזבחת עליו.** אצלו, כמו (במדבר ב כ) ועליו מטה מנשה. או אינו אלא עליו ממש, תלמוד לומר (דברים יב כז) הבשר והדם על מזבח ה' אלהיך, ואין שחיטה בראש המזבח: **את עלתיך ואת שלמיך.** אשר מצאנך ומבקרך. את צאנך ואת בקרך, פרוש לאת עולתיך ואת שלמיך: **בכל המקום אשר אזכיר את שמי.** אשר אתן לך רשות להזכיר שם המפרש שלי, שם אבא אליך וברכתיך אשרה שכינתי עליך מכאן אתה למד שלא נתן רשות להזכיר שם המפרש אלא במקום שהשכינה באה שם, וזהו בית הבחירה. שם נתן רשות לכהנים להזכיר שם המפרש בנשיאת כפים לברך את העם:
@74 **ואם מזבח אבנים.** רבי ישמעאל אומר כל אם ואם שבתורה רשות, חוץ משלשה ואם מזבח אבנים תעשה לי, הרי אם זה משמש בלשון כאשר, כאשר תעשה לי מזבח אבנים לא תבנה אתהן גזית שהרי חובה עליך לבנות מזבח אבנים, שנאמר (דברים כז ו) אבנים שלמות תבנה, וכן (שמות כב כד) אם כסף תלוה, חובה הוא, שנאמר (דברים טו ח) והעבט תעביטנו. ואף זה משמש בלשון כאשר וכן (ויקרא ב יד) ואם תקריב מנחת בכורים זו מנחת העמר, שהיא חובה, ועל כרחך אין אם הללו תלוין, אלא ודאין, ובלשון כאשר הם משמשים: **גזית.** לשון גזיזה שפוסלן ומסתתן בברזל: **כי חרבך הנפת עליה.** הרי כי זה משמש בלשון פן, שהוא דילמא, פן תניף חרבך עליה: **ותחללה.** הא למדת, שאם הנפת עליה ברזל חללת, שהמזבח נברא להאריך ימיו של אדם, והברזל נברא לקצר ימיו של אדם, אין זה בדין, שיונף המקצר על המאריך. ועוד, שהמזבח מטיל שלום בין ישראל לאביהם שבשמים, לפיכך לא יבא עליו כורת ומחבל. והרי דברים קל וחמר ומה אבנים שאינם רואות ולא שומעות ולא מדברות על ידי שמטילות שלום אמרה תורה לא תניף עליהם ברזל, המטיל שלום בין איש לאשתו, בין משפחה למשפחה, בין אדם לחברו, על אחת כמה וכמה שלא תבואהו פרענות:
@75 **ולא תעלה במעלות.** כשאתה בונה כבש למזבח, לא תעשהו מעלות מעלות אישיקלונ''ש בלעז [מדרגות] אלא חלק יהא ומשופע: **אשר לא תגלה ערותך.** שעל ידי המעלות אתה צריך להרחיב פסיעותיך, ואף על פי שאינו גלוי ערוה ממש, שהרי כתיב (שמות כח מב) ועשה להם מכנסי בד, מכל מקום הרחבת הפסיעות קרוב לגלוי ערוה הוא, ואתה נוהג בהם מנהג בזיון. והרי דברים קל וחומר ומה אבנים הללו שאין בהם דעת להקפיד על בזיונן אמרה תורה הואיל ויש בהם צורך, לא תנהג בהם מנהג בזיון, חברך שהוא בדמות יוצרך, ומקפיד על בזיונו, על אחת כמה וכמה:

@2 **אחר שלוחיה.** ר"ל אחר ששלחה לביתה בהיותה במלון והוצרכה למול בנה ולהתעכב שם ואז אמר אליה שתשוב אל בית אביה עם בניה כי לא יוכל משה להתעכב שם עד ירפא הנער:
@3 **אמר** שכבר שמע יתרו כל אשר עשה אלהים למשה ולישראל עמו מהנפלאות כאשר הוציא את ישראל מיד מצרים והנה שמע לפי זה הפירוש מכת בכורות. ומה שפסח השם יתעלה על בתי בני ישראל לבלתי היות שם נגף למשחית ומה שהשאילום המצרים בצאתם כלי כסף וכלי זהב ושמלות כי נתן יי' חן העם בזה בעיני מצרים כי אלו הנפלאות עשה יי' יתעלה כאשר הוציאם ממצרים וידמה שלא היה נכון בעיניו הדבר כי לא יהיה זה מהיושר בחוק יי' כשלא יודע בו יותר מזה השיעור ולזה שב משה לספר ליתדו את כל המכות אשר הביא השם יתעלה על פרעה ועל מצרים בהדרגה ואת כל התלאה אשר מצאתם בדרך מרדיפת פרעה וחילו אחריהם וממלחמת עמלק ואז הודה יתרו לשם יתעלה וכרך אותו וראה כי ביושר הביא הש"י על המצרים מה שהביא מהרעות:
@4 **ויצילני מחרב פרעה.** אמר זה כי הוא היה מבקש להרגו כמו שנזכר בפשרת ואלה שמות:
@5 **אל המדבר אשר הוא חונה שם הר האלהי'.** ר"ל אל מדבר סיני שהיה חונה שם משה שהיה בו הר האלהים והוא הר סיני שנגלה עליו השם יתעלה והנה יהיה אמרו אל המדבר אשר הוא חונה על דרך מה שאמר קרית חנה דוד והנה זה ראיה שזה היה אחר מתן תורה כמו שכתב החכם אבן עזרא ואולם בא זה הספור בזה המקום בעבור מה שאמר יתרו עתה ידעתי כי גדול יי' כי זה יורה שהנפלאות שעשה השם יתעלה יתחייבו להאמין אל כל מי שישמע אותם כ"ש למי שראה אותם והנה לזאת הכוונה נתחדשו אלו הנפלאות כמו שקדם ר"ל שיאמינו ישראל בשם יתעלה כדי שיוכנו לקבול התורה ולזה בא זה הספור קודם מתן תורה ועוד כי סמיכות זה הספור לספיר מתן תורה יעיר אותנו למצוא הסבה אשר בעבורה פירש משה מן האשה שהיו תמהים מזה אהרן ומרים ואמרו הרק אך במשה דבר יי' הלא גם בנו דבר וזה כי הוא זכר בזה הספור שוב אשתו אליו וזכר אחר זה בספור מתן תורה מה שצוו ישראל שיהיו נכונים לשלשת ימים לא יגשו אל אשה וזה ממה שיתבאר ממנו במעט עיון שכבר היה ראוי למשה שיפרש מהאשה כי הוא היה תמיר עם השם יתעלה ויאמר אל משה אני חותנך יתרו בא אליך. יתכן ששלח לו זה על ידי שליח:
@7 **וישתחו וישק לו.** יראה מפשט הכתוב כי משה השתחוה ליתרו חמיו והיה זה מגודל הענוה שהיתה למשה:
@9 **ויחד יתרו על כל הטובה שעשה יי' לישראל.** הרצון כי כבר שמח יתרו על כל הטובה שעשה יי' לישראל כי היא היתה הכוונה ברע שביא השם על מצרים ולא שמח ברע שהביא על המצרים מצד מה שהוא רע להם אבל מצד שהוא טוב לישראל כי אין מחוק השלם לשמוח על הרע מצד שהוא רע:
@10 **ויאמר יתרו ברוך יי' אשר הציל אתכם מיד מצרים ומיד פרעה.** יתכן שאמר זה אל הזקנים וראשי העם שהיו שם עם משה שלא העמיסו עליהם המצרים העבודה בחומר ובלבנים כי לא נכנסו כל ישראל בזאת העבודה כמו שבארנו בפרשת ואלה שמות והנה הצילם מיד מצרים ומיד פרעה שהיו מכאיבים ומכים אותם כאמרו וירא איש מצרי מכה איש עברי מאחיו ושוטרי בני ישראל תמצא גם כן שהיו מוכים וזה לאות כי מנהגם הזה לחכות העבדים ולצערם עם שכבר היו משתדלים להמית כל הבן הילוד לישראל ולזה אמר אחר זה אשר הציל את העם מתחת יד מצרים כי העם היו חת ידם לענותם בסבלותם ואפשר כי קצת ראשי העם והזקנים היו גם כן עובדים את העבודה אבל נתן יתרו תודה לשם יתעלה בתחלה על הצלתו ראשי העם והזקנים כי הם הנכבדים שבעם ואחר כן נתן תודה על הצלתו עם. וזה הביאור השני הוא יותר נכון לפי מה שאחשוב כי גדול יי' מכל האלהים הוא כטעם מי כמוך באלים כי בדבר אשר זדו עליהם הוא שב אל מה שאמר אשר הציל את העם והרצון בזה שהשם יתעלה הציל ישראל בדבר בעינו אשר חשבו המצרים עליהם להשחיתם וזה כי המצרים היו רודפים אחרי בני ישראל על שפת הים כדי שיטבעו או יפלו בידם כי לא היה להם מנוס אך הים היה מהצד האחד והמצרים הרודפים אחרים מהצד השני ובדבר ההוא בעינו שחשבו להשחיתם בו נשלמה ההצלה לישראל כי זה היה סבה אל שטבעו המצרים בים ופחדו המצרים מרדוף עוד אחרי בני ישראל והנה יהיה אמרו אשר זדו עליהם כטעם וכי יזיד איש על רעהו:
@12 **עולה וזבחים.** זה ראיה שכבר נעשה המזבח והוקם המשכן כשהיה זה המעשה:
@12 **לאכול לחם עם חותן משה לפני האלהים.** אפשר שהיה אהל משה אצל אהל מועד כמו שאמר החכ' א"ע או אמר לפני האלים ע"ד אמרו הר האלהים מפני רדת השכינה בהר ולהיות השכינה תמיד באהל משה אמר שהם היו אוכלים להם עם חותן משה לפני האלהים או ירצה בזה כי בעת אכלם הלחם היו לפני האלהים ר"ל שהיו משתדלים בעבודתו ולקרבה אליו כפי מה שאפשר כי משה רבינו היה מישירם על זה:
@13 **וישב משה לשפוט את העם.** הנה זה היה מהראוי כי השופט ראוי שיהיה יושב כדי שיתישב יותר בענין המשפט שבא לפניו:
@13 **ויעמוד העם על משה מן הבקר עד הערב.** הנה מן היושר שיהיו בעלי דינין עומדים כדי שלא יתישבו למצא טענות ידחו בהם האמת ולזה היה ראוי שידברו מה שידברו בזולת התיישבות ומפני זה אמרה התורה ועמדו שני האנשים אשר להם הדים והנה היו עומדים מהבקר עד הערב לרבוי הבעלי דינין הבאים לפניו בעם רב כזה כשלא יהיו בו כי אם שופט אחד ולזה תמה יתרו מדוע לא שם משה שפטים אחרים על העם להקל מעליו ולזה אמר מדוע אתה יושב לבדך שלא יהיה שם שופט אחר זולתך כי זה יהיה סבה שכל העם נצב עליך כל היום שמי שבא לפניך לדין לא יוכל להשמיע דבריו אליך תכף אבל יצטרך לפעמים להמתין מבקר עד ערב לרבוי הטענות הבאות לפניך ואמר משה לחותנו הנה לא אוכל לשים על העם מי שיקל מעלי וזה כי כבר יבא אל העם בהכרח לדעת בנבואה מה שישאלו ממני והנה יהיה לדרוש כטעם ותלך לדרוש את יי' ובלי ספק אין בעם מי שיקל מעלי בזה והנה בענין הדינים אשר ביניהם לא אוכל גם כן לשים עליהם מי שיקל מעלי וזה כי כאשר יהיה להם ריב קצתם עם קצם יבא אלי לשפוט בין איש ובין רעהו ואשפוט אותם לפי מה שהתחייב ממצות התורה וזה לא יוכל לעשות אחר זולתי ואודיע גם כן להם חקי האלהים ותורותיו וזה לא יוכל עשות אחר זולתי כי לי לבד יבואו מצות התורה ובנבואה והנה זכר חקי האלהים ותורותיו לפי שלא יתכן שיודעו לאדם מדרך החכמה והעיון ואולם המצות אשר יחייבם השכל בעצמותם יתכן שידע האדם דיניהם בזולת התורה:
@17 והשיב חותן משה אליו **לא טוב הדבר אשר אתה עושה** הנה ישיגך לאות נפלא כזה ולכל העם אשר עמך כי אתה לא תוכל לדון לבדך כל דברי ריבותם והם יראו להביא כל דברי ריבותם אליך בדרך שתשפוט ביניהם עד שמרוב הלאות אלי תפריד הדבקות אשר בינך ובין השם יתעלה בדרך שלא תבא אליך הנבואה כאשר ישאלוך.
@19 **עתה שמע בקולי** ואתן לך עצה בדרך שיהיה אלהים עמך תמיד ולא תפריד הדבקות אשר בינך ובינו מצד רבוי הלאות בדברי ריבות העם היה אתם לעם אצל השם יתעלה ר"ל שלא תטריד מחשבתך בדבר אחר והבאת אתה לפני האלהים את הדברים אשר ישאלוך על צד הנבואה ותבאך הנבואה מצד הדבקות שיהיה לך תמיד עם השם יתעלה והזהרת אתהם את החקים ואת התורות והם מצות לא תעשה שלא יתכן שיודעו כי אם על צד הנבואה:
@20 **והודעת להם את הדרך ילכו בה.** במנהגיהם ובתכונותיהם כמו אהבת הרעים והשמר מהנקימה והנטירה ומה שידמה לאלו המצות:
@20 **ואת המעשה אשר יעשון.** והם מצות עשה אשר יהיה בקיומן מעשה כמו אכילת מצה וישיבת סוכה והנחת תפילין והתעטף בציצית ומה שידמה להם מהמצות המעשיות ואתה תבחר מכל העם בדרך נבואה אנשי חיל שיהיה להם אבירות לב ולא ייראו מאדם כדי שלא יעוותו המשפט מפני היראה ותהיה יראת השם יתעלה על פניהם כי כמו אלו ראוי שישפטו דין אמת ויהיו אנשי אמת ר"ל שיהיו אוהבי האמת כי בכאן תכונות לקצת האנשים לאהוב השקר מן האמת והם האנשים ההטעיים בטבע כמו שזכר הפילוסוף והנה אוהבי האמת יחקרו בריב הבא לפניהם חקיר' שלמה לדון דין אמת לאמתו לרוב אהבתם האמת ויהיו שונאי בצע ר"ל שונאים הגזל והעושק אלא שכבר יקשה לזה הפירוש מדוע התנה זה התנאי כי אחר שהם ירירי אלהים אין ספק שהם שונאים הגזל והעושק ולזה ידמה שיהיה בצע מענין תועלת הממון כטעם מה בצע כי בהרוג את אחינו והרצון בזה שהם אוהבי האמת באופן שישנאו בעבורו הממון באופן שלא יעלים מהם אהבת הממון אמתת דרך הדין. ואולם שזאת התכונה היא ראויה לשופט הנה יתע' ממה שאומר וזה שאם היה האדם אוהב ממונו מאד הנה כאשר תהיה לאחר טענת ממון עליו תמנע ממנו אהבת הממון לחקור אשר עם לבו באופן שלם אם יש זכות לחברו עליו ומי שינהג זה המנהג לא יתכן שיהיה שופט כי זה יהיה מבא לשפוט בין האנשים בזולת יושר וזה כי האדם תמצאהו על הרוב אוהב יותר קצת האנשים מקצת. ולה תמצא שיהיו מריבים שני בני אדם ויבחר הרואה אותם שינצח האחד יותר מן האחר ואם לא ראה אותם קודם זה כ"ש כשראם קודם ונשא ונתן עמהם שכבר יתכן שיהיה שם שתי סבות מביאות לאהוב האחד ולשנא האחר או לאהוב האחד יותר מהאחר הרבה ואין ספר שכאשר יאהבהו השופט יותר יאהב ממונו יותר. ולזה תעלים ממנו אהבת הממון אמתת הדין הנה יקרה מזה שלא ישפוט על נכון ולזה אמרו במכילתא שונאי בצע ששונאים ממונם בדין כ"ש ממון אחרים וזה אצלנו מה שאמר שונאי בצע ששונאים ממונם בדין כי ההיא דאמרינן כל דיינא שמפיקין מיניה ממונא בדינא לאו דיינא הוא ר"ל שאם לא ישנא ממונו בעבור דין האמת הנה תעלי' ממנו אהבת ממונו אמתת הזכות שיש לחברו עליו. ולזה לא ירצה לתת לחברו מה שישאלוהו לחשבו שאין לו זכות עליו וכאשר יקראהו חברו לדין יכיר השופט כי יש לחברו זכות עליו ויוציאהו ממנו ומי שזה דרכו אין ראוי שיהיה דיין שאם העלים ממנו אהבת ממונו האמת כן יעלים ממנו האמת לפעמי' אהבו ממון חברו:
@21 **ושמת עליהם שרי אלפים ושרי מאות.** פירשו רבותינו במכילתא ובמסכת סוטה ששרי אלפים היו שרים לאלף ושופטים אותם והם היו שש מאות לשש מאות אלף. ובזה האופן היו שרי מאות ששת אלפים ושרי חמשים י"ב אלף ושרי עשרות ששים אלף. והנה קשה לזה הפירוש איך יתכן שימצאו כמו זה המספר הרב מהאנשים שיהיו בהם כל אלו התכונות כמו שכתב החכם א"ע. והחכם א"ע פירש שרי אלפים שרים שיש להם משרתים ובני בית ושכירים אלף וכן על זה הדרך והנה יקשה לזה הפירוש גם כן אם היה מתנאי אלו השופטים שיהיו שרי אלפים או שרי מאות או שרי חמשים או שרי עשרות הנה היה ראוי שיאמר שונאי בצע שרי אלפים ושרי מאות שרי חמשים ושרי עשרות ושמתם עלליהם לא שיפסיק לומר ושמתה עליהם קידם שיזכיר כל התנאים וכן תמצא גם כן שאמר אחר זה ויבחר משה אנכי חיל מכל ישראל גוו'. וכזה גם כן תמצא בפרשת אלה הדברים אמר ואקח את ראשי שבטיכם וגו'. ולזה ידמה שמשה שם אותה שרי אלפי שרי מאות שרי חמשים ושרי עשרות והנה הענין לפי מה שאחשוב שמשה בחר מהם אחד אחד לשבט מהיותר נכבדים ושם אותם שרי אלפים כדי שיהיו חזקים ותקיפים להכריח האנשים לקבל דינם ותחתיהם שם דיינים אחרים נכבדים ושם אותם שרי מאות וכן בזה האופן בדרך שיוכלו השופטים לשפוט בין איש ובין רעהו בזולת טורח ושפטו את העם בכל עת כי לא יבואו לפניהם דברי ריבות רבים ולזה לא יצטרכו הבאים לפניהם להתעכב שם והיה כל הדבר הגדול שלא ידעו משפטו יביאו אליך ואתה תודיע להם משפטו וכל הדבר הקטן ישפטו הם ויקלו מעליך ונשאו אתך ויהיה והקל מקור לא צווי:
@23 **אם את הדבר הזה תעשה.** הנה לא תמנע נבואתך אך יצוה ה' אותך מצות התור' ותוכל לעמוד עם הש' יתע' ולהפנות מחשבתך משאר הענינים או יהיה פירוש ויכלת עמוד הפך נבול תבול. או ירצה אם את הדבר הזה תעשה ויסכים בו השם יתעלה ויצוך עליו ויכלת עמוד וגם כל העם הזה איש על מקומו יבא בשלום תכף שיבואו לדין ישמע הדיין דבריהם וישפוט ביניהם ותסור מפני זה המחלוק' והקטטה מביניהם והנה זכר שכבר שמע משה לקול חותנו וזכר עם זה שכבר לוח משה חותנו לכבודו והלך לו אל ארצו והנה בפרשת בהעלותך זכר בשלמות דברי משה לחותנו ובקש ממנו שילך את ישראל וייטיבו לו:
@28 **בחדש** הוא יום ראש חדש בעצמו והעד מה שאמר ביום ההוא באו מדבר סיני ולזה יאמר החדש בשני פנים. האחד על הזמן אשר מחדש לחדש כמו חדש ימים. והשני על יום ראש החדש וכן יאמר השבת על יום השביעי מהשבוע ויאמר על כל השבוע אמר שבע שבתות תמימות תהיינה. ולפי שזה יורה כי לכל הפחות יהיה מתן תורה ביום השלישי לחדש השלישי והוא קרוב לזמן חג השבועות כי הוא בששה בסיון ויהיה אפשר שיהיו ישראל חונים שם שלשה ימים מה שאמר להם משה היו נכונים לשלשת ימים. הנה ראוי שנאמין כי יום מתן תורה היה בששה בסיון ועוד כי הו' מן השקר שתשאיר לנו התורה רושם וזכר לעת שיצאנו ממצרים לעשות בו חג הפסח ולא תשאיר לנו רושם וזכר לעת שנתנה בו התורה בזה האופן הנפלא ולזה הוא מבואר שחג השבועות הוא בעת מתן תורה והיה זה בהזכירנו ענין מתן לתורה הנפלא להעמידנו תמיד על האמונה בדבר תורה:
@29 **ויחנו במדבר ויחן שם ישראל נגד ההר.** ירצה לפי מה שאחשוב שהם חנו במדבר וחנו ממנו במקום שהיה אצל ההד כי שם הוליך אותם עמוד הענן ואפשר עוד שיהי' הרצון בזה כי ביום החדש באו מדבר סיני וזה שכבר נסעו מרפידים ביום ההוא ובאו מדבר סיני וחנו שם ביום ההוא בעינו. והנה ספר זה לפי מה שאחשוב להיות המרחק רב בין רפידים ובין מדבר סיני כמו שזכר החכם ר"ע. ועם כל זה הגיעו במדבר סיני ביום ההוא בעינו ולזה חנו שם במדבר שלא להטריחם יותר מן הראוי ואחר שכבר חנו שם זמן מה שבו לחנות נגד ההר כי עמוד הענן ועמוד האש הוליך אותם שם על פי יי' ואז עלה משה אל האלהים אל הר סיני כי ידע כי שם יתן השם יתע' תורה לישראל ושם באתהו הנבואה מהשם יתע' ואמר אליו כה תאמר לבית יעקב ותגד לבני ישראל והנה כפל הענין במלו' שונות כמו אחלקם ביעקב ואפיצם בישראל והנה היה רצון השם יתע' שיאמר זה לאשר יבינו דבריו ולזה אמר זה משה לזקני ישר' והם אחר זה הגישו הדברים אל כל העם באופן שיבינו אותם אתם ראיתם הנפלאו' העצומות שעשיתי במצרים בעבור שתדעו כי אני יי' ותאמינו בי עד שכבר העתקתי אתכם מאמונותיכם הנפסדות והבאתי אתכם לעבודתי בתכלית המהירות במה שחדשתי לכם מהמופתים הנפלאים כאלו נשאתי אתכם על כנפי נשרים שהם ממהרים לעוף:
@32 **ועתה אם שמוע תשמעו בקולי.** לקיים מצותי ושמרתם בריתי אשר אני כורת עמכם להיות לי לעם ולקיי' דברי התורות בכללם והוא הברית הנזכר בסוף פרשת ואלה המשפטים הנה תהיו לי סגולה מכל העמים לשמר אתכם ולהשגיח בכם כי לי כל הארץ לעשות בה כחפצי ולזה אוכל לשמור אתכם מכל רע מצד יתרון השגחתי בכם ויהיה אמרו כי לי כל הארץ על דרך אמרו למען תדע כי ליי' הארץ ולא תחשבו שיהיו דברי תורותי אשר אצוה אתכם עומסים עליכם מעמס כבד ומנהיגים אתכם בשפלות ובבוז פי לא אעביד אתכם בעבודה קשה אבל אשים אתכם בני חורין ונכבדים בדרך שתהיו ממלכת כהנים ושרים וגוי קדוש לבלתי התגאל בפעולות המגונות אשר יתנהגו בהם שאר האומות כמו שאמר ועתה ישראל מה יי' אלהיך שואל מעמך כי אם ליראה:
@33 **אלה הדברים אשר תדבר אל בני ישראל.** כי בזה בלי ספק ראוי שיסכימו לקבל התורה ר"ל מפני התועלת הנפלא שיגיע ממנה להם עם זה שלא יכבד להם עניינה אבל יערב להם והנה בא משה מן ההר אל המחנה וקרא לישראל ואמר להם הדברים האלה אשר צוהו יי' והם הגישו הדברים לכל העם וענו כל העם יחדיו כל אשר דבר יי' נעשה:
@35 **וישב משה את דברי העם אל יי'.** ראוי שתדע כי הידיעות כלם הם אצל השם יתע' וישפיע לנביא אחת מהם זולת האחרת מצד הנביא כי מצד השם יתע' ישפיע לו יחד כלם אם היה אפשר זה במקבל ואולם תתיחד הידיעה בקצת הענינים מקצת מצד מה שתשוטט בו מחשבת הנביא כמו שביארנו בשני ממ"י ולזה מפני שהיה יחוד ההודעה מצד הנביא היה ראוי שיגיד הנביא מה ששוטטה מחשבתו בו וזה כלו במראה הנבואה כי ידמה לנביא ענין הגעת ענין הנבואה לו כאלו ישאל ויענה וזה אמנם יהיה באמצעות הדמיון וכבר תעמוד על אמתת זה מההשפעה אשר תהיה בחלומות הצודקים כי כבר תמצא פעמים רבות בזה האופן והנה מה שאמרו ישראל כל אשר דברר יי' נעשה היה אפשר שיובן על שני פנים. האחד שיהיה להם אות כי השם יתע' מדבר עמו אלו הדברים אשר יצוה אותם עליהם ויהיה הרצון מאמרו כל אשר דבר יי' נעשה אבל רצונינו שיתברר לנו שדבר יי' לך. והשני הוא שיהיה הדבור דבור השם יתע' לא דבור משה וזה כי אע"פ שיתברר להם שהשם מדבר עמו לא יתברר להם שיהיה הדבור אשר ידבר להם משה הוא הדבור אשר דבר אליו השם יתעלה והנה לא היו ישראל סכלים שירצו שידבר להם השם יתעלה בעצמו כי זה בלתי אפשר להם אבל רצו שיתחדש על דרך מופת מהשם יתע' מה שיודיע להם רצון השם יתעלה מזולת שישמעו זה מפי משה כמו שהכירו ענין מצות שבת מפני דמן קודם שישמעו זה מפי משה והנה השיב משה דברי העם אל יי' והבין אותם משה אז לפי האופן הראשון רוצה לומר שהם רצו שיהיה להם אות יעוד להם כי השם יתע' מדבר עמו ואז יעשו כל אשר דבר יי' לו ובאתהו התשובה מהשם יתע' לפי מה שהבין אותו משה מדבריהם לסבה שזכרנו במה שקדם ואמר אליו הנה אנכי בא אליך בעב הענן בעבור יראה העם בדברי עמך וגם בך יאמינו לעולם במה שתדבר להם בשמי אחר שכבר יתפרסם להם שאנכי מדבר עמך והנה פירשנו ישמע יראה לפי שהחושים יבואו קצם תחת קצת לפעמים אמר ראה ריח בני:
@40 **לא תגע בו יד.** רוצה לומר בהר סיני כי לכבוד שם יתע' יחוייב שייראו מגעת בו כלל לא ביד ולא ברגל והנה מי שלא ישמר מזה יהיה נסקל על יד בית דין או יהיה מושלך ממקום גבוה אם בהמה אם איש שיגע בהר לא יחיה אבל יהיה נסקל על יד בית דין והנה הבהמה כוללת בהמה וחיה כמו שנבאר ברשת שמיני. וראוי שתדע כי גם האשה היתה בכלל כמו שאמרו במכילתא כי מן השקר שינהג זה הדין באיש ובבהמה ולא ינהג באשה ולזה כי האשה לחסרונה הוא יותר ראוי שתרחק מההר אשר ירד השם בו מה שהתמידה השכינה להראות מהאיש ולזה תמצא כי משה ואהרן לשלמותם עלו אל ההר כי הם היו קרובים מהש' יתע' ומזה המקום למדנו שההשלכה ממקום גבוה דינה כדין הסקילה בשוה והטעם כי בסקילה הוא שיוכה האדם באבנים או במה שידמה להם וזאת ההכאה כבר תהיה בשני פנים אם שיעתיקו האבנים וישליכום על המוכה או שישליכו אותו עליהם או על מה שינהג מנהגם כי באלו השני פנים תגיע לו ההכאה ולפי שראוי שנבחר לדון במיתה הקלה שבמיתות אשר בסוג ההוא כמו שנבאר בג"ה במה שיבא הנה ראוי שננהג בנסקלים זה המנהג רוצה לומר שנשליכם ממקום גבוה בדרך שימותו ולה היו דנין הנסקלים בזה האופן כמו שנתבאר בסנהדרין:
@40 **במשוך היובל המה יעלו בהר.** הנה היובל הוא השופר שהוא מקרן הכבש כי היובל הוא כבש כמו שנתבאר במסכת ר"ה והנה הרצון באמרו במשוך היובל כאשר יתקע משה בשופר ואז יוכלו ישראל לעלות בהר וידמה שכבר תקע משה בשופר כשנסתלקה השכינה משם כמו שפירש הגאון לפי מה שכר ממנו החכם אבן עזרא וכן תמצא שאמר בספר יהושע במשוך בקרן היובל כשמעכם את קול השופר:
@42 **היו נכונים לשלשת ימים.** הוא לפי הפשט מה שאמר לו השם יתעלה היו נכונים ליום השלישי כמו שפירש החכם אבן עזרא. ולזה אמר אחר זה ויהי ביום השלישי להורו' כי מה שאמר להם היו נכונים לשלשת ימים הרצון בו ליום השלישי וכזה תמצא שאמר ויאסוף אום אל משמ' שלשת ימי' ואחר כך זכר כי ביום השלישי התירם ממאסרם ואסר שמעון לעיניהם וכבר הביא זה הענין החכם אבן עזרא לראיה על פירושו ובכלל הנה יום מתן תצורה היה מוגבל מהשם יתע' שיהיה ביום החמישים אחר יום ראשון של פסח כי בזה היום צוה השם שיהיה חג שבועות ולה לא יתכן שיכוין השם יתעלה אל יום אחד ויוסיף משה מדעתו וישנה העניין ליום אחר ואולם אמרו זה רז"ל על צד הדרש להוציא מזה המקום דין פולטת שכבת זרע כמו שנזכר במסכת שבת:
@43 **ויהי ביום השלישי בהיות הבקר.** המציא השם יתע' על הר סיני בדרך המופת קולות וברקים נפלאים וכבר תמצא בזה האופן ענן כבד היה בו איד קטורי בדרך שחדש קולות מרעידים וברקים נפלאים וחדש גם כן שם ע"ד המופת קול דומה לקול שופר והיה חזק מאד וזה בתכלית הפלא רוצה לומר שיתחדש קול השופר מזולת שופר אלא שמציאות קול השופר אינו נמנע מצד עצמותו ואולם מה שהוא בלתי אפשר אצל הטבע הוא שיתחדש קול שופר מזולת שופר או מה שיאות לו וה הוא המופת אשר היה בזה והוא אצלנו במדרגת התחדש הנחש מהמטה שהוא נמנע אצל הטבע אלא שמציאות הנחש אינו נמנע בעצמותו והנה חרד כל העם אשר במחנה מאלו הקולות הנפלאים:
@44 **ויוצא משה את העם מן המחנה.** והושיבם בתחתית ההר ר"ל אצל תחתית ההר כדי שיראו אלו הנפלאות וישמעו דברי השם יתע' מתוך דברי האש והנה אמר לקראת האלהים לפי ששם נראה כבודו במה שחדש שם מהנפלאות העצומות והנה עלה עשן נפלא מכל הר סיני לפי שכבר ירד עליו כבוד השם יתעלה באש ונתחדש בהר בדמות רעש וחרדה בדומיון מה שיתחדש בארץ אשר נסגר בה איד קטורי וזה כלו חדש השם יתע' אז על דרך המופת:
@46 **ויהי קול השופר הולך וחזק מאד משה ידבר והאלהים יעננו בקול.** ירצה לפי מה שאחשוב כי קול השופר היה הולך ומתחזק מאד וזה היה ענין בתכלית הפלא ועוד נתחדש שם פלא אחר כי משה היה מדבר עם השם יתע' וכשהיה מגיע לו מענה מהשם יתעלה בנבואה היה מתחדש אז קול דברים מוחש ישמעו אותו ישראל ויתברר להם שהשם יתע' מדבר עמו והנה חדוש קול הדברים בזולת כלי הדבור הוא אצלנו כחדוש הנחש מהמטה וזה כי מציאות קול דברים אינו נמנע מצד עצמותו אבל הוא נמנע מצד הטבע שיתחד' בזולת כליו ולזה היה חדושו על דרך המופת ואחר שהשלים לזכור הנפלאות שחדש שם השם יתע' במעמד הר סיני שב לספר מה שצוה השם יתע' למשה אז ומה שהשיב לו משה ומה שענה אותו השם יתע' שהיה המענה ההוא בקול כמו שקדם:
@48 **רד העד בעם.** להזכיר אותם שלא יהרסו להתקרב אל ההר לראות כבוד השם יתעלה שירד על הר סיני באופן שיגעו בהר שמא לרוב תשוקתם לראות זה הענין הנפלא לא יתנו אל לבם לזכר מה שצוה שלא יגעו בהר ויהרסו רבים מהם לעלות ויהיה זה סבה אל שיומתו רבים מהם בסקילה:
@49 **וגם הכהנים הנגשים אל יי'.** ידמה שכבר קרא כהנים בני אהרן על שם העתיד ובזה האופן בעינו קראם נגשים אל יי' כי הם היו הכהנים ונגשים אל יי' בכח ואם לא היו עדיין כהני' בפועל וכן פירשו ז"ל במכילתא. וכזה תמצא שאמר הכתוב מבכור פרעה היושב על כסאו על שם העתיד והנה הזהיר אותם שיתקדשו וישמרו מעלות בהר ונגוע בקצהו פן יפרוץ בהם השם יתע' וימיתם במגפה לפי שהם אולי לא ישמרו מעלות בהר מפני ראותם שמשה ואהרן עולים בו. והנה מה משה מדוע הוסיף הש' יתע' לצוות ישר' שלא יהרסו לעלות ואמר הנה באמת לא יוכל העם לעלות אל הר סיני כי אתה העדות בנו לאמר הגבל את ההר וקדשתו לרשום בו גבול שלא יעברו ישראל הגבול ההוא ואמר משה לשם מה צורך יש בצווי הזה הלא כבר הגבלתנו וצוויתנו עם זה לקדש ישראל בדרך שיהיו נכונים ליום השלישי ולזה לא נצטרך להוסיף עתה להם אזהרה בזה וצווהו השם יתע' להוסיף להתרות אותם על זה לסבה שזכרנו. ועוד שכבר יעלה הוא ואהרן ואולי יחשבו מפני זה הכהנים והעם שאין בזה אשם אם יעלו בהר או אם יגעו בו ולזה חוייב שהוסיף להזהירם על זה שנית:
@51 **והכהנים והעם אל יהרסו לעלות אל יי' וגו'.** והנה אמרו פן יפרוץ בהם יי' ואולם לעם לא היה צריך להזכיר העונש שכבר קודמה להם הידיעה מה יהיה העונש אם יגעו בהר ואמנם הוצרכו להוסיף להזהירם שלא יעלו בהר ושלא יגעו בו לסבה אשר זכרנו:
@55 **על פני.** ר"ל על עצמותי והרצון בזה שאע"פ שתאמין בי לא תשתתף עמי אלהים אחרים לתת להם חלק באלהות או יהיה הרצון בזה על השגחתי וירצה בזה שלא תאמין שיהיה לנו מנהיג אחר זולת השגחת השם יתעלה וזה כי מה שיסודר מהגרמים השמימיים הוא מהשם יתעלה והוא שליט להמיר הסדור ההוא כאשר יקרה ממנו רע לדבקים בו כמו שנתבאר מענין יציאת מצרים ולזה אין ראוי להאמין ההנהגה והממשלה על הנמצאות כי אם מהשם יתעלה אשר בשמים ממעל הם הככבים והנה אמר לפי שרבים טעו בהם וחשבו שיהיו אלוהות מפני מה שיראו מהפעולות השופעות מהם בזה העולם השפל ולא השגיחו כי גבוה עליהם הוא אשר נאצלו ממנו אלו הפעולות באמצעותם כמו שהתבאר בטבעייות ובאלהייות:
@56 **ואשר בארץ מתחת.** הם הב"ח ההולכים והמעופפים ונכללו עמהם בזה המאמר הצמחים אשר על הארץ:
@56 **ואשר במים מתחת לארץ.** הם הדגים ושרצי המים והצמחים הצומחים במים. והנה בא זה הענין בהדרגה בגדול החל ובקטן כלה וזה כי הככבים הם יותר נכבדי' מהב"ח אשר בארץ על מדרגותיהם והב"ח אשר בארץ הם יותר נכבדים מהב"ח המימיים כמו שהתבאר בספר ב"ח וכן ההיקש מן הצמחי' אשר בארץ עם צמחי המים. ולזה תמצא בצמחי המים מה שהוא כמו אמצעי בין הדומם והצומח כמו האלמוג ולפי שאמר כל תמונה הנה נכללו בזה גם כן שאר הדברים הנמצאים בארץ ובמים אשר להם תמונה מצד המלאכה או מצד הטבע:
@57 **אל קנא.** אמר זה כלשון בני אדם כאלו השם יתע' מקנה אם יתנו האלהות לזולתו כמו שיקנה המלך אם יתנו המלוכה לזולתו:
@59 **לשוא.** הנה שם שוא יפול על הכזב ועל הדבר שהוא לבטלה משל מה שהוא נופל על הדבר שהוא לבטלה אמרו שוא לכם משכימי קום ומשל מה שהוא נופל על הדבר הכוזב אמרו שוא ודבר כזב והנה ישתתפו אלו העניינים 'שהם לבטלה ולזה נכללו שניהם במלת שואו היתה האזהרה בהם יחד אחת במספר:
@60 **זכור את יום השבת לקדשו.** הוא זכירה בפה לקדש אותו וזה הקדוש ראוי שיהיה אצל כניסתו ויציאתו להבדילו משאר ימי השבוע:
@63 **וינח ביום השביעי.** ר"ל שלא חדש בו דבר ע"ד מופת על האופן שעשה בששת ימי בריאת העולם אבל נמשך המציאו' על ענינו לפי הטבע שהטביעו עליו בעת הבראו ולזה פירשו רז"ל וינח פועל יוצא והרצון בו שהניח לעולמו:
@67 **וכל העם רואים את הקולות.** וראה את ערותה. וכן אמר ומתוק האור וטוב לעינים כאלו היה הראות חוש הטעם. או יהיה ישמע מענין הקבלה כטעם והיה אם שמוע תשמע בקול יי' ולא שמע בתורתו ויהיה הרצון בזה הנה אנכי בא אליך כעב הענן לעיניהם וזאת יהיה לכם לאות שאני מדבר עמך והנה אעישה להם זה האות בעבור ישמע העם במה שאדבר עמך ויקיימו הדברים ההם וגם בך יאמינו לעולם בכל מה שתדבר להם בשמי מפני מה שיתפרסם להם שאני מדבר עמך והנה זה הפירוש השני יותר נכון לפי מה שאחשוב וכאשר שמע משה זה המאמר מהשם יתעלה שב להתבונן במה שאמרו ישראל וידע שהם כוונו בזה שיהיה המדבר להם השם יתעלה לא משה. והנה הגיד משה דברי העם אל יי' לפי זאת הכוונה השנית. ולה אמר לו השם יתע' כי מפני שהם רוצים שיגיע להם קול דברים מהשם יתע' כבר יחוייב שתקדשם שלא יגשו אל אשה ויכבסו שמלותם לכבוד השם יתע' כדי שיהיו נקיים מהטמאות ובזה האופן יהיו נכונים ליום השלישי לשמוע קול הדברים שיגיע מהשם יתע' על דרך המופת כי ביום השלישי ירד עיי' לעיני כל העם על הר סיני ותתן גבול לעם סביב ההר שלא יעברו הגבול הוא וזה כשתאמר להם השמרו לכם עלות בהר ונגוע בקצהו השפל כל הנוגע בהר מות יומת על יד בית דין וכבר ביאר אחר זה שזאת המיתה היא סקילה והנה הזהירם מגעת בהר כלל לישב בנפשותם עוצם מעלת השם יתע' כדי שייראו ממנו ולא יקלו בדבריו:
@67 **רואים את הקולות.** הוא כמו שומעים כי כבר יחליפו החושים קצתם בקצת והיה זה כן לפי שבכאן חוש משותף לכל החושים החמשה כמו שנתבאר בספר הנפש וזה ייחס השגת הלפידים והקולות לכח אחד ואע"פ שהשגת הלפידים תהיה לחוש הראות והשגת הקולות לחוש השמע והנה הקדים הקולות ללפידים ואע"פ שהלפידים הם סבה לחדוש הקולות לפי שחדוש הקולות היה יותר מכוון בזה המקום מחדוש הלפידים וכן אמר כזה במה שקדם ויהי קולות וברקים ועוד שדרך התורה ברוב המקומות לזכור האחרון בסדר הראשון לפי שהוא יותר מכוון ולזה הזכירה התורה עשרת הדברים בזה הסדור כמו שנתבאר במה שאחר זה:
@68 **דבר אתה עמנו ונשמעה.** ר"ל שכבר נקבל דבריך ונלך בדרכיהם:
@68 **ואל ידבר עמנו אלהים פן נמות.** ר"ל באמצעות קול הדברים כי עשרת הדברים שמעו אותם ישראל בזה האופן והחריד אותם הקול הנפלא ושאר הנפלאות שהיו שם:
@69 **לבעבור נסות אתכם.** יתכן שיהיה מענין ההתנשאות ואע"פ שהוא בסמ"ך וכן אמרו במכילתא בשביל לגדל אתכם בא האלהים ורצה בזה כי בקבולם התורה יהיה להם התנשאות וההתרוממות על שאר האומות כמו שאמר במה שקדם והייתם לי סגולה מכל העמים ועוד כי בה יהיו ממלכת כהנים כמו שקדם וזהו ההתנשאות ורוממו' למתנהגים בה בדרכי התורה והנה אמר בכאן ובעבור תהיה יראתו על פניכם תמורת מה שאמר במה שקדם כי בקבולם התורה יראה גוי קדוש:
@70 **הערפל.** הוא עב הענן אשר ירד בו הכבוד:
@72 **לא תעשון אתי.** הנה מפני מה שאמר לא תעשון אתי ואחר זה אמר לא תעשו לכם כמו שאמר בענין הקטרת והקטורת אשר תעשו במתכונתה לא תעשו לכם להורות שלא יעשנה כי אם לבית השם יתעלה הנה הוא מבואר שהרצון בזה באמרו לא תעשון אתי שלא יעשו בבית המקדש אלהי כסף ואלהי זהב ולא יעשו זה גם כן בבתיהם ובשאר המקומות והעד גם כן על זה הפירוש מה שאמר אחר זה מזבח אדמה תעשה לי ר"ל שלא תעשה לי בבית אלהי כסף ואלהי זהב אבל תעשה לי שם מה שלא יתכן שיחשב בו האלהות ושם תעבדני והוא המבזח שלא היתה בו תמונה תביא לחשוב בה האלהות וכאשר התישב זה הוא מבואר שאין הרצון באמרו אלהי כסף ואלהי זהב שיעשו מהם אלוהות כי בזה לא תצטרך התורה להבדיל בין עשייתם אותם בבית המקדש ובין עשייתם אותם בבתיהם כי הכל הולך אל מקום אחד ועוד שאם היה הענן כן למה זכר כסף וזהב הנה היה ראוי שימנע במוחלט עשיית האלהים בשיאמר במוחלט שלא יעשו להם אלהים אחרים ואמנם הרצון בזה שצורות מי שיתכן שיקראו אלהים לא יעשו לו למי בבניין בית המקדש ולא להם ולזה זכר כסף וזהב להורות כי לנו יעשו והנה האדם תמצאהו שהוא נקרא אלהים. אמר והייתם כאלהים יודעי טוב ורע. ואמר אמרתי אלהים אתם. עד האלהים יבא דבר שניהם. ובכלל הנה האדם יתכן שיקרא אלהים להיותו בעל שכל כי מפני זה יושפע ממנו פעולות להשלים הדברים הטבעיים וכן הכוכבים נקראים אלהים אמר ברון יחד ככבי בקר ויריעו כל בני אלהים. ואינו צריך להביא ראיה שהשכלים הנפרדים קרויים אלהים אמר הודו לאלהי האלהים. והנה מאלו שהם נקראים אלהים הזהיר הזם יעת' מעשות לו צורה לנוי כדי שלא יביא זה לחשוב שיהיה להם האלהות האמתי:
@73 **וזבחת עליו.** ר"ל אצלו. כטעם ועליו מטה מנשה. והראיה שלא היתה הזביחה על המזבח שהרי נתבאר בפרשת ויקרא ששחיטת השלמים תהיה פתח אהל מועד ולזה הוא מבואר שאין שחיטתם על המזבח ממש:
@73 **אזכיר את שמי.** הוא מעניין אזכרתה והרצון בו שבכל מקום אשר אריח שמי ועצמותי כטעם והריחו ביראת יי'. והנה המקום אשר יריח בו השם יתע' שמו הוא המקום אשר יהיו החשובים הדבקים בו כי הם משיגים מנימוס הנמצאות וסדרם וישרם דבר מה ובזה האופן ידע השם יתעלה כי שמו בקרבם כי כשישיגו שעור מה מנימוס הנמצאות ישיגו מעצמותו יתע' כמו שהתבאר מדברינו למי שיתבונן בהם בראשון ובה' ממ"י והנה שם תדבק השגחתו יתעלה וברכתו כמו שביארנו בד' ממ"י או שיהיה אזכיר מענין זכרון ויהיה המקום שיזכיר בו שמו השם יתעלה המקדש כי כל ענייניו הם מישירים להשיג סוד הנמצאות כמו שנבאר במה שיבא ולזה נתחייבו ישראל לראות המקדש ג' פעמים בשנה ור"ל שבכל מקום שיהיה מקדשו שם תדבק השגחתו ויברך ישראל ואעפ"י שלא היה במקום הנבחר כי אם בסוף העניין שהיה בהר המוריה והנה סבה זה כי המקדש בעצמותו יהיה סבה אל קניין השלמות אשר בעבורו יהיו מושגחים:

@1 **וישמע יתרו עד בחדש השלישי:**
@1 **ביאור דברי הפרשה:**
@1 ואולם התועלות המגיעות מזה הספור הנה הם רבים:
@1 **התועלת** הא' הוא במדות. והוא להודיע שראוי לאדם שיזדרז לראות נפלאות השם יתע' כי מהם יעמוד על אמתתו ית' ותכלית כחו וגבורתו ובכלל הנה מהפעולה נעמוד על הפועל וכל מה שהיתה הפועלה יותר נפלאה תעמיד אותנו על פועל יותר נפלא ולזה תמצא שיתרו עם היותו שר ואדון במדיון שהיה ארץ רעננה ודשנה הנה כששמע נפלאות ה' התעורר ללכת במדבר במקום שהיה משה חונה לעמוד על אמתת הענין כדי שיתברר לו כח השם יתע' וגבורתו ועצמותו כי תכלית הצלחת האדם הוא כשישכיל מאמתת הש' לפי מה שאפשר. ולזה תמצא שאמר יתרו כששמע אמתת הדברים עתה ידעתי כי גדול יי' מכל האלהי'. וזכר בתחלת הספור שהו' שמע כל אשר עשה הש' יתע' למשה ולישראל עמו להורות על שהסבה המביאה אותו ללכת במדבר ולצאת ממקומו היתה לעמוד על אמתת זה הענין:
@1 **התועלת** הב' הוא במדו'. והוא שראוי לאדם כשישתדל לעושת פועל מה שיכוין שיגיעו ממנו כל התועלו' שאפשר ולא יקצר בזה. ולזה תמצא כי יתרו אשר התעורר ללכת אל משה לעמוד על אמתת נפלאות השם יתע' לקח עם זה צפורה אשת משה ובניה והביא אותם אל מש כי היה מן הראוי שילך אל משה ג"כ לזאת הסבה השנית ורצה שיגיעו לו בהעתק האחד שתי אלו התועלות עם שכזה היה מההדור והכבוד למשה מה שלא יעלם:
@1 **התועלת** הג' הוא במדות. והוא שראוי לאדם שיעשה לו ה' נס שישתדל שיהיה הנס ההוא נזכר לפי מה שאפשר. ולזה תמצא כי כשנתבשר משה כי מתו כל האנשים המבקשים נפשו קרא שם בנו הנולד לו אז אליעזר להזכיר כי השם יתע' היה לו לעזר להציל אותו מחרב פרעה:
@1 **התועלת** הד' הוא במדות. והוא שראוי לשלם כשיבא לבית רעהו שיודיעו לו זה תחלה כדי שיוכל להשתדל לתקן ענינו באופן אשר ירצה לכבוד השלם הבא אליו ואם לא הודיע לו זה תחלה אולי ימצאהו כשיבא אליו באופן שיצטער ויבוש כשלא יוכל להשלים חקו מהכבוד לאיש השלם הבא אליו ולזה תמצא כי יתרו השתדל שידע משה בואו כדי שיהיה לו פנאי לסדר עניניו באופן אשר ירצה לכבוד יתרו עם שזה היה כבוד משה ר"ל שאם היה יתרו בא ולא תהיה לישראל הקדמת הידיעה בזה כדי שינהגו בו כבוד היה זה הענין בזיון למשה באופן מה כי משה היה במדרגת המלך וראוי לעם שינהגו כבוד בקרובי המלך לכבודו:
@1 **התועלת** הה' הוא במדות. והוא שאין ראוי לאדם מפני עלותו במעלת הגדולה והממשלה שיקצר מלנהג כבוד באנשי' אשר היה להם חוק עליו בזה קודם גדולתו וממשלתו כמו אביו ואמו וחמיו ומי שידמה להם. ולה תמצא כי משה עם עלותו בתכלית הממלכה והממשלה לא קצר מפני זה בכבוד חותנו אבל נהג בו מהכבוד בתכלית מה שאפשר וזה כי הוא יצא לקראתו והשתחוה לו ונשקו ושאל לו אם שלום לו ר"ל אם הוא בריא ואיך עניניו כמו שהיה עושה זה קודם עלותו לזאת המעלה הנפלאה ולא הוקיר לו דבריו מפני מעלתו וממשלתו ואולם אמרנו זה כי אין מחוק המשל להרבות דברים עם האנשים בזה האופן ועש' לו לויה גם כן בהפרדו ממנו כמו שנז' בסוף ואין ספק שזה היה סבה אל שעשו לו יש' כבוד נפל' ואם לא נזכר בבאור:
@1 **התועלת** הו' הוא במדות. והוא שראוי לאדם במדת הענוה בתכלית מה שאפשר הלא תראה כי משה רבינו ע"ה עם היותו נכבד מכל מין האנושי והיה עם זה בתכלית מה שאפשר מהממשלה הגיע מיתרון ענותו שיצא לקראת חותנו והשתחוה לו ונשקהו ושאל לו מעניניו איך הם:
@1 **התועלת** הז' הוא במדות. והוא שראוי לאדם שיפרסם לאוהביו ולקרוביו גבורת הש' יתע' ונפלאותיו לפי מה שאפשר כדי שיעתיקם אל האמונה האמיתית והשלמות התכליתיי ולזה תמצא כי משה רבינו ע"ה ספר לחותנו כל שעשה ה' לישראל במצרים ובים סוף ושאר הנפלאות כלם שעשה להם כמו מלחמת עמלק וענין מי מרה וענין השלו והמן והוצאתו מים מהצור להשקות ישראל ומקניהם ועמוד האש ועמוד הענן ושאר הנפלאות שעשה להם במתן תורה ובשאר המקרים שארעו להם עד בא יתרו אליו. והנה ראה יתרו בעיניו הרבה מאלו המופתים וזה כי הוא ראה מופת עמוד האש ועמוד הענן ומופת המן והנה השתדל משה בתכלית מה שאפשר להעתיק יתרו אל שישאר עמהם ויהיה לו חלק בארץ כדי שיעתק הוא וזרעו על זאת האמונה האמתי' כמו שנזכר בפרשת בהעלותך אמר אל נא תעזוב אותנו כי על כן ידעת חנותנו במדבר והיית לנו לעינים. וידמה שכבר רצה יתרו ללכת לארצו ולמולדתו להעתיק אותם אל האמונה האמיתית כמו שאמרו רבותינו ז"ל במכילתא כי אין ראוי לאיש שלם כמוהו אחר השיגו האמת באמונה האמתית שיעזוב זאת האמונה מפני הקושי אשר לו לעזוב ארצו ומולדתו:
@1 **התועלת** השמיני הוא במדות. והוא שאין ראוי לאדם שיהיה שמח לאיד כי הרע הוא בלתי רצוי בעצמותו ולזה לא יסור רע מהשם יתעלה אם לא מצד מה שבו מהטוב. ולזה ספר ששמח יתרו על הטובה שעשה השם לישראל ולא שמח ברע שהגיע אל המצרים:
@1 **התועלת** התשיעי הוא במדות. והוא שראוי לאדם לברך את השם יתעלה ולתת לו תודה על הנפלאות השופעות ממנו כי בזה תועלת להישיר להאמין בשם יתע' ושהכל הוא מאתו יתע' ולזה ברך יתרו השם יתע' על הטובה שעשה לישראל והקריב לו עולה וזבחים:
@1 **התועלת** הי' הוא במדות. והוא שכאשר יודה האדם להשם יתע' בהצילו האנשי' והיו בהם נכבדים ושפלים ראוי שיקדים לתת לו לו תודה על הצלתו הנכבדים ואח"כ על הצלת הפחותים וזה שאם היה כולל הצלת הנכבדים עם הצלת הפחותים הנה יהיה פוחת מעלת הנכדים כי היא לא יראה עצמו יותר שמח בהצלתם משמחתו בהצלת הפחותים והמשל שאם היו המלך ומשרת פחות במקום סכנה והצילם השם יתע' הנה אין ספק שאם אמר אחד מהאנשים להם ברוך יי' אשר הציל אתכם שהוא מבזה המלך ופוחת מעלתו כי הוא משוה שמחתו להצלת הפחות לשמחתו להצלת המלך. ולזה תמצא שנתן יתרו תודה לשם יתע' על הצלתו הנכבדים שבעם והם משה ואהרן הזקנים והם ראשי העם ואח"כ נתן תודה על הצלת העם:
@1 **התועלת** הי"א הוא במדות והוא שראוי למנהיג השלם שינהיג המונהגי' ממנו בתכלית מה שאפשר מהטוב והשלמות ולא יעלים עיניו מהנהגתם הלא תראה כי משה רבינו עליו השלום שהיה בתכלית מהדבקות בשם יתעלה עד שלא היה יכול להפנות מחשבתו בזולתו וזה היה סבה שלא היה יכול בדברו לבני האדם לסדר דבריו באופן ראוי הנה עם כל זה לא רצה לקצר בהנהגת ישראל אבל היה משתדל לשפוט בין איש ובין רעהו לפי משפטי התורה להסיר הקטטות והמריבות מביניהם אע"פ שהיה לו בזה לאות נפלא:
@1 **התועלת** הי"ב הוא במדות. והוא שראוי לשלם שלא יקצר מהגעת השלמות לפי מה שאפשר בפעולות אשר יראה בלתי שלמות כי בזה ילך בדרכי השם יתעלה שישתדל להגיע השלמות בכל אחד מהנמצאות בתכלית מה שאפשר. הלא תראה כי יתרו לא נמנע מפני עוצם מעלת משה מלגנות הפעולה הזאת אשר היה בה מהלאות הנפלא למשה ולישראל והשתדל לעשות זאת הפעולה באופן יותר שלם אלא כי מפני היותו משער עוצם מעלת משה בחכמתו רצה לדעת תחלה הסבה אשר בעבורה הוכרח משה לעשות המעשה כי אולי היה שלם הפועל אשר היה חושב שיהיה בלתי שלם וכאשר נתברר לו שלא היתה שם סבה תכריח עכ"פ שיעשה זה הפועל על זה האופן אז הראה למשה שלא טוב הדבר אשר הוא עושה ובאר לו זה באופן שלם ונתן לו עצה איך יגיע התכלית שהיה משה מכוין אליו בזולת לאות לו ולישראל:
@1 **התועלת** הי"ג הוא להודיע התכונות אשר ראוי שתהיינה לשופטים השלמים והם אלו אשר זכר יתרו ר"ל שיהיו אנשי חיל יראי אלהי' אנשי אמת שונאי בצע. וכבר ביארנו במה שקדם למה היה ראוי שתהיינה אלו התכונו' לשופטי' השלמים ואין תועלת בכפל הדברים ונתבאר עם זה שהוא ראוי שישים אותם שרים למשרתים רבים סרים למשמעתם כדי שייראו מהם ואנשים:
@1 **התועלת** הי"ד הוא במדות. והוא שראוי לאדם שיהיה שומע לעצה הטובה ולעזוב עצתו כשלא היתה טובה כמוה. הלא תראה כי משה רבינו ע"ה עם רוב שלמותו וחכמתו עזב עצתו מפני עצת יתרו להיוה יותר טובה ממנה:
@28 **בחדש השלישי עד אנכי יי' אלהיך:**
@28 **ביאור דברי הפרשה:**
@28 ואולם התועלות המגיעות מזה הספור הם תשעה:
@28 **התועלת** הראשון הוא להודיע כי כל מה שיעשה השם יתעלה מהנפלאות לישראל היה לתכלית שיתקרבו לעבודתו והנה סבב הש' יתע' במהירות נפלא להעתיקם מהרעות אשר גדלו עליהם ולהוציאם אל האמונה האמתית כדי שיהיו מוכנים לקבול התורה אשר בה היו מוכנים לירושת הארץ כמו שזכרנו פעמים רבות. ולזה אמר אתם ראיתם את אשר עשיתי במצרים ואשא אתכם על כנפי נשרים. ועתה אם שמוע תשמעו בקולי וגומ'. לפי שאז היו מוכנים לקבול התורה. לעוצם מה שראו מהנפלאות אשר הביאו אותם להאמין בשם יתעלה בתכלית מה שאיפשר:
@28 **התועלת** השני הוא להודיע שאין התורה נימוס מכריח ההולכים בדרכיה לעשות דבר יכבד עליהם לפי האמת אבל הוא הפך זה שהי תשים אותם בני חורין מכל אלו הפעולות המגונות אשר היה מנהג שאר הנימוסים להנהיג בהם ההולכים בדרכיהם כמו שאמר כי גם את בניהם ואת בנותיהם ישרפו באש לאלהיהם וזה כי התורה תכוין לבריאות הנפש והגוף ותכוין לקדש האנשים מהפעולות המגונות אשר הם בלתי אנושייות כמו רבוי המשגל והמשגלים המגונים ושאר הדברים הולכים מנהגם כמו שאמר ואתם תהיו לי ממלכת כהנים וגוי קדוש ולזה היה זה הנימוס בהפך שאר הנמוסים הקודמים כי שאר הנמוסים היו מוקבלים על צד האונס וההכרח לפי שאין עצמותם מחייב ההמשך אחריהם ואולם התור' אין קיבולה על צד האונס וההכרח כי עצמותה יחייב ההמשך אחריה ולזה הודיע הש' יתע' זה לישר' כשרצה שיקבלו התורה להקנותם השלמו' האמתי':
@28 **התועלת** השלישי הוא להודיע כי מי שילך בדרכו התורה תדבק בו ההשגחה האלהית לשמרו ולהצילו מהרעות הנכונות לבא עליו ולזה אמר ועתה אם שמוע תשמעו בקולי וגו'. והייתם לי סגולה מכל העמים וגו'. הנה הקדים השם יתב' לזכור התועלת שיגיע מההתנהג בדרכי התורה קודם שיגיע מהות הנימוס התוריי' ר"ל שהוא ישים אותם ממלכת כהנים וגוי קדוש כדי לחבב יותר לישראל ענין התורה ויתרצו לקבל מצוותה:
@28 **התועלת** הרביעי הוא להודיע כי הנבואה תגיע לנביא לפי מה שתשוטט מחשבתו בו ולזה כשהיה חושב משה במאמר ישראל כוונה אחת באה לו הנבואה בה האופן זולת האופן אשר באהלו בו כשחשב במאמרם כונה אחרת כמו שפירשנו במה שאמר וישב מש את דברי העם אל יי' ויגד משה את דברי העם אל יי':
@28 **התועלת** החמישי הוא להודיע עוצם השגחת השם יתע' בישראל ורצותו להועילם עד שכבר נתן להם התורה באופן שלא ישאר להם ספק בה בשהיא מאת השם יתע' כדי שיאמינו במצות התורה אמונה שלימה וילכו בדרכיה וזה שאם היה מספר להם משה דברי התורה על צד הנבואה הנה אולי ישאר להם ספק בזה כי הם לא ידעו אם מה שיאמר להם משה הוא מה שדבר אליו השם יתע' ולזה חדש ע"ד מופת קול דברים היו שומעים אותו ישראל ובזה האופן שמעו עשרת הדברות שהם סוגי התורה הראשונים כמו שיתבאר אחר זה ובזה האופן גם כן היו שומעים דברי התורה לולי שהם אמרו למשה דבר אתה עמנו ונשמעה ואל ידבר עמנו אלהים פן נמות ולא נצטרכנו גם כן אל זה כי שאר המצות התוריות בכללם הם נכללות באופן מה העשרת הדברים ולזה היו שומעים עשרת הדברים מספיק להן כאלו שמעו מצות התורה בכללם:
@28 **התועלת** הששי הוא במדות. והוא שראוי לאדם שינהג בתכלית הקדושה במקומת הנכבדים אשר בהם ייראו פעולות השם יתע' ונפלאותיו הראות נפלא ולזה צוו ישראל שלא יגשו אל אשה להיות נכונים ליום השלישי לעמוד סביב ההר אשר ירד כבוד השם יתעלה וצוו שלא יעלו בהר ולא יגעו בו לתת כבוד לשם יתברך אשר ירד כבודו שם:
@28 **התועלת** השביעי הוא להזכיר עוצם הנפלאות אשר נתחדשו שם אז ע"ד המופת על הר סיני ענן כבד וקולות וברקים וקול שופר חזק מאד ועלה עשן נפלא מהר סיני בכללו ונתחדש בו כדמות רעש ועוד שקול השופר היה הולך וחזק מאד מה שהתמיד להמשיך קולו ועוד שכאשר היה עונה השם יתע' למשה בנבואה היה מתחדש קול דברים על יד המופת מגיד הדברים ההם שהיה אומר השם יתע' למשה וזה כלו הוא בתכלית הפלא. והנה התועלת בזכירת אלו הנפלאות הוא להוסיף אמות בענין התורה עם שהאמונה בנפלאות הוא מפנות התורה:
@28 **התועלת** השמיני הוא במדות. והוא שראוי למנהיג השלם כשיכוון. שימנעו המונהגים ממנו מדבר מה להרחיקם מהיזק עצום או להקנותם תועלת נפלא שישים העונש חזק למי שיעשה הדבר ההוא ולא יסמך בזה לבד אבל יוסיף להזהירם על זה בעת שיש לירוא שימשכו אל המעשה ההוא אשר מנע אותם מעשותו כי בזה האופן יגיע אל התכלית המכוון ביותר שלם שאפשר וזה כי יראתם מהעונש החזק ימנע אותם מהמשך אחר המעשה ההוא והזכרה בשעת המעשה ימנע אותם משכיחת האזהרה הזאת והעונש הנפלא אשר בה. הנה לזאת הסבה תמצא שהזהיר השם יתע' שלא יעלו בהר ולא יגעו בו שאם יעשה זה יהיו נדונים בסקילה והוסיף להזכירם זאת האזהרה בעת שיהיה לחוש פן יהרסו לעלות ואולם משה היה חושב שלא יצטרכו לזאת האזהרה השנית לפי שהגבול אשר גבלו בהר יזכירם והודיעו השם יתע' והנה שעם כל זה יצטרך להזהירם על זה מפני שמשה ואהרן יעלו אל ההר ואולי יחשבו מפני זה שלא יהיה לשם אשם אם יעלו בהר או יגעו בו:
@28 **התועלת** התשיעי הוא במדות. והוא שאין ראוי לאדם לעשות פעל ההבל והבטלה. הלא תראה כי משה רבינו ע"ה היה קשה בעיניו להזהיר ישראל שלא יהרס אל יי' לראות ואע"פ שצווהו השם יתע' על זה מפני היותו חושב שלא יהיה בזאת האזהרה תועלת עד שביאר לו השם יתע' מה שיכריח להוסיף להזהירם:
@53 **אנכי יי' אלהיך וגומ' עד סוף הפרשה:**
@53 **ביאור דברי הפרשה:**
@53 **אמר** השם יתע' לישראל באמצעות קול הדברים המוחש אנכי יי' אלהיך המנהיג אותך ומשגיח בך אשר הוצאתיך מארץ מצרים שהיתה סוגרת ומסוגרת מלצאת ממנה כמו הבית שישימו בו העבדים שיכוונו לסגרו היטב כדי שלא יצאו ממנה ולזה אמר במקום אחר מכור הברזל. והרצון בזה שארץ מצרים לא היה יכול עבד לצאת ממנו כאלו תאמר שהיו עושין בו סימן יוכר בו שהוא עבד וכל מוצאו ומכירו שהוא עבד היה מצווה לתפשו ולהביאו אל אדוניו כמו שהוא המנהג היום בקצת המדינות. והנה היה זה תכלית הפלא. רצוני כי מהמקום שלא היה עבד אחד יכול לצאת הוציא השם יתעלה זה המספר הרב מהעבדים או ירצה בזה כי פרעה היה מונעם מהיציאה משם בדרך שלא היו יכולים לצאת כאלו היו בכור הברזל או מסוגרים בבית העבדים וסבב השם יתע' באלו הנפלאות העצומות אשר חדש שם להוציא ישר' ממצרים ומפני זה נתב' לישר' כי יש גבוה על הגרמי' השמימיי' הוא אשר פעל אלו הנפלאות וזה כי מה שיושפע באמצעו' הגרמים השמימיים הם הדברים הטבעיים כמו שהתבאר בששי ממ"י ולזה צוה הש"י להאמין שהוא האלוה כי בזאת האמונה תשלם לאדם הצלחתו האנושית כמו שהתבאר במעט עיון למי שיראה הפילוסופיא. ולא יהיה לך אלהים אחרים על פני. נוסף עליו ואע"פ שכבר תאמין כי ואפילו הדברים ששמם השם יתעלה אמצעיים להשפיע פעולותיו בזה העולם השפל כי הם אינם במדרגה שותפים לשם יתעלה שיותן להם אלהות אבל הם במדרגת המשרתים והכלים להגיע פעולותיו בנמצאות והוא מבואר מאד מזה שכבר הוזהרנו מלהסיר ממנו האלהות ולתתו לזולתו כי בזה יותר מההתרחק מהאמין בשם יתעלה. לא תעשה לך פסל וכל תמונה מהדברים הנמצאים בשמים כמו השמש והירח והכוכבים וכל צבא השמים ואשר בארץ מתחת כמו תבנית הבהמה והעוף ורמש האדמה ואשר במים מתחת לארץ כמו תבנית הדגה. והנה למדנו מזה שאם עשה הפסל על זה האופן לע"ז אע"פ שלא יעבדו עובר בלא תעשה וכן אם עשוהו אחרים לו. לא תעשה לך. והנה מלאכת האדם שתעשה ע"י שליח ייוחס עשייתה אליו כאמרו אז יבנה יהושע. ולא תשתחוה להם. מגיד שאין ראוי להשתחוות לאחר ממיני ע"ז ואע"פ שאין דרך עבודתו בכך כי ההשתחואה לאלהות לא תותר לעשות כי אם לשם יתעלה לבדו וכן ראוי שנבין מזה בשאר העבודות הנעשות לשם יתעלה כמו הזביחה והקטור והנסוך ולזה אמרה התורה זובח לאלהים יחרם וגו'. ואולם זכר בכאן מין אחד מהעבודות אשר יעשו לשם יתעלה וממנו נלמד הענין בשאר העבודות. ולא תעבדם. ר"ל בעבודות המיוחדות להם אשר יעבדום בהם עובדיהם כמו זורק אבן למרקולים ופוער עצמו לפעור כי זאת היא עפורתן כי אנכי יי' אלהיך מקנא במי שיתן האלהות לזולותי ואעניש אותו השונא אותי ועובד ע"ז בעונש נלא שיענשו על זה העון בני החוטא השלישים והרביעים. ולזה ראוי שישמרו האנשים מעבוד ע"ז. ואולם למי שיאהבני וישמר מצותי באופן שידבק בי אעשה חסד נפלא ימשך החסד ההוא לזרעו לאלפים מהדורות והנה יסופק בזה המאמר ספק מה והוא איך יתכן שיעניש השם יתעלה בני החוטא והנה אין להם אשם בחטא אביהם ואנחנו מתירים זה הספק בזה האופן והוא שהעונש יביא השם יתעלה על העוברים על דבריו אם על צד ההשגחה אם על דרך התוכחת אם על צד סור ההשגחה שיחולו עליהם הרעות הנכונות לבא עליהם לצד המערכת וכאשר יהיו אלו הרעו' באופן שיגיע להם רע לזרעם ולא היה מגיע להם לולי חטא אבותיהם והמשל כי כאשר מרו אבותינו חויב להם מהעונ' שיגלו בין האומות וירשו גוים ארצם והנה נמשך לזרעם אחריהם הגלות בסבת המצאם גולים בהולדם עד שלא יתכן שימלטו מזה הרע אם לא בהיותם יוצאים ממנו על צד המערכת או בשיהי בו בתכלית מהשלמות שיתכן שיוציאם השם יתע' מהארצות אשר הדיחם שם על דרך המופת ובה האופן אמ' הנביא אבותינו חטאו ואינם ואנחנו עונותיהם סבלנו וזה שאם לא חטאו אבותינו היינו אנחנו נמצאים בארץ מצרים ולא נצא ממנו אם לא כשנעשה מהפעולות המגונות מה שנתחייב עליהם כמו זה העונש ואולם כשנמצאנו בגלות בחטא אבותנו הנה לא יספיק לנו לשוב שם ההשמר מהפעולות המגונות אבל יצטרך לנו שנקנה מהשלמות כמו שנהיה בו דבקים לשם יתעלה באופן שיוציאנו מהגלות הזה על צד ההשגחה הנפלאה ובזה האופן לא היה עול עם יגיע לבנים עונש בעבור חטא האבות כי זהו במקרה והנה זה העונש המגיע בזה האופן הוא מעט לפי שהרע המסודר מהמערכת הוא מעט כמו שהתבאר במ"י והטובות ישפיע השם יתעלה באמצעותו על הרוב ועוד שהרע ההוא המסודר מהמערכת יתכן שיסור קודם עתו מצד דבקות ההשגחה האלהית הפרטית במקבל הרע. ולזה הוא מבואר שזה הרע אין ראוי שיתמיד אורך נפלא עם ההשגחה האלהית הפרטית וההשגחה הכוללת אשר תהיה באמצעו' המערכת מתנגדו' לו ואולם הטוב המסודר מהשם יתעלה לדבקי' בו יתכן שיתמיד לאלפים מהדורות כי הטוב הוא נעזר בטובות המסודרות על צד המערכת ובטובו' המסודרות על צד ההשגחה הפרטית וזה מבואר מאד כ"ש למי שראה דברינו בזה במ"י והתבונן בהם ואולם רז"ל התירו זה הספק באופן אחר וזה שהם אמרו שהשם יתע' פוקד עון אבות על בנים כאשר יהיו הבנים אוחזים מעשה אבותיהם בידיהם והוא בלי ספק מאמ' אמתי כמו שביארנו במ"י וזה כי הרע המסודר מהם יתעלה על צד התוכחת יהיה לפי המרי ר"ל שמי שהסתבך במרי סבוך מעט תספיק לו תוכח מעוטה ומי שהחזיק באופן ששב לו כקניין חזק יצטרך לתוכחת יותר עצומה ובהיות הענין כן הנה כאשר חטא האדם לבדו תספיק לו תוכחת יותר מעוטה מהתוכחת אשר תצטרך לו אם היה מחזיק אביו בזאת התכונה והוא היה אוחז מעשה אבותיו כי אז הסתבך בזה חמרי סבוך יותר חזק ובזה האופן אמרה התורה וגם בעונות אבותם ימקו והנה מה שאמרנוהו בזה הוא יותר נאות לפי הפשט:
@53 **לא תשא** את שם יי' אלהיך לשוא כי ה' יקח נקמתו ממי שישא שמו לשוא ולא ינקהו מזה החטא והנה ההשבע בשמו לשוא יהיה אם במה שהוא שקר וכזב אם במה שהו' ללא צרך משל מה שהוא ללא צורך כמו שנשבע על הידוע כמי שנשבע על השור שהוא שור והנה ההשבע במה שהוא שקר יחלק לשלשה חלקים אם שישבע על מה שהוא שקר כיצד התורה ר"ל שאי אפשר לו לקיימו כמו שנשבע שלא יניח תפילין כי התורה הכריחהו על זה והוא מושבע מהר סיני לקיים מצותה והנה הוא במדרגת מי שנשבע שלא לעשות דבר מה שהיה נשבע מתחילתו לעשותו ואם שישבע על מה שהו' שקר מצד טבעו ר"ל שאי אפשר לו לקיימו כמו שנשבע שלא יישן ג' ימים כי טבעו יאנוס אותו לישן קודם זה והנ' זאת האזהרה היא נמשכת לאזהרת ע"ז לפי שיש בעניינה מיעוט האמונה בשם יתעלה מה שלא יעלם וזה מבואר בשבועה שתהיה לשקר וזה כי השבועה בדבר הוא מורה על היקש בין שני הענינים מן האמתות והקיום ר"ל שזה הדבר הוא אמת כמו שזה יתקיים ולזה תהיה השבועה אצל האנשים בשמי' להעיר כי כמו שהשמים קיימים כן יתקיים זה המאמר או כמו שהשמים הם אמתי המציאות כן זה ולפי שהאמתות והקיום הוא נאמר בשם יתעלה מקודם ושאר הנמצאו' באיחור לפי שהאמתות והקיום להם מזולת שהוא השם יתעלה ובשם יתע' הוא מעצמותו על כן צותה התור' להשבע בשמו יתע' בזה האופן כאמרו ובשמו תשבע ומנעה השבע בשם זולתו ולזה ההיתה השבועה בשמו לאמת נמשכת אל ההאמנה בו יתעלה וההפך בהשבע בשמו לשקר כי זה יורה על שהנשבע יאמין שאין אמתות לשם יתעלה ולא קיום ולזה הקיש זה המאמר הכוזב למציאות השם יתעלה או לחייב שהם מציאותו כמו שהתבאר באלהיות ולה היה חטא שבועה השקר קרוב למדרגת חטא ע"ז והנה מי שישבע בשמו לחנם יורה שהוא מאמין שאין בשם יתעלה תועלת וצורך לנמצאות ולזה ישבע בו לאמת שאין צרך בהאמתתו והנה זאת האמונה היא יותר מגונה מאמונות מי שישתף לשם יתעלה אלוה אחר בהנהגת המציאות והנה תעמוד על אמתת זה ההיקש ממה שישבע בו האדם בחיי נפשו או בחיי בנו או בחיי אביו שלא יקל בקיום הדבר ההוא מפני מה שהקיש בין קיום הדבר ההוא ובין החיים ההם:
@53 **זכור** את יום השבת לקדשו מבין שאר הימים וזאת הזכירה היא בדבור לא בלב לבד והיא תהי' בכניסתו וביציאתו ר"ל שנזכור ההבדל אשר בין יום השבת לשאר הימי' כדי שנזכיר מעשיית מלאכה בו וזאת הזכירה אשר בכניסתו קראוה אותה רז"ל קדוש ואשר ביציאתו קראוה הבדלה:
@53 **ששת** ימים תוכל לעשות מלאכת עבודה ועשית כל מלאכתך והם שאר המלאכו' שהם לצורך אוכל נפש ואולם היום הז' הוא שבת ליי' אלהיך ר"ל שתיוחדו מכל מלאכה ויהיה היום ההוא מיוחד ליי' אלהיך כשתשתדל לעבודתו לבד ולא יטרידוך עסקים. לא תעשה כל מלאכה אתה לא ממלאכת עבודה ולא מהמלאכות שהם לצורך אוכל נפש ולא יעשוה גם כן לא בנך ובתך הקטנים ולא עבדך ואמתך הכנעני' ולא בהמתך ולא יעשה לך גם כן גרך אשר בשעריך ואף על פי שלא קבל עליו מצות התורה כמו שתראה בעניין הנבלה שאמרה התורה לגר אשר בשעריך תתננה ואכלה. הנה יתבאר לך כי האזהרה היתה כזה העניין לו לא לבנו ובתו ובהמתו ועבדו ואמתו וגר שער לפי שאין הבהמה ראויה למצות ולאזהרה ולא בנו ובתו הקטנים ולא הגר אשר בשער כי אינו בן תורה ולזה ראוי שנבין שהכונה בעבד ובאמה בכאן העבד והאמה שלא נכנסו בגבול המצות כגון עבד ואמה הקטנים ואולם הגדולים הם נכנסים לגבול המצו ואין האזהרה בהם לאדון אבל לעצמם ולזה אמר במקום אחר וינפש בן אמתך והגר להורות שעל הקטן ידבר והנה זה הגר אשר ידבר בו הוא כשיהיה שכירו ולקיטו ולזה אמר וגרך אשר בשעריך והמשיכו גם כן לעבדו ואמתו ובהמתו שהם תחת ידו והנה הזהיר השם יתע' ישראל מעשות מלאכה ביום השבת להעיר על חדוש העולם עד שהשלי' השם יתע' המלאכה הנפלאה שהיתה בו בששת ימי הבריאה וביום השביעי המשיך המציאות על ענינו לפי הטבע שהטביעו כמו שביארנו בפרשת בראשית ולזה ברך השם את יום השביעי כי הוא היה הולך במדרגת התכלית למה שנתחדש בששת ימי הבריאה וזאת היא הברכה בתוספת המעלה שהית' לו ולהזכיר זה הענין הנפלא אשר היו מהגדולו' אשר בפנו' התוריות והעיוניות כמו שנתבאר מדברינו בספר מ"י ברך השם את יום השבת ויקדשהו מעשות בו מלאכה כדי שיהיה היום ההוא מיוחד לעבודתו יתע' ובהתבונן בנפלאותיו ועוצם חכמתו להנהיג המציאות בזה האופן השלם ואפשר שנאמר שהרצון באמרו על כן בירך יי' את יום השבת ויקדשהו הוא להודיע לישראל שראוי שישבות ביום השבת כי בירך השם את יום השבת בעניין המן שהוסיף לישראל ממנו ביום הששי באופן שהיה מוכן להם מזונות שבת קודם באו ולזה לא הבאיש בשבת ורמה לא היתה בו וקדש השבת בעניין המן שלא היה יורד בשבת והיה יורד בשאר הימים והעד על זה הפירוש מה שאמר משה לנשיאי העדה כשהגידו למשה כי ביום ההוא מצאו העם לחם משנה הוא אשר דבר יי' שבתון שבת קדש לה' מחר כמו שביארנו. וראוי שתדע כי מצות הזכירה היא נוהגת בנשים לפי שהם מוזהרות מעשיית המלאכה בשבת כמו האנשים ולזה תהיה מצות השביתה והזכירה נוהגת ג"כ ועוד כי הזכירה היא לתכלית שישמרו מעשיית המלאכה ולזה יחוייב שתתנהג בנשים כי הם מוזהרות מזה וכזה אמרו ז"ל מי שישנו בשמירה ישנו בשכירה והני נשי הואיל ואיתנהו בשמירה איתנהו בזכיר' וראוי שתדע כי מלאכה היא מה שתכוין בו תכלית מהתכליו' וזה התכלית לפעמים יהיה מכוון בעצמו ולפעמי' יהיה בעבור זולתו משל מה שהוא מכוון בעצמו כמו הבישול והאפיה ותקון המזון והתפירה לתקון המלבוש ומה שידמה לזה משל מה שהוא בעבור זולתו כמו החרישה והזריעה והטחינה וההרקדה ומה שידמ' לזה והנה חייבה התורה על המלאכה שהיא מכוונת בעבור זולתו כמו שמצאנו במקושש וכן אמר' התור' בחרי' ובקציר תשבות ולה אין הכונה במלאכה שיגיע בה תכלית מהתכליו' אשר יכונו לפי הנהןג במלאכות כי בכאן מלאכות משרתות ומלאכו' ראשיות ומזה יתבאר כמה הם סוגי המלאכו' הראשוני' אשר יתחייבו עליהן בשבת והם לפי מה שהתבאר מהחפוש מ' חסר אחת והם הזריעה ומה שיכוון בו מהמלאכו' מה שיכוון בזריע' כמו הנטיעה וההברכה ומה שידמה לזה והחרישה ומה שיכוון בו מהמלאכות ומה שיכוון בחריש' והוא נתינת המזון לצמחי' והקציר' ומה שידמ' לזה והעמור ומה שידמה לו והדיש' ומה שידמה לזה והזריה והברירה והטחינה וההרקדה והלישה והאפיה ומה שידמה להם. כי כל אחת מאלו תקרא מלאכה לפי הנהוג אף על פי שהם קצתם בעבור קצת וגזיזת הצמר ומה שידמה לה והלבון והנפוץ והטוייה ועשיית הגירין והמיסך כדי לארוג והמריגה והצביע והקשירה כי כבר תקרה באריגה כשנפסק החוט וההתרה כי היא תקרה בה גם כן כשלא יעשה הקשר כראוי והתפירה והקריעה כי היא תעשה על מנת לתפור והבנין והסתירה כי כבר יכוין לסתור במלאכת הבנייה לתכלית שישובו לבנות הבנין ההוא באופן יותר שלם ומה שיעשה למלאכה להשלימה כמו שיפת הכלים בעור הדג להחליק אותם בתכלית מה שאפשר. ובזה הסוג נכלל כל דבר שבהעשותו תשלם המלאכה ומה שידמה לאחד אחד מאלו המלאכות והצרה והשחיטה ומחיקת העורות ועבודן וחתוכן והכתיבה והמחיקה כי פעמים תעשה לכתוב במקומו והשרטוט והבערה והכבוי וההוצאה מרשות לרשות ומה שידמה להן והנה כשתחקור על המלאכות כלם תמצאם נכללות תחת סוגי אלו המלאכות אשר זכרנו והנה ההושטה מרשות היחיד לרה"י ורה"ר באמצע ג"כ נקראת מלאכה בתורה כי כן היתה עבודת הלוים במשכן להושיט הקרשים מעגלה לעגלה אשר לפניה ולזה כשהיתה ההושטה בזה האופן רצוני שיהיו שני רשויו' היחיד בצד אחד מרשות הרבים והנה יתחייבו עליה להיות כמו זה הענין נקרא מלאכה בתורה וראוי שתדע שהעברת החפצים ברשות הרבים יותר מארבע אמות היא תחת זה הסוג ובעבור זה נהרג המקושש כמו שארז"ל וזה כי כבר תמצא שיעתיקו האנשים החפצים ממקום למקו' ברשות הרבים בזה האופן שיעתיקו אותם ממקו' למקום יותר קרוב מהבית או מהשדה וכשיקבץ שם במקום ההוא ישובו להעתיקו גם כן ממקום למקום עד שנשלם להם שיעתיקוהו בבית או בשדה ולזה יהיה נמנה זה מהמלאכות ואולם שיעור הארבע אמות נתבאר ממה שאומר והוא שאין כל העתקה שתעשה בזה האופן מלאכה ולזה יחוייב שיהיה שם שיעור ראשון תהיה ההעתקה אשר תהיה בשיעור ההוא מלאכה וזה השיעור הו' ארבע אמות ומעלה כי עד ד' אמות יוכל האדם להעתיקה חפץ עד היותו עומד במקום אחר והנה אמרה התורה שבו איש תחתיו ר"ל שמי שלקט דבר בשבת ישב תחתיו בדרך שלא יוציא החפץ מתחתיו והשיעור שיהיה לזה הוא ארבע אמות ר"ל שאדם הבינוני שיהיה שוכב ויפשוט ידיו ורגליו ימצא מתחתיו ארבעה אמות מהשיעור כי קומת אדם הבינוני הוא שלש אמות והאורך הנוסף בסבת פשוט ידיו ורגליו היא אמה אחת ומזה השרש יתבאר שמי שזרק החפץ מרשות הרבים והעבירו דרך רשות היחיד ונח ברשו' הרבים שאם נח חוץ לארבע אמות ממקום עקירתו חייב כי אלו הארבע אמות הם כמו רשות של אדם היושב בהם ולזה יצורף עמהם רשות היחיד להשלי' השיעור ארבע אמות וזה הדבר נתבאר בפרק הזורק ובתוספתא במעט עיון. ואולם הר"ם ז"ל נבאר מדבריו שהבין שלא יתחייב עד שיהיה שם ארבע אמות מזולת רשות היחיד ולא אשער מאין הוציא זה כי אלו הארבע אמות הם שיעור מה שיש תחתיו של אדם ולא תהיינה בשום פנים תחתיו אלו הארבע אמות מרשות הרבים שרשות היחיד מפסיק ביניהם אם לא יחתוך איש ההוא ולזה נפלאנו על הר"ם ז"ל ואולם רצונו היה מה שאמרנו ואף על פי שלא יראה זה מפשטי דבריו כמו שיתבאר למעיין בהם ואיני צריך לבאר שההוצאה מרשות היחיד לרשות הרבים או ההכנסה היא מלאכה כי הוא מבואר שכל אחת מאלו היא מלאכה מעשיית יכוון בה תכלית כאלו תאמר להוציא החפצים לחוץ למכרם או להכניסם לבית לשמרם ולזה היה הענין נכנס בגדר המלאכה אשר באה האזהרה מעשייתה ולזה אמר הנביא לא תוציאו משא מבתיכם ביום השבת והנה זאת המלאכה הוא מה שיעשוהו לפי המורגל מנימוס המלאכה ההיא ואם יעשה הדבר ההוא בזולת זה האופן לא יקרא מלאכה לפי הנהוג ולזה לא יתחייבו על עשייתו מן התורה כמו שהוציא החפץ בזולת האופן הנ"ל הנהוג כאלו תאמר ששם אותו על רגלו והוציא אותו וזה כי כל מלאכ' יש לה אומנו' וסדור תעש' לפי הסדור ההוא ומה שלא יעשה על זה האופן אין ראוי שיקרא מלאכה לפי הנהוג והמורגל וכן אם עשו שנים המלאכה שאין מדרכה שיעשו שנים הנה הם פטורים כי אין זאת המלאכה לפי המורגל כאלו תאמר שיוציאו שני' קופה קטנה ומה שידמה לזה ולפי שמגדר המלאכה היא שיכוין בה תכלית לתועלת מה הנה מה שלא יכוין בה תכלית או שיכוין בו תכלית ולא יהיה בו תועלת כלל לא יתחייבו בו בשבת ולזה יהיו המקלקלים פטורים בשבת אם לא יהיה בקלקול ההוא תועלת מה אם להנקם מהשונא או מה שידמה לזה ולזאת הסבה גם כן לא יתחייבו בדבר שאין מתכוין בו כי אין זה נכנס בגדר המלאכה כלל כאלו תאמר שיהלך אדם על גבי עשבים ויתכוין להלוך בשבת שהוא מותר בשבת וימשך מזה מה שידמה לקצירה רצוני שיעקור מהעשבים וזאת המלאכה תעשה בהכרח בכוונה בה ובזה האופן יתישרו בו על התכלית ולזה מי שחשב לעשות מלאכה אחת ולא עשה אותה אבל עשה אחרת הוא פטור כי לא יקרא מלאכה מה שעשה אותו כי לא כיון לזה וכן העושה מלאכה כמתעסק בזולת כוונה הנה הוא פטור כי אין זה נכנס בגדר המלאכה כלל וכן העושה מלאכה ולא הגיע אל התכלית שיכוין אליו ר"ל שלא נעשית המלאכה באופן שכיון בה והיה זה סבה שלא הגיעו אל התכלית לפי מה שכיון הנה הוא פטור ואולם אם הגיע התכלית היותר שלם ממה שכיון הנה הוא חייב כי כבר נעשית כונתו וגם כן הנה מהמלאכות מה שיעשה לא לגופה של מלאכה ויהיה נכנס בגדר המלאכה אחר שכבר נעשית המלאכה לתכלית מה כאלו תאמר שיעקור אדם אילן כדי שלא יסתעפו שרשיו ויקעקעהו הבניין הסמוך לו שהוא אינו צריך לגו האילן הנה מפני שאי אפשר שיגיע זה התכלית בזולת מלאכה הנה יתחייב וכן מי שיכבה הנר מפני השמן אעפ"י שאינו צריך לגוף הכבוי חייב וכן כל כיוצא בזה וראוי שתדע כי לא יתחייב האדם על מה שהוא ממלאכה ואינו מלאכה כי התורה הזהירה על המלאכה. לא על מה שהוא חלק מהמלאה ומזה המקום יתבא' לך לפי מה שהתבאר מהשרשים הכוללים שהמלאכות שיגיע התכלית בכל חלק מהם כשהגיע הנה כל חלק מהם יקרא מלאכה וזה כי החלק יהיה אם תהיה המלאכה מהכמה המתדבק כמו מלאכת הבנייה החלק היותר קטן שיתכן שיעשה במלאכה ההיא ולזה יתחייב דרך משל הכונה בכל שהוא כי כבר יתכן באי זה חלק שיהיה ממנו שתעשהו מלאכת הבנייה כי חסר כמו זה החלק להשלים בנין קצת הדברים ואם היתה המלאכה מהכמה דמתחלק ותעשה המלאכה ההיא מקבוץ האחדים אחד אחד כמו הכתיבה שיכתבו אות אחר אות וכמו האריגה שיארגו חוט אחר חוט הנה יתחייבו על עשיית שנים מהאחדים ההם כי זה המ"ם הוא קטן המספר שימצאו במלאכה ההיא מקבוץ האחדים ואם לא תעשה המלאכה מקבוץ האחדים אחד אחד אבל תעשה רבים מהאחדים יחד כמו העניין בהוצאת הזרעי' ובהוצאת התבן למאכל הבהמו' הנה יהיה הענין בזה כמו העניין במלאכה שהיא מהכמה המתדבק רצוני שכבר יתחייב על החלק היותר קטן שיורגל העשותו במלאכה ההיא כאלו תאמר שהוא התחייב אם הוציא מהתבן מה שיהיה מלא פי הבהמה אשר דרכה שתאכל אותו כי זה הוא קטן השיעור אשר יחלק בו התבן כשיקחוהו הבהמות לאכלו ויתחייב מהוצאת הזרעי' על קטן השיעור שיורגל שיקחהו הזורע לזרעו מאותם הזרעים ואולם מה שלא יגיע התכלית בכל חלק מהמלאכה כמו העתקת החפצים ממקור למקום הנה לא יתחייב אם לא עשה כל המלאכ' משל זה שהעוקר החפץ ממקום להעתיקו למקום אחר הנה כשעקר החפץ והעתיקו למקום אחר נשלמה המלאכה. ואולם קודם שהניח החפץ לא נשלמה ולזה אם עקר אחד והניח אחר שניהם פטורים ומזה יתבאר שאם עקר החפץ ולא הניחו על מקום ראוי שיונחו בו כמו שלא היה המקום ההוא ד' על ד' שאין ראוי להניח בו החפצים הנה לא יתחייב כי אין זו הנחה אבל הוא אמצע ההעתקה. וכן האופה ולא גמר לאפות באופן שראוי כלל לאכילה הנה הוא פטור כי זה חלק ממלאכה לא מלאכה והבן זה כי הוא מגדולי השרשים אשר יהיו בדיני המלאכות אשר יעשו בשבת וכבר ידעת מהשרשים הכוללים שהוא מותר לעשות בשבת מלאכה לפקוח נפש והוא מבואר גם כן שהמלאכה שהתחיל אדם לעשותה קודם השבת ונגמרה מאליה בשבת לא יעברו עליה מפני עשיית מלאכה והמשל כמו ששם האדם פת בתנור מערב שבת ונגמרה אפייתו מאליה בשבת לא יעברו עליה מפני עשיית המלאכה וזה כי הוא לא אפה זה הפת בשבתו ואינו מצווה על שביתת התנור כי אין אדם מצווה על שביתת כליו אבל הוא מצווה על שביתת בהמתו לבד כמו שביארה התורה ועוד כי בה יתכן שתאמר מנוחה ושביתה לא בכלים כי אין עמל בכלים במה שיעשה באמצעותם מהמלאכות וזה מבואר בנפשו וכבר ביארנו במה שקדם שהיום התוריי הוא מתחיל מהערב והנה מסתפק לרז"ל אם תהיה התחלת היום מעת שקיעת החמה או מעת שיסור אורו והוא כשיראו שלשה כוכבים בינוניים וזה כי אור השמש מונע הראות הכוכבים וכשיראה מהם זה הרבוי אז נשפוט שסר אור השמש באופן מה וזה כי כשנראה כוכב אחד לבד לא היה שם רבוי מראיית הכוכבים ולא נשפוט מפני זה על סור אור השמש ולפי שאין הראות הכוכבים אחד אחר אחד מפני רבוים יראו מהם יחד רבים בהעדר אור השמש מונע הראות הכוכבים וכשיראה מהם זה הרבוי אז נשפוט שסר אור השמש באופן מה וזה כי כשנראה כוכב אחד לבד לא היה שם רבוי מראיית הכוכבים ולא נשפוט מפני זה על סור אור השמש ולפי שאין הראות הכוכבי' אחד אחר אחד מפני רבוים יראו מהם יחד רבים בהעדר אור השמש והם הכוכבים אשר גדלם שוה ומרחקם מהשמש שוה באופן מה הנה נקח מהם הרבוי הראשון שהוא שנים ונוסיף אותו על הכוכב האחד והוא שלשה ואולם אם יהיה לילה כשיראה שני כוכבים בינוניים הנה יש בזה ספק וזה שאם היה הראות הכוכבים אחד אחר אחד בהכרח הנה יהיה לילה כשיראו שני כוכבים כמו שהתבאר בשרשים הכוללים וזה לא היה הראות הכוכבים אחד אחר אחד מפני היות רבים מהם יחד במדרגה אחת מהשמש הנה מפני שהמספר הרב הראשון הוא שלשה הנה לא יהיה לילה עד שיראו שלשה כוכבים והנה קראו רז"ל זה הזמן אשר בין שקיעת השמש וצאת הכוכבים בין השמשות וזה הזמן הוא ספק אם הוא מהיום העובר או מהיום הבא ולזה ראוי להשמר מעשות מלאכה משקיעת השמש מערב שבת עד צאת הכוכבים ביום השבת כי בספר של תורה וראוי שנשפוט להחמיר כדי שלא נעבור על דברי התורה כ"ש בענינים הגדולים כמו השבת שיש בו כרת ומיתת ב"ד כמו שיתבאר במה שיבא בג"ה. וראוי שתדע שאם הניח האדם לעשות מלאכה לבנו ובתו הקטנים ולעבדו ואמתו ובהמתו ושכירו ולקיטו אינו לוקה לפי מה שאמ' לא תעשה כל מלאכה אשר כלל בו אלו האזהרות הוא לאו שנתן לאזהרת מיתת ב"ד ואין לוקין עליו והנה הוא עובר על עשה שנאמר למען ינוח שורך וחמורך וינפש בן אמתך והגר. וכן ראוי שתדע שאחד שור וחמור ואחד כל בהמה וחיה ועוף שיש ברשותו של אדם כי ההיקש בהם אחד אלא שדבר הכתוב בהווה לפי שהשור והחמור הם נכונים לחרוש בהם ולשאת בהם כל משא והוא מבואר שלא יקרא מלאכה מה שתשא הבהמה לתכשיט או לשמירתה שלא תברח או שלא יגיע לה נזק מאי זה שיהיה מהדברים ואולם יקרא מלאכה מה שתשאהו על צד ההעתקה ממקום למקום או שלא יהיה בו תועלת לשמירת הבהמה בעצמה או שלא תברח וכן הענין באדם כי מה שישא מהדברי' שאינם תכשיט לו או שאינם לשמרו מהקור והחום והוא מבואר עוד שהאכילה אינה מלאכה אבל היא נכנסת בגדר הפעולות הטבעיות כי הב"ח כולם יעשו זה הפועל. ולזה לא נאסרה בשבת כמו שאמר בביאור אכלוהו היום כי שבת היום ובהיות הענין כן הנה שבירת הדברים שהם לצורך אכילה לא יקרא מלאכה כאלו תאמר שבירת האגוז לאכול מה שבתוכה כי זה יעשוהו הב"ח גם כן בשניהם וגם שבירת הכלים לקחת מה שבתוכם מהאוכלים כשלא יכוין שתעשה השבירה ההיא באומנות וכן תמצא שיעשו זה כשיוכלו עליו. ולזאת הסבה בעינה מותר לאדם לחתוך האוכלין לפני בהמתו:
@53 **כבד** את אביך ואת אמך בדבריך ובמעשיך כאלו תאמר לשמשם ולהאכילם ולהשקות' ולהלבישם משלו אם אין נכסים לאב ולאם כי הכבוד יאמר על מה שיותר אדם מהונו לתת לכבוד זולתו כמו שאמר כבד את יי' מהונך והנה בקיימך זה היעוד ימשך מהתועלת שתחזיק בארץ אשר יי' אלהיך נותן לך לאורך ימים וזה כי בכבד האדם הוריו כפי כוחו מפני שהביאוהו לחיי העולם הזה יתעורר לכבד השם יתעלה אשר שפע ממנו מציאותו ומציאו' הוריו וישמר מציאותם הזמן האפשרי במה ששפע ממנו מהכוחות השומרות מציאותם ולזה השתדל לקיים מצות השם יתעלה כפי היכולת וזה יהיה סבה אל שלא תסור השגחת השם יתעלה מישראל באופן שיירשו הגוים ארצם הלא תראה שלא גלו ישראל מהארץ כי אם אחר בזותם השם יתעלה ועבדם ע"ז עד שהגיעו מעוצם בזותם השם יתעלה ומצותיו שהעמידו צלם בהיכל כמו שנתפרסם ממנשה. ועוד כי כשיכבד האדם הוריו ישמר מעשות דבר יכעיסם ויתנהג מפני זה במוסרם וזה יהיה הסבה שיקבלו המוסר הדורות הבאים מהראשונים דור אחר דור ויחזיקו מפני זה כלם בתורת השם יתעלה אחר שכבר החזיקו בה דורו של משה ועוד כי בזה ישלם תקון קבוץ הבית אשר הוא התחלה לתיקון קבוץ המדינה והנה יקרה מתקון קבוץ המדינה שתשלם ההסכמה בין האנשים ויקבלו צעיריהם המוסר מגדוליהם וזה יהיה סבה אל שישמר יש' תמיד תורת השם יתעלה דור אחר דור. ואולם התועלת שיהיה להם בהחזיקם תמיד בארץ ישראל הוא קנין שלמו' האנושי כי בארץ ההיא הכנה נוספת להגעת השפע האלהי בה כמו שזכרנו פעמים רבות במה שקדם עם שקבוץ השלמים הוא עוזר מאד להגעת השלמות ובהיותם מפוזרים בין האומות ימנע מהם זה העזר עם מה שיטריד' התענותם תחת יד האומו' ההם. וראוי שתדע שכבוד אב ואם נוהג אפילו לאחר מיתה כי בזה ישלם התועלת שאמר למן יאריכון ימיך וגו' שאם לא היה האדם מזדרז אחר מות אביו לתת כבוד לאביו שהביאהו לחיי העולם הזה לא יזדרז ללכת במוסרו ולא יזדרז מפני זה ללכת אחר מצות השם יתעלה. ועוד שכבר מצאנו בספורי התורה כבוד ההורים אחר מיתה במה שאמרו אחי יוסף ליוסף אביך צוה לפני מות לאמר כה תאמרו ליוסף אנא שא נא פשע אחיך וגו'. וזה כלו מורה כי הם אמרו זה להורות יוסף שרצון אביו היה שימחול להם. ולזה נתן להם זאת העצה כדי שיוכרח יוסף לכבוד אביו למחול להם וראוי שתדע כי זה הדין נוהג באיש ובאשה ובטומטום ובאנדרוגינוס כי לא הבתה בזה הצווי דבר שלא בא הצווי בזה לאיש לבד כמו הענין בהדבק ממצות התורה אלא שהאשה כיון שנשאת אין ספק בידה לעשות כי רשות בעלה עלה ואולם תכבדהו אז בדבריה ובמה שאפשר לה ואין ספק כי מי שיבזה בעל אמו יבזה אשו וכן מי שיבזה אשת אביו יבזה אביו ולזה נכלל בכבוד אב ואם כבוד אשת אביו שאינה אמו וכבוד בעל אמו שאינו אביו וכן הוא מבואר שאם היה הבן ממזר שאביו הוא מי שהולידו ולזה יחוייב המסור גם כן בכבוד אביו ואמו. והנה הקדימה התורה כבוד אביו לכבוד אמו לפי שהוא ואמו חייבים בכבוד אביו. ולזה יהיה כבוד אביו קודם לכבוד אמו ומזה המקום יתבאר שכבוד השם יתעלה קודם לכבוד אביו ואמו לפי שהוא והוריו חייבים בכבוד השם יתעלה:
@53 **לא תרצח** ר"ל שלא תהרוג נפש אדם מישראל כי הריגת הבעלי חיים הותרה להם לפי שהתבאר בתורה במקומות רבים. וכבר נצטוו גם כן על הריגת קצת האומות כמו עמלק ושאר האמות שנצטווח ישראל שלא יהיו מהם כל נשמה ולזה יחוייב שישוב זה הצווי לנפש ישראל והוא מבואר שכל מי שיהיה חי גדול או קטן או איש או אשה או טומטום או אנדרוגינוס יפול עליו שם הרציחה כי הוא חי ולזה אמר בפרשת אמור ואיש כי יכה כל נפש אדם מות יומת:
@53 **לא תנאף** ר"ל שלא תבא על אחת מהעריות אשר תזהיר בהם התורה כמו אשת איש וזולתה כמו שאמר אזר ינאף אשת רעהו מות יומת הנואף והנואפת ושלא תביא האשה אחת מהעריות עליה. ועוד יתבאר באי זה אופן יתחייבו בו ובאיזה אופן לא יתחייבו בו אצל הביאור בענין העריות:
@53 **לא תגנוב** הנה זאת האזהרה היא לגניבת נפש מישראל שיתכן בה מיתת ב"ד כמו שיתבאר בפרשת ואלה המשפטים וזה סמכו לאזהרת הרציחה והניאוף שיש בהם מיתת ב"ד ואולם האזהרה על גנבת ממון היא בפרשת קדושים תהיו באמרו לא תגנובו ולא תכחשו ולא תשקרו איש בעמיתו וכבר יתבאר זה מדברינו מצד אחר מהביאור כאשר נבאר שאלו עשרת הדברים מקיפים על כל מצות התורה באופן מה:
@53 **לא תענה** ברעך עד שקר. ר"ל שלא תעיד ברעך באופן שתהיה עד שקר בעדות ההוא ואין ראוי שנאמר שיהיה זה המאמר אזהרה לעד שקר שלא יעיד בחברו שאם היה הדבר כן יהיה מוזהר עד השקר מלהעיד ברעהו האמת וזה דבר אין ראוי שיאמן כי הכובש עדותו הוא חוטא כמו שיתבאר בפרשת ויקרא ואפשר שיהיה הרצון בעד עדות כמו שכת' ר' דוד קמחי ויהיה הרצון בזה שלא תעיד ברעך עדות שקר וכמוהו גלעד שקר' לבן בלשון ארמית יגר שהדותא כי כבר ימצאו בלשוננו שמו' יהיו פעם שם תואר ופעם שם מקר' והנה ימצא בזה העדו' מה שיתחייבו בו מיתת ב"ד כמו שיתבאר בפרש' עדים זוממים:
@53 **לא תחמוד** בית רעך ר"ל אשתו וטפו ושאר קנינו וענין החמדה הוא שישתדל שיהיו לו כאילו תאמר שיתן ממון לרעהו שיגרש אשתו כדי שישאנה או שימכור לו עבדו ואמתו ושורו וחמורו או אחד משאר קניניו כי זאת היא תכונה רעה מאד להשתדל שיצאו קניני רעהו מתחת ידו אם לא יתרצה מעצמו למכרם ולהוציאם מתחת ידו וכבר למדנו שהחמדה אינה בלב לבד אבל יש עמה מעשה ממה שאמרה התורה לא תחמוד כסף וזהב עליהם ולקחת לך וגומ' ואמר עוד לא יחמוד איש ארצך ר"ל שלא ישתדל איש לקחת אותה בעלותך לרגל וכן אמר וחמדו שדות וגזלו ולזה לא יהיה עובר על לאו זה אם לא עשה מעשה באופן שיהיה לו הדבר שחמד ואי אפשר שנאמר שיהיה הרצון בבית רעך האהל אשר ישב בו כי אנחנו נמצא עניין זכירתו הפרטים הולכים בהדרגה בנכבד החל ובקטן כלה ולזה הקדים אשתו לעבדו. ועבדו לאמתו. ואמתו לשורו. ושורו לחמורו. ואחר כן כלל כל שאר הקנינים שאין בהם רוח חיים והנה אין הבית יותר נכבד מהאשה שיקדימוהו לה ולזה יהיה הרצון בביתצ כלל קניניו וכן פירשו במכילתא והנה מצאנו הבית נופל על האשה והבנים אמר ונשמרתי אני וביתי ואמר בקנין המלוכה כי בית יעשה לך יי' והנה אם נתאוה בלב לבד אע"פ שלא עשה מעשה כבר עובר בלאו כמו שנזכר במשנה תורה ולא תאוה בית רעך שזהו ועבדו ואמתו. והנה נכללה זאת האזהרה בכאן במה שאמר לא תחמוד. שלא יתכן שישמר האדם מהחמוד אם לא ישמר מהתאוות קניני רעהו כי התאוה מביאה לידי חמוד. וראוי שתדע כי אלו עשרת הדברים מקיפים בכל מצות התורה. ולזה היתה כוונת האלהית שישמעו אותם ישראל בזה האופן הנפלא לא מפי משה כדי שיאמינו בהם התקיים להם האמונה בכל המצות התוריות אשר הם מקיפים בהם. ואנחנו מציעים תחלה בביאור זה כי הצואה לעשות מה שהוא בתכלית מהטוב תקיף אל עשיית הדברים המביאים אל הטוב ההוא והאזהרה מעשות מה שהוא בתכלית מהרע תקיף מההשמר מעשית הדברים המביאים אל הרע ההוא והמשל שאם יצוה אדם לבנות בית חזק והיה מדרך הבניין ההוא שלא ישלם אלא כשיקחו אבנים מהמקום הפלוני וחמר מהמקום הפלוני ולבנים מהמקום הפלוני וקורות מהעץ הפלוני הנה הצואה על הבנין ההוא היא צואה לקחת אבנים והחמר והלבנים והקורות מהמקומות ההם אשר בהם יתכן שישלם זה הבניין ואחר זאת ההצעה נאמר כי מפני שהתכלית הוא יותר נכבד ממה שלפני התכלית במה שידרוך אל השלמות והיה המאוחר בסדר בפעולות אשר יכוין בהם השלמות יותר קרוב אל התכלית מהקודם בסדר הנה הקדימה התורה בענין עשרת הדברים המאוחר בסדר וזכרה באחרונה הקודם בסדר. ועל זה האופן ראינו לבאר הסבה וסדור עשרת הדברים כשנתחיל מלא תחמוד עד שנגיע בזה האופן לאנכי יי' אלהיך ונאמר כי התורה תשתדל להשלים האד' במדות ובעיון כמו שזכרנו במה שקדם ובארנוהו במה שאין ספק בו מספורי התורה ויתבאר עוד בג"ה אצל נתינתנו טעמי המצות במצות מצוה והנה השלמות במדות יגיע כשישמר האדם מעשיית הרע וישתדל בעשיית הטוב. וכן השלמות בעיון יגיע כשישמר האדם מהאמין הדעות הנפסדות ובהשתדלותו להאמין הדעות האמתיות והוא מבואר כי הסרת חליי המדות והעיון קודם בסדר להקנאת השלמות במדות ובעיון כמו שקדם ברפואת הסר' הליחה המחליאה להקנאת מזג הבריאות ולזה גם כן קדם בסדר הקנאת שלמות המדות להקנאת שלמות המושכלות כי לא יתכן שישתדל האדם בשלמות המושכלות כראוי אם לא אחר הנקותו מטומאת המדות המגונות המונעות אותו מכל שלמות ולפי שהיו בכאן מצות יכוין בהם ההישרה לשלמות המדות ולשלמות המושכלות יחד הנה יחוייב שיקדים בסדר אלו המצו' המישירות לשלמות המושכלות ולה יהיה הסדור נותן שיקדים בסדר סוגי האזהרה אשר יקיפו על סור מרע במדות ואח"כ יזכור סוגי הצואה אשר יקיפו על עשיית הטוב במדות ואחר כן יזכור סוגי האזהרה אשר יקיפו על סור מרע במה שהוא משותף למדות. ולעיון. ואחר כן יזכור סוגי הצואה אשר יקיפו על עשיית הטוב. כמה שהוא משותף למדות לעיון ואחר כן יזכור סוגי האזהרה ואשר יקיפו על עשיית הרע בדיעות ואחר כן יזכור סוגי הצואה אשר יקיפו על עשיית הטוב בדיעות אלא שהתורה הפכה זה הסדור והתחילה מהמאוחר בסדר לסבה שזכרנו ועוד כי אע"פ שהאמונה בשם יתע' וההרחקה המאמין זולתו הם אחרונו' בסדור כאשר יגיע' זה בהתאמתות וחקירה הנה ראוי שתהיינה קודמות בדר על צד הקבלה כדי שיתחנכו הקטנים באמונת השם יתע' ויגדלו עליה ויהיה זה סבה אל שייראו ממנו ויתנהגו בדרכי התור' והנה לא תחמוד ולא תענה ולא תגנוב ולא תנאף ולא תרצה הם כלם אזהרות מקיפות על סור מרע במדות ומצות כבר היא מקפת על עשיית הטוב במדות והאזהרה מעשית מלאכה בשבת היא מקפת על סור מרע במה שהוא משותף בין המדות והדיעות והצואה לשבות בו ולזכרו ולקדשו היא מקפת על עשיית הטוב במה שהוא משותף בין המדות והדעות ולא תשא ולא יהיה לך אזהרות מקיפות על סור מרע בדיעות והוצאה בהאמנת השם יתע' היא מקפת על עשיית הטוב בדעות וידמה שיהיה לא תשא ולא יהיה לך הם אזהרות מקיפות על סור מרע בדעות והצואה באמנת השם יתע' היא מקפת על עשיית הטוב בדעות וידמה שיהיה לא תשא משותף גם כן בין המדות והדעות אלא שכבר סמכה אותו התורה ללא יהיה לך לסבה שזכרנו אצל ביאורנו לזה הפסוק ר"ל לא תשא. וראוי שתדע שהחטא שיחשב שיהיה יותר קטן ראוי שתקדם בו האזהרה כי זה ממה שיהיה סבה אל שיקל לאנשים לעשות אותו כי לא יחשבו להם עון בזה וכן הוא מבוא שהחטא יתכן שיעשה בקלות יותר הוא ראוי שתקדם האזהרה בו וכאשר התיישב זה כלו הנה נאמר שלא ימנע החטא במדות משיהיה במחשבה או בדבור או במעשה והנה החטא אשר במחשבה כאלו תאמר שיתאוה האדם בית רעהו הוא מה שיחשב שאין בו מרי כי לא עשה דבר בתאותו זאת והנה זאת התאוה והחמדה הם מביאים לניאוף או לגנבה או לרציחה כאשר לא יוכל להשיג מבוקשו בזולת זה האופן ולזה היתה זאת האזהרה קודמת בסדור לשאר האזהרות אשר בהסרה מהרע במדות. והוא מבואר שהדבור אינו ממה שיחשב היותו מעשה אצל האנשים ולזה יקל לאנשים יותר ההיזק לזולתם בדבור מהמזיק במעשה עד שמי שיקשה בעיניו הכותו רעהו יקל לו להזיק לו בדברו באופן שתקרה ממנו הרציחה כי יחשב שהוא לא פעל דבר וזה מבואר מאד ולזה היתה קודמת בסדר האזהרה על החטא שיהיה בדבור על האזהרה על החטא שיהיה במעשה ולפי שהחטא שיהיה בדבור יהיה היותר חזק ממנו הדבור שיביא בהכרח למעשה לפיח שהדבור ההוא כמו הענין בעדו' שיהיה לפני ב"ד עד שכבר תמשך ממנו הרציחה בהכרח כאלו תאמר כאשר העיד על האיש מה שהרג את הנפש הנה זכרה התורה החטא היותר חזק שיהיה בדבור והוא עדות שקר והנה תחת האזהרה הזאת היא הליכת רגיל ולשון הרע ושאר מה שיגיע בו ההפסד המדיני מפני החטא אשר בדבור והוא מבואר שמי שירגיל לשלח רסן לשונו ברכילות ולשון הרע יקרה לו שיקל מפני זה לשלח רסן לשונו להעיד עדות שקר ומזה המקום יתבאר שאין ראוי לאדם כשישבע על הדברים שבינו לחבירו שישבע על שקר כי הוא עד בזה הענין עד שכבר יחתך הדין על פיו ואולם בזה הענין יהיה חטא אחד בדעות ובאה האזהרה בו בדבור לא תשא. ואחר שזכר החטא שיהיה במחשבה ובדבור זכר החטא שיהיה במעשה והנה החטא אשר במעשה יהיה אם כשתגיע ההנ אה לשני החלקים או לאחד מהם לבד ואשר תגיע בו ההנאה לשני החלקים יקל העשותו יותר כי בפועל ההוא התחלה לכל אחד מהחלקים והמשל כי המשגל להיות בו הנאה לזכר ולנקבה כבר תהיה התחלת הפועל לזכר וכבר תהיה גם כן התחלתו לנקבה מצטרף לזה כי יקל לאחד מהם להשמע לחברו להיות בו הנאה לכל אחד מהם. ולזה הקדים האזהרה בענין מה שיחטא אדם במשגל שיש בו הנאה לזכר ולנקבה והקדי' להזהיר ביותר קשה שבזה סוג והוא המשגל שיהיה עם העריות והיתה זאת האזהרה מקפת על כל מה שבזה הסוג וזה כי מי שירגיל בזה הפועל המגונה יקרה לו מרוב התפתותו בו שיבא על העריות ולזה היתה האזהרה על בעילת העריות מקפת על האזהרה על בעילת שאר הנשים אשר הוזהר מבעילתם ואשר תגיע בו הנאה לאחד משני החלקים לבד יהיה אם שיגיע בו היזק לחברו בזולת ידיעתו או בידיעתו והנה מה שיגיע היזק לחברו בזולת ידיעתו יהיה העשותו יותר קל ממה שיגיע בו היזק לו בידיעתו כאלו תאמר שהגניבה יקל העשותה יותר מן הגזלה כי הנגזל יתנגד לגוזל בענין גזלתו ומי שנגנב לו דבר לא יתנגד לגנב בזה הפעל כי לא ידע אותה ולזה קדם בסדר האזהרה על הגנבה לאזהרה אשר תהיה על ההיזקים שיגיעו מהאדם לחברו בידיעתו כמו הרציחה ומה שידמה לה והנה הקשה שבזה הסוג הוא שיגנב האדם לחברו בידים ושיהיה הנגנב נפש אדם ולזה בארץ האזהרה על הגנבה בזה האופן והיא מקפת על מה שבזה הסוג מההיזקים לפי שמי שלא ישמר להזיק לחבירו בזה האופן יקרה לו שיקל לו לגנב נפש מישראל והנה תחת זה הסוג גניבת ממון ושלוח יד בפקדון וההמנע מהשיב אבדה כי בזה יגיע היזק לחברו בזולת ידיעתו וכן ההמנע מנתינת מתנות כהונה לוייה ומתנות עניים וההמנע מלשלם נדריו וההשתמשו' בקדשי' הוא תחת זה הסוג ובכלל כל מה שהיה בו היזק לזולתו בזולת ידיעתו ואולם מה שיגיע בו היזק לחברו בידיעתו הנה היותר קשה שבזה הסוג הוא הרציחה היה שתהיה לעצמו או לזולתו ולזה באה בזה הסוג האזהרה על הרציחה ותחת זה הסוג הוא כל מה שיהיה סבה להביא נזק לאדם או לזולתו בידיעתו וכן מי שיקל בהביא ההיזקים לאנשים בזה האופן יקרה לו שיקל בהריגה האנשים ויביאהו זה גם כן אל שיקל להריגתו עצמו לרוב היותו מורגל בהמצאת ההיזקים והנה תחת זה הסוג הוא האזהרה משנאת אחיו בלבבו והנקימה והנטירה ומה שידמה לזה ממה שיביא האדם להזיק לחברו וכן חת זה הסוג הוא עשית מעקה והאזהרה מהמצאת הדברים המזיקים כמו שור המזיק והבור והבערה הבערה ומה שידמה להם והנה תחת זה הסוג הוא גם כן ההשמר מאכילת הדברים המזיקים והם המאכלים העכורות אשר זכרה התורה כמו הבהמה אשר איננה מפרסת פרסה ומעלה גרה והדג שאין בו סנפיר וקשקשת ומה שידמה להם כי אם מזיקים לאדם כמו שנבאר בג"ה אצל ביאורינו לאזהרות ההם וכן תחת זה הסוג הוא שלוח קצת הטמאים כמו הצרוע והזב כי יבא מהם היזק לאשר היו אצלם ותחת זה הסוג תהיינה גם כן קצת הטמאות לזאת הסבה בעינה. ואולם הטמאות אשר לא תחיינה להסרת ההיזקים אבל להרחיקה מהמשך אחר ההנאות הגופיות הם תחת לא תנאף ולזה תהיה מצות נזירות וענין זולל וסובא תחל לא תנאף באופן מה ר"ל מצד מה שהוא זולל וסובא ואולם מצד מה שאינו שומע בקול אביו ואמו הוא תחת דבור כבד את אביך ולפי שכבר נשלמה האזהרה בזה האופן מעשיית הע במדות בכל הפנים שאפשר בא אחר כן הצווי בעשיית הטוב במדות והוא שיגיע האדם לכל בעל חוק חקו ובא הציווי בזה ביותר ראוי מהם וביותר נבחר אצל האנשים כלם והוא כבוד ההורים כי זה מקיף על כל מה שבזה הסוג והוא כי מי שלא ירגיל עצמו לתת לכל הדברים חקם יקרה לו שלא יתן להוריו חקיו מהכבוד אשר בו הפסד מבואר לאנשים כלם ותחת זה הסוג הוא שיירא האדם מהוריו וממנהיגי המדינה כמו המלכים והשופטים והחכמים ושיכבד אותם ותחת זה הסוג גם כן הוא שיתן האדם שכר השכיר וישיב הפקדון אשר הפקד אתו ומה שידמה לזה ותחת זה הסוג גם כן הוא שייטיב האדם לדלים האמללים מאשר הביא אלוה בידו כי כמו זה חוק לו כשיתבונן בדרכי ה' שיטיב לכל אחד מהנמצאות בתכלית מה שאפשר ושם גם כן בטבע הנמצאות שישפיע אחד לחברו ממה שחננו השם יתע' מהשלמות והנה תחת זה הסוג הוא ההלואה לדלים ולתת להם צדקה די מחסורם והשבת העבוט והשמטת כספים וענין השמטה והיובל ושלוח עבדים ומתנות עניים בכללם ומתנות כהונה ולוייה ומה שידמה לזה. ובהיות הענין כן הוא מבואר שאלו המצות הששה האחרונות הם מקיפות על כל המצות אשר תהיינה בהסרת הרע ובעשיית הטוב במדות וזה גם כן בהדרגה וסדור ישר כמו שביארנו ואחר זה זכר מה שיש בו מבא למדות ולדעות במצות כמו המועדים והדומה להם וזכר היותר חזק מהם והוא השבת לפי שמי שיזלזל במועדים יבא לזלזל בשבת ובזה האון היתה הזהרה העשיית מלאכה ביום השבת מקפת על שמירת המועדים בכללם והנה תחת זה הסוג הוא עניין הקדשים אשר בו מבוא במדות והדעות כמו הקדשת המקדש על מדרגותיו והקדשת שאר הקדשים על מדרגותיהם אשר בהם תועלת במדו' ובדעות. וזה יתבאר ביאור יותר שלם אצל המאמר במועדי' ובענין הקרבנות והקדשים והמקדש ואחר זה זכר מה שיש באלו המצות מעשיית הטוב כאלו תאמר השביתה ביום השבת והזכיר' לקדשו וזה מקיף גם כן על השביתה במועדים וזכירתם לקדשם ונהוג הקדושה במה שקדשו השם יתע' לזאת הסבה ואמנם זכר השבת להיו' החזק שבדברים אשר תחת זה הסוג ואחר שהשלים בדבור זכור את יום השבת לקדשו המקפת על כל מה שבזה הסוג המשותף למדות ולדעות מהמצות שב להזהיר על ההסרה מהרע בדעו' והנה החזק שבדברים האלו הוא מה שהיה בעצם השם יתע' והנה ימצא בזה הסוג מה שיקל מאד לאנשים כמו ההשבע בשמו לשקר ולשוא שהוא מביא לבזות השם יתעלה ולהקל בו כמו שביארנו ולזה הקדי' האזהרה בו עם שבזה גם כן מבוא בזה במדו' אלא שמה שיש בו מההסרה מהרע במדות הוא נכלל במדות בדבור לא תענה כמו שזכרנו ואחר זה זכר האזהרה מנתינת האלהות לזולתו ותחת זה הסוג הוא ענין העוננות והנחש והכשוף ומה שידמה להם כמו שנבאר אצל המאמר באלו המצות ובמה שינהג מנהגם ואחר שהשלים לזכר מה שיסיר מהרע בדעות צוה על עשיית הטוב בדעות וזכר החזק שבהם והוא ההאמנה בשם יתע' והנה הוא נכלל בזה הסוג מה שיביא להאמין בשם יתע' כמו עבודתו ויראתו ואהבתו וההליכה בדרכיו וההאמנה בדברי נביאיו והבניית המקדש על האופן שהתבאר בתורה ותפילין ומזוזה וקריית שמע וההגייה בתורה ומה שידמה לזה מהמצות המישירות לידיעת השם יתע' ולדעות האמתיות ובכאן נשלמה הסבה בסדור עשרת הדברים והתבאר שהם מקיפים במצות התוריות בכללם
@53 ונשוב אל מה שהיינו בו מהביאור אמר שכל העם ראו אלו הדברים המרעידים שהיו במעמד הר סיני בעת השמיעו להם השם יתע' עשרת הדברים האלו במה שחדש על דרך מופת מקול הדברים בענן והם הקלות והלפידים וקול השופר וההר שהיה עשן ונתרחקו מפני זה מהר סיני כי יראו מאד מהשם יתעלה לי מה שראו מעוצם נפלאותיו שם וגודל מעלתו עד שיראו שימותו מפני מה שראו בעיניהם מכבוד השם יתע' לזה אמרו אל מש אחרי שמעם עשרת הדברים באמצעות קול הדברים שחדש השם יתע' בענן דבר אתה עמנו ונאמין דבריך ונקבל אותם ואל ידבר עמנו אלהים בזה האופן הנפלא פן נמות מפני חסרוננו והיותנו בלתי ראוים לראות כבודו ולשמוע דבריו והנה כמו זה אמר מנוח מות נמו' כי אלהים ראינו. ולזה אמר במשנה תורה השמע עם קול אלהים מדבר מתוך האש כאשר שמעת אתה ויחי. ויאמר משה אל העם אל תיראו כי לא הראה אתכם השם יתע' אלו הנפלאות בכבודו אשר ירד בענן להמית אתכם אבל עשה זה לרומם אתכם בזאת התורה הנפלאה כי זה יהיה סבה אל שתקבלו אותה. והראה לכם גם כן אלו הענינים המרעידים כדי שתראו ממנו ותלכו בתורתו בעבור מה שנתבאר לכם מגודלו ועצמו והפלגת גבורתו לעשות כל אשר יחפוץ. והנה אחר זה עמד העם מרחוק כי לא היה רצונם לשמוע עוד דברי התורה כי אם על ידי משה ומשה נגש אל עב הענן אשר היה לו מגיע שם השפע האלהי. וראוי שתדע כי אלו עשרת הדברים הגיע למשה בנבואה ובעת הגיעם אליו היה מתחדש קול הדברים מתוך האש מגיד אותם לישראל כמו שאמר והאלהים יעננו בקול ר"ל שמה שהיה מדבר אליו היה מגיע לו עם קול מוחש היה מתחדש אז ואמר במשנה התורה את הדברים האלה דבר יי' אל כל קהלכם בהר מתוך האש ואולם מה שאמרו רז"ל אנכי ולא יהיה לך מפי הגבורה שמענום הוא נאמר על צד הדרש כי הם בלי ספק שמעו אותם כלם מפי הגבורה כמו שביארנו ואולם נאמר זה למצוא רמז על דרך הגימטריא במניין מצות התורה שהם תרי"ג וכאשר הוקשה להם כי תורה לא יהיה על צד הגימטריא כי אם תרי"א אמרו זה המאמר:
@53 **ויאמר** יי' אל משה כה תאמר אל בני ישראל אתם ראיתם כי מן השמים הגעתי אליכם דברי באש כי לא ראיתם בהר כל תמונה וזה ממה שיבאר לכם שאינני בעל גוף וגויה ולה ראוי לכם שלא תעבדו לאחד מהנמצאות הבעלי גוף ולפי שכבר הזהיר בזה בביאור בדבור לא יהיה לך שב להזהיר בכאן במה שיביא לעבוד אחד מהנמצאים בעלי גוף ואמר לא תעשון בבניני והוא בית המקדש צורות לנוי של כסף או של זהב שיביא לחשוב בהם שיהיו אלוהות כמו צורות האדם וצורות הכוכבים ומלאכי השרת לפי מה שחשבו האנשים שתהיה להם צורה כי אלו יתכן שיטעו בהם האנשים ויחשבו שיהיו אלוהות לעוצם מעלתם על שאר הנמצאות ולהיותם בעלי שכל ואע"פ שכבר באה המצוה לעשות שם שנים כרובים זהב שהם על צורת בן אדם הנה הזהיר מעשו' מהם יותר כמו שנתבאר במכילתא עם שהשם יתעלה התחכם ששם ענינם באופן שאין לטעות בהם שיהיו אלוהות כמו שנבאר במה שיבא בג"ה. וראוי שתדע כי צורת האד' לא יעברו על עשייתה אם לא היתה בולטת כי אינה תמונת האדם לפי מה שיורגש ממנו בזולת זה האופן וזה מבואר בנפשו. ואולם צורת הכוכבים והמזלות הנה יעברו עליה אע"פ שהיא שטוחה כי צורתם היא שטוחה לפי מחשבת האנשים וכן צורת מלאכי השרת אשר יסכימו האנשים בהם יעברו על עשייתה אע"פ שהיא שטוחה לפי שאין להם צורות ותמונות על דרך האמת. מזבח אדמה תעשה לי. ר"ל שיהיה מחובר לקרקע שלא תבנהו על גבי ספין ולא על גבי עמודים כדי שלא תתן התנשאות ורוממות למה שתעבוד בו השם יתע' כי זה הוא יביא לחשוב שתהיה אותם העבודה הנעשית במקדש לתמונה ההיא ואצל המזבח בעזרה תזבח עליו עולותיך ושלמיך וצאנך ובקרך שיהיו קדשים כמו הענין בעולות ושלמי' הקרבי'. ואולם המקומות שתהיה בהם זביחת הקדשים בעזרה יתבארו בג"ה בחומש ויקרא וזה בכל מקום אשר יהיה שמי נזכר שם תדבק השגחתי ואברכך היה המקום גבוה או שפל כי עיני משוטטות בארץ לדעת כל אשר בארץ ואם אני בתכלית הגובה ולזה לא ארצה שיהיה נפרד המזבח מהארץ ואם יגיע העת שתבנה לי מזבח אבנים וזה יהיה אחרי שתישבך בארץ כי במדבר עשו מזבח נחשת כמו שיתבאר אחר זה כדי שיוכלו להעתיקו עמהם בלכתם במדבר ואמנם אחר זה צוה לעשות מזבח אבנים כמו שאמר מזבח אבנים שלמות תבנה את מזבח יי' אלהיך הנה תחוייב להמנע שלא תבנה שם אבני בניניך אם יהיו אבני גזית כי מפני שהנפת חרבך על האבן ההיא חללתה אותה. ולא תעלה במעלות על מזבחי אבל יהיה המקום ההוא שתעלה בו למזבח בזולות מעלות ויהיה הולך במדרון באופן שתעלה בו בזולת מעלות כדי שלא תצטרך לעשות פסיעה רחבה שתגלה ערותך עליו אבל תעלה בו עקב בצד גודל בזולת הרחבת הרגלים ואע"פ שהיו להם מכנסים לכסות בשרם הנה רצה השם יתע' לכבודו שלא יראו מכנסיהם במקום ההוא אשר יעלו בו על המזבח. וראוי שתדע כי המזבח יחוייב שיבנה מאבנים שלמות שלא יהיה בהם חסרון ולזה אם היה באבן חסרון מוחש הנה האבן ההיא פסולה לבניין מזבח וזה החסרון הוא כדי שתחגור בה הצפורן כי כשהיתה בזה האופן איננה שלמה לפי המוחש וכן אין ראוי שיפסלו ממנה דבר באופן שתהיה גזית כי כשהיתה בזה התואר איננה שלמה ואע"פ שאין בה פגימה ולזה אמר לא תבנה אתהן גזית לעבור עליה בלא תעשה והנה אם נגע בה הברזל אע"פ שנשארה שלמה הנה האבן ההיא פסולה שנאמר כי חרבך הנפת עליה ותחללה ר"ל שהנפת החרב עליה לפסלה היא מחוללת. וראוי שתדע שאם שם במזבח קצת מהאבנים אבני גזית או שנגע בהם ברזל הנה האבנים ההם פסולות לעבודה לא המזבח כי בשאר האבנים יתכן שתעשה שם העבודה שנאמר ותחללה ר"ל שהיא מחוללת ואין המזבח כולו מתחלל בעבורה. ואולם שאר בנין בית המקדש לא מנעה התורה לבנות גזית ומה שאמר ומקבות והגרזן וכן כלי ברזל לא נשמע בבית בהבנותו אינו מורה שלא יבנהו גזית כי בבית לא נשמע אבל בחוץ נשמע בכמו שביארו במכילתא. והנה התועלות המגיעות מזה הספור הם רבים:
@53 **התועלת** הראשון הוא במצות. והוא להאמין כי יש שם אלוה שליט על כל הנמצאות להגיע אותם אל אשר יחפץ ושהוא יבלבל הסדור המסודר מהכוכבים להטיב לדבקים בו וזה הוא מה שאמר אנכי יי' אלהיך אשר הוצאתיך מארץ מצרים מבית עבדים. ואולם התועלת בזאת המצוה הוא בדעות כי כשלא יאמן שתהיה שם עלה פועלת לא תהיה שם חכמה כלל כי החכמות יחקרו בסבות אשר בעבורם יהיה הדבר וכאשר לא תהיה שם סבה פועלת לא תהיה שם סבה תכליות כלל כמו שהתבאר במקומותיו וכן כשלא יאמן בשיהיה משגיח מאישימין האדם בזה האופן תמנע ממנו פנה גדולה בדעות כמו שביארנו ברביעי ממ"י עם שהוא מן הגדולות שבפנות התוריות:
@53 **התועלת** השני הוא במצות. והוא למנות מנתינת האלהות לזולתו מהנמצאים וזהו מה שאמר לא יהיה לך אלהים אחרים וגו'. ואולם התועלת בזאת המצות הוא בדעות וזה כי כשינתן האלהות לזולתו יפול הרבה מהאדם מחכמת הנמצאו' והיקר שבהם ותמנע הצלחתו הנפשית האמתית שהיא מגעת כשנשכיל ונדע השם יתע' כפי היכולת כמו שאמרנו בספ' מ"י וכבר אמר זה הנבי' בביאור כי אם בזאת יתהלל המתהלל השכל וידוע אותי וכ"ש כשינתן האלהות לפסולים כי זה ממה שיפיל חכמת הנמצאו' בכללה וזה מבואר בנפשו למי שנתפלסף:
@53 **התועלת** השלישי הוא בדעות. והוא להודיע כי השמי' הם לצד המעלה והארץ לצד המטה. ואע"פ שיש חלק מהשמים נכח כפות רגלינו כי הוא מקיף בארץ וזה הדבר כבר נתבאר בטבעיות והנה הודיע זה באמרו אשר בשמים ממעל ואשר בארץ מתחת:
@53 **התועלת** הרביעי הוא בדעות. והוא להודיע כי כבר יגיע רע מהשם יתע' לעוברים על דבריו ושהוא בלתי מכוון בעצמו ולזה לא יתמיד מציאות הרעות כהתמיד מציאות הטובות השופעות ממנו לאוהביו. רצוני שאלו הרעות ישארו זמן מועט והטובות ההם יתכן שיתמידו לאלפים מהדורות והיה זה כן לפי שאין מדרך השם יתע' שיכוין להגעת הרעות אם לא מצד כוונתו אל הטוב והנה הורה על זה באמרו פוקד עון אבות על בנים על שלשים ועל רבעם לשונאי ועושה חסד לאלפים וגו' כמו שביארנו במה שקדם:
@53 **התועלת** החמשי הוא במצות. והוא להזהיר מההשבע בשם יתע' לשוא ולשקר וזהו מה שאמר לא תשא את שם יי' אלהיך לשוא. והנה התועלת בזאת המצוה הוא בדעות ובמדות ואולם מה שהוא ממנה בדעות הוא להעיר על שמציאות השם יתע' הוא אמת ושיש בקיומו צורך לנמצאות לא יתכן שיעמדו זולתו כי הוא מתמיד מציאותם ושומר אותו תמיד בתכלית מה שאפשר. ולזה אין ראוי שישבעו בשמי לשקר ולא לשוא ולבטלה כי זה יביא לחשוב שלא יהיה השם יתעלה נמצא או שלא יהיה בו תועלת לנמצאות. ואולם מה שהוא ממנה במדו' הוא שאם לא ייראו האנשים יראה עצומה מההשבע בשמי לשקר לא יהיה בכאן דרך ארץ לשופטים לשפוט בין האנשים במשאם ומתנם במה שיכפרו אותו קצתם לקצת. כי לא יתברר להם עם מי האמת ואולם כשייראו מהשבע לשקר הנה יוציאו האמת מהם על יד השבוע' שתהיה בין שניהם והכלל הנה התועלת המגיע בזה בקבוץ המדיני הוא עצום מאד. ואולם שרשי זאת האזהרה הם ששה:
@53 **השרש** הראשון הוא שתהיה השבועה בשם יתעלה או בשם אחד מהתארים שהש' יתע' נקרא בהם כמו אל או רחום או חנון ומה שידמה להם כי כל אחד מהם הוא שם יי' לפי שהוא נקרא בהם כבר נתבאר זה ברביעי משבועות:
@53 **השרש** הב' הוא ששבועת שוא תהיה בשני פנים האופן הראשון הוא שישבע לחנם ולבטלה כמו שנשבע בשם יי' על הדבר הידוע ומפורסם לכל כמו שישבע על האיש שהוא איש ועל האשה שהיא אשה ועל האבן שהוא אבן כבר נתבאר זה בירושלמי מנדרים האופן השני הוא שישבע לשקר וזה יחלק לג' חלקים הראשון הוא שיהיה הדבר ההוא שקר מבואר מצד עצמותו כמו שישבע על האיש שהוא אבן ומה שידמה לזה כבר נתבאר בג' משבועות וזה אמנם יהיה כשלא יאמר על דרך הפלגה וגוזמא כמו שישבע שהבנין הגבוה ראשו בשמים או שישבע במחנה שיש בו רבים מהאנשים כיוצאי מצרים על דרך הגוזמא ואע"פ שאין בו אלא רבוא אחד או יותר מעט כי כשיהיה הענין כן לא יעברו עליו משום שבועת שוא כי כן דרך האנשים לדבר בו כשיפליג לדבר מה. והנה לא נתכוון זה כי אם על גובה הבנין או על רבוי אנשי המחנה כבר נתבאר זה בג' מנדרים. השני הוא שיהיה הדבר שנשבע לעשותו בלתי אפשר לקיימו בצד הטבע כמו שישבע שלא יישן ג' ימים כי טבעו יאנוס אותו תוך זה הזמן כבר נתבאר זה בג' משבועות. השלישי הוא שיהיה הדבר ההוא שנשבע עליו בלתי אפשר לקיימו מצד התורה כאלו תאמר שנשבע שלא יאכל מצה בלילי הפסח כבר נתבאר זה בג' משבועות:
@53 **השרש** השלישי הוא שהעונה אמן אחר שהשביעוהו בשם יי' לשוא דינו דין הנשבע בשם יי' לשוא וזה דבר נלמד אותו ממה שנאמר בסוטה כשהשביע אותה הכהן בשבועת האלה ואמרה האשה אמן אמן למדנו מזה שדין העונה אמן אחר שבועה דינו דין הנשבע כבר נתבאר וזה בג' משבועות:
@53 **השרש** הרביעי הוא שמי שקלל עצמו בשם יי' לשוא או עונה אמן אחר הקללה דינו דין הנשבע בשם יי' לשוא כי הקללה היא שבועה כמו שיתבאר מענין הסוטה שהיו הדברים שאמר לה הכהן אלות וקללות ונקרא הדבר ההוא שבועה ובכלל הנה הכפירה בשם יתע' היא יותר מבוארת במי שקלל עצמו בשם יי' לשקר ממה שהוא בנשבע בשמו לשקר כי זה יורה שהוא יאמין שאין שם אלוה או שאין לו כח להרע ולהטיב וכן הענין במקלל עצמו בשם יתעלה לבטלה וזה מבואר במעט עיון עם שזה יורה שיאמין שאין בו תועלת לנמצאות כבר נתבאר זה בד' משבועות:
@53 **השרש** החמישי הוא שאם כיון לדבר שאינו שוא אצל מחשבתו ויצא מפיו דבר שוא פטור שהרי לא נשא שם יי' לשוא כבר נתבאר זה בג' משבועות ובג' מנדרים:
@53 **השרש** הששי הוא שאם היה אנוס על שבועת שוא פטור וזה מבואר מהשרשים הכוללים כבר נתבאר זה בג' מנדרים:
@53 **התועלת** הששי הוא במצות והוא לזכור את יום השבת לקדשו בדברים ולשבות בו ממלאכה ושלא לעשות בו מלאכ וזהו אמרו זכור את יום השבת לקדשו והנה התועלת בזאת המצוה הוא בדעות ובמדות. ואולם מה שהוא ממנה בדעות הוא להעיר שהעולם נתחדש אחר שלא היה ושסוגי הנמצאות על מדרגותיהם בסדר הבריאה לפי מה שחדש אותם השם יתעלה ביום הבראם וכללם בששה סוגים והמדרגה השביעית היה בהמשכתו המציאות על ענינו הטבעי במה שיושפע לו ממנו והנה הידיעה בזה הוא חלק גדול מחכמת הנמצאות כבר יתבאר זה מדברינו בששי מ"י ובפירושנו למעשה בראשית והנה זהו מה שאמר כי ששת ימים עשה יי' את השמים ואת הארץ את הים ואת כל אשר בם וינח ביום השביעי והנה בזה בדעות עוד תועלת וזה שזה שיהיה זכר ליציאת מצרים אשר היו ישראל עבדים ולא היה להם רשות לשבות ממלאכה כמו שאמר במשנה תורה בדבור שמור את יום השבת לקדשו. והנה התועלת המגיע מזכירת יציאת מצרים הוא ההאמנה בשם יתע' ושהוא השליט על הנמצאות לעשות מהם כחפצו וזה התועלת הוא משותף לכל המועדות והנה ימצא התועלת בו בהשלמת הנפש וזה כי טרדת האדם בעסקיו תמנע הכו מהחקירה בידיעת סודות המציאות אשר יעמידו האדם על השגת השם יתעלה לפי מה שאפשר שהוא תכלית שלמות הנפש וכאשר היה בכאן זמן ימצא בו האדם בו פנוי מהעסקים הנה יתכן לו שישתמש בזמן ההוא בעבודת השם יתע' לבד וכשהשגתו ולהורות שכונת התורה היתה בשבת לזה התכלית אמר ששת ימים תעבוד ועשית כל מלאכתך וביום השביעי שבת ליי' אלהיך ר"ל שלא נעשה אז מלאכה כי אם ליי' וזאת המלאכה היא להשכיל ולידע השם יתע' לפי היכולת וזה כי המלאכה המעשית נאסרה אפילו גבוה שנאמר לא תעשה כל מלאכה. וזה התועלת הוא גם כן משותף למועדים כלם באופן מה והנה ימצא עוד דתועלת בו בדעות והוא שכבר למדנו מענין שבת שבכאן לצורות שבע מדרגות והמדרגה השביעית היא קדש והיא השם יתעלה והם צורות היסודות והם האיכויות כאלו תאמר החום והקור והלחות והיובש וצורות המתדמה החלקים המורכבים מהיסודות וצורת הצמחים וצורות הב"ח וצורת האדם והוא השכל ההיולאני וצורות השכלים הנבדלים והצורה השביעית אשר שפע ממנה כל אלו הצורות היא השם יתע' והנה לשאר הצורות ימצא דבקות מה בחומר ומלאכות מיוחדות יסודרו מהם זולתי השם יתע' וזה כולו מבוא במעט עיון למי שעיין בדברינו בחלק השלישי המאמר הששי ממ"י ואולם בענינים המדיניים ימצא בו תועלת גם כן וזה כי יקנה החריצות לבעלי המלאכה בעשיית מלאכתם ולא יחושו לעמל המגיע להם במלאכה ההיא לחשבם כי עוד זמן קרוב ינוחו ר"ל שבכל שבוע ינוחו יום אחד ועוד ימצא בו תועלת בענינים המדיניים וזה כי המסודר מהגרמים השמימיים מהרע לא יזיק לאוהבי השם יתע' בעת היותם דבקים בו כמו שביארנו ברביעי מספר מלחמות יי' ולפי שהכוכבים המושלים בליל שבת ויומו יקרה להם שיגיעו הרבה מההיזקים לאנשים כמו שהתבאר בחוש לפי מה שנתפרסם בחכמת משפטי הכוכבים והם מאדים ושבתי והנה רצה השם יתעלה שישבתו ישראל ממלאכה ביום השבת כדי שישתדלו בעבודתו ויהיו בזה נצולים מהרעות ההם וגם שבשביתתם מהמלאכות תגיע להם הצלה מהרבה מהרעות ההם והמשל שאם היה הרע שיגיע מהם שיקרה לאדם הפסד ונזק בעשיית מלאכתו או בלכתו בדרך הנה ישמר מההיזק ההוא כשישמר מההליכה בדרך ההוא או מעשיית המלאכה ההיא. ולזה אמר הנביא לישראל בעת היותם נכונים אל שיגיע להם הרע לך עמי בא בחדריך וסגור דלתך בעדך חכי כמעט רגע עד יעבור זעם. ובכלל הנה כשיהיה האדם נכון שיגיעו לו רעות הנה תמצא שכל מה שירבה לעשות מהפעולות יסבב להגיע הרע לו ולזה ישמר מהרע בהשמרו מעשות עסקיו. והנה צוה השם יעת' לקדש זה היום בדברים לתת לו מעלה גדולה בנפש כי בזה יהיה האדם נשמר יותר מעשות מלאכה בו עם שזה הקדוש יזכיר לאדם כי שבת היום וזאת הזכירה שתהיה בדברים ראוי שתהיה בכניסתו להבדיל בינו ובין זמן העובר וביציאתו להבדיל בינו ובין הזמן העתיד:
@53 **והנה** שרשי המצוה הזאת הם י"ג והם לקוחים מגדר המלאכה זולת המעט מהם. ואולם גדר המלאכה היא שהיא פעולה אנושית מסודרת משכל מעשי והיא תעשה בתואר מוגבל ובכלים מוגבלים יכוון בו תכלית מה מהתכליות שהם טוב מה וזה כלו מבואר מענין המלאכית:
@53 **השרש** הא' הוא שכבר יתחייבו מכל סוג מן המלאכות ביחוד כמו שביארנו מאמרו לא תבערו אש בכל מושבותיכם וזה שההבערה היתה בכלל המלאכות ויצאת מהם לבאר ממנה שעל כל אב מלאכה יתחייבו עליה ביחוד עד שאם עשאם כלם בהעלם אחד יתחייב חטאת על כל אחת ואחת והם ט"ל מלאכות כמו שזכרנו כבר נתבאר זה בשביעי משבת:
@53 **השרש** הב' והוא שמה שאינו מסודר משכל מעשי לא יכנס בגדר המלאכה כמו שבירת הפרות לאכול מה שבתוכם ושבירת הכלים לקחת האכל או המשקה שבתיכם אם לא עשה השבירה בדרך מלאכה ואומנות וזה כי הב"ח גם כן יוכלו עליו ולזה לא יכנס בגדר המלאכה כבר נתבאר זה בכ"ב משבת:
@53 **השרש** הג' הוא שהעושה מלאכה בזולת כליה הלקוחים בגדרה ובזולת התואר המסודר בה פטור כמו שנשא המשא ברגל או שהוציאו שנים מחט או שכתב בפיו או שאחזו שנים הקלמוס וכתבו כבר נתבאר זה בו' ובז' ובי"ב משבת ובמקומות רבים זולתם:
@53 **השרש** הרביעי הוא שהמלאכה שאינה מתקיימת לא תכנס בגדר המלאכה כי נעדר ממנה התכלית המגיע כמלאכה ההיא כמו הכתיבה במשקין שאין רשומן נכר ועומד או הכתיבה בירקות שהם נפסדין בזמן קצר כבר נתבאר זה בי"ב משבת:
@53 **השרש** החמישי הוא שתהיה כוונתו לעשות מלאכה שהו' עושה כי בזולת זה לא יכנס בנגר המלאכה. וזה מבואר מגדרה כבר נתבאר זה בראשון מחגיגה ולה יתבאר שאם עשה מלאכה כמתעסק ובזולת כונה פטור כבר נתבאר זה בי"א משבת ובי' מערובין. ובמקומות רבם זולתם ומזה השרש יתבאר שאם לא עשה המלאכה ההיא שיכוין אליה אע"פ שנעשית מלאכה אחרת לא יכון אליה פטור כבר נתבאר זה בד' מכריתות וב' משבת:
@53 **השרש** הו' הוא שהמלאכה שלא יכוין בה טוב מה שלא יתחייבו עליה כמו השורף גדיו של חברו ולא להקנס ממנו כי אם על דרך הקלקול וההשחתה כבר נתבאר זה בשני ובתשיעי משבת ובא' מחגיגה:
@53 **השרש** הז' הוא שכבר תחייבו על המלאכה אע"פ שאינה מכוונת אם לא בעבור זולתה כי אין מתנאי התכלית בגדר המלאכה שלא יהיה בעבורה תכלית אחד וזה מבואר בנפשל והשמו שכבר יתחייבו על ההבערה כמו שביארה התורה ואע"פ שהיא בעבור זולתה כאלו תאמר שהיא לבשל או לאפות כבר נתבאר זה בד' מכריתות ובז' משבת:
@53 **השרש** השמיני הוא שהמלאכות שהגיעו חלקיהם אל תכליתם באופן מה שהגיעו כמו שמלאכת הכתיבה והאריגה והבנין והנוהג מנהגם שהחלק המתחדש מהם הוא מתחדש על תכליתו עד שהם נשארים בזה האופן שהם מתחדשים הנה יתחייב על החלק הקטון שיהיה במלאכה ההיא מסכים הסכמה מה לכל והוא במלאכות שיהיו בקבוץ האחרים בשנים מהאחרים ההם כי הוא הקבוץ הראשון כאלו תאמר שהכותב יתחייב כשכתב שתי אותיות והאורג כשארג ב' חוטין ובמלאכות שיהיו הכמה המתדבק יתחייבו בחלק הקטן שידבק בו באופן מהתכלית מהמלאכה ההיא כבר נתבאר זה בו' ובז' משבת ומקומו' רבים אל תם:
@53 **השרש** הט' הוא שהמלאכה שלא הגיע התכלית בחלק ממנה ובאופן שזכרנו לא יתחייבו על החלק ממנה כי לא יקרא החלק ממנה מלאכה וזה מבואר מגדר מלאכה המשל כי ההוצאה היא עקירת החפץ ממקום מוקף מחיצות והנחתו במקום בלתי מוקף כמו שיתבאר והנה מי שעקר ולא הניח או הניח ולא עקר הוא מבואר שלא יצדק על אחד מהם שיהיה מוציא זה החפץ כמו שביארנו במה שקד' ולזה לא יתחייב על כמו זה החלק מהמלאכה אם עשה המלאכה ההיא בכללה כבר נתבאר זה בראשון משבת:
@53 **השרש** העשירי הוא שההוצאה מרשות היחיד לרשות הרבים או ההבאה מרשות הרבים לרשות היחיד תקרא מלאכה וזה מבור ממה שאמר איש ואשה אל יעשו עוד מלאכה לתרומת הקדש ויכלא העם מהביא למדנו מזה שההבאה היא מלאכה וכבר יתבאר זה עוד שהמקושש שנתחייב מיתה בעבור היותו מקושש למדנו מזה שנשיאת החפצים היא מלאכה כמו שביארנו במה שקדם והוא על צד שני פנים. האחד הוא הבאת החפצים מחוץ לפנים כמו הענין במלאכת המשכן או הוצאתם לחוץ והוא מבואר מאד כי זה מן המלאכות כי הרוב שיעשה הוא לקנות החפצים או למכרם או להוציא מהבית מה שלא יאות שישאר בבית או להביא לבית מחוץ מה שיצטרך שם ולה אמר הנביא לא תוציאו משא מבתיכם ביום השבת ומה יתבאר שנשיאת החפצים בבית ממקום למקום או מבית לבית לא יקרא מלאכה כי לא הזהירם על נשיאת המשא כי אם על הוצאתו מהבתים והאופן השני הוא שיהיה האדם בחוץ ברשות הרבים ויוציא החפצים ממקומו שהוא ד' אמות שם בר"ה כמו העין במקושש כי זה גם כן הוא מבואר שהוא מלאכה כמו שביארנו במה שקדם כבר נתבאר זה בי"א משב' וראוי שתדע שמה שישא אותו האדם לתכשיט או לרפואה כמו האספלנית ומה שישא לשמירה דרך מלבוש לא יכנס בגדר מלאכה וזה מבואר כי כמו שנשיאת המלבוש אינה מלאכה כן הענין באלו כי הם לצורך הנושא אותם כבר נתבאר זה בו' משבת ולפי שהמקושש היה מקושש במקום שהיה רשות הרבים והוא המדבר למדנו שהמעביר החפץ יותר מד' אמות ברשות הרבים חייב ולפי ששעור רשות הרבים לא יתכן שיהיה בפחות מרוחב י"ו אמות באופן שיאות שישתמשו בו רבים ולי יעיקו קצתם לקצתם לפי מה ששערו חכמים ומזה היה בדרך הרבים רוחב י"ו אמה הנה ידענו שרשות הרבים שינהג בו זה הדין לא יהיה בפחות מזה הרוחב מי"ו אמו' והוא מבואר גם כן שאם היה מקורה אינו רשות הרבים כי הוא כמו בית וג"כ הנה מפני שההוצאה היא מפני' לחוץ שאינו פנים כמו שיתבאר מדברינו בזה המקום הוא מבואר שהוא ראוי שלא יהיה רשות הרבים מוקף מחיצות באופן שיפול עליו שם פנים ולזה יחוייב גם כן שלא יהיה מקורה ולפי שההוצאה מתוך מה לא תשלם אלא אם לא היה חתוך ההוא מוגבל ומוקף למדנו שהוא ראוי שיהיה רשות היחיד מוקף ארבע מחיצות ולפי שאינו ראוי להשתמש בו אם לא היה גבהו י' טפחים ולא יתכן גם כן שיקרא בית לפי הוראת הגדר בפחות מזה השעור ואם לא היה עם זה שעורו בארך ד' טפחים או יות' וכן הענין ברוחב ידענו שלא יהיה רשות היחיד אם לא היה גבוה י' טפחים או יותר וד' בארך וברוחב ולזה הוא מבואר שההוצאה מרשות היחיד למקום שאינו רה"ר לפי מה שהגבלנו לא יתחייבו עליו מן התורה וכן הענין בהבאה ממקום רשות הרבים למקום שאינו רשו' היחיד לפי מה שהגבלנו וג"כ הנה ההוצאה לא תשלם אם לא היתה ממקום נח החפץ אל מקום ינוח בו החפץ כמו שבארנו במה שקד' והנה המקו' הראשון שראוי שינוחו בו החפצים אינו בארך פחות מארבע טפחים וכן הענין ברוחב למדנו מזה המקום שאינו ארוך ארבע טפחים ולא רחב ארבע טפחים אין העקירה ממנו עקירה ולא ההנחה בו הנחה ואולם ידו של אדם הוא מקום ראוי להניח בו החפץ כי האדם ישמרהו בידו ויאחזהו בו ולה תהיה העקירה ממנו עקירה וההנחה בו הנחה וגם כן הנה מפני שרשות הרבים הוא המקום שמשתמשים בו רבים הוא מבואר שמה שיהיה ברשות הרבים שאינו ראוי שישתמשו בו רבים. כמו הימים והנהרות או התל שהיה ברשות הרבים למעלה מעשרה טפחים אין דינו די רשות הרבים כי לא יאות שישתמשו בו רבים כבר נתבאר זה בי"א משבת ובראטשון ממנו ובמקומות רבים זולתם:
@53 **השרש** הי"א הוא שהמלאכה שעשה בכליו של אדם בשבת לא יתחייב עליה כאלו תאמר שהניח הפת בתנור מערב שבת ונאפה בו בשבת או מה שידמה לזה וזה כי אין האדם מצווה על שביתת כליו כבר נתבאר זה מראשון משבת:
@53 **השרש** הי"ב הוא שאין ראוי לאדם שישתדל שעשו מלאכו בשבת בנו ובתו הקטנים שנאמר לא תעשה כל מלאכה אתה ובנך ובתך ועבדך ומזה יתבאר שהתורה הזהירה אותו על שביתת בנו ובתו הקטנים שנאמר ועבדך ואמתך וכוון בהם אל הקטנים כמו שביארנו במה שקדם:
@53 **השרש** הי"ג הוא שהאדם מצווה על 'שביתת בהמתו ממלאכה שנאמר לא תעשה כל מלאכה וגומ'. ואמתך ובהמתך והו' לאו שנתן לאזהרת מיתת בית דין ואין לוקין עליו אמר במקום אחר למען ינוח שורך וחמורך וגו'. אחד שור וחמור ואחד כל בהמה וחיה ועוף כמו שהתבאר מהשרשים הכוללים והוא לאו הבא מכלל עשה ואין לוקין עליו ולזה הוא מבואר שאסור להוציא משא על הבהמה בשבת או לחרוש בה וכבר נתבאר זה מכ"ד משבת הוא מבואר שמה שתשא הבהמה לתכשיט או לשמרה שלא תברח לא יקרא מלאכה וזה מבואר מאד וכבר נתבאר זה בחמשי משבת:
@53 **השרש** הי"ד הוא שדחויה שבת אצל סכנת נפשו כאלו תאמר שחולה שיש בו סכנה עושין לו כל צרכיו בשבת אע"פ שיש בהם מלאכה כי כל המצות נדחות מפני סכנת נפשות זולתי שלש והם ע"ז וגלוי עריות ושפיכות דמים כי התורה נתנה לבריאות הגוף והנפש לא לנקמה והשחתה וזה מבואר מדבריה כמו שזכר וזה אמר במצות התוריות אשר יעשה אותם האדם וחי בהם ואולם ששפיכות דמים אינו נדחה מפני סכנה נפשות הוא מבואר מאד כי מה בצע להציל נפש בהריגת נפש אחרת וכן הוא מבואר מאד שאין ראוי לעבוד ע"ז מפני סכנת נפשות כי אין ראוי להאביד חיי הנפש שהם נצחיים בעבור העמדת חיי הגוף שהם חיי שעה וזה תמצא בחנניה מישאל ועזריה שהפילו עצמם לתוך כבשן האש להמלט מלהשתחות לצלם הזהב שעשה נבוכדנצר ואולם גלוי עריו' הוא מה שיצטרך אל ביאור וכבר ביארו זה רז"ל ממה שאמר בנערה המאורסה שנבעלת בשדה צעקה הנערה המאורסה ואין מושיע לה וזה לאות שאם היה שם אדם ראוי שיהיה מושיע לה באופן שיוכל עליו ואפי' בנפש הרודף אחריה אם לא יוכל להיות מושיע לה בזולת זה האופן. ולזה הוא מבואר שהנפש נדחת מפני העריות וזה ממה שיתבאר ממנו כמעט עיון שאין ראוי לדחות העריות מפני הנפש כבר נתבאר זה בח' מסנהדרין ובראשון מיומא ובשני מע"ז ובמקומות אחרים זולתם הנה זה השרש הוא כולל לכל המצוות באופן שזכרנו:
@53 **התועלת** הז' הוא במצות. והוא לכבד הוריו כמו שאמר כבר את אביך ואת אמך והנה התועלת בזאת המצוה הוא הבמדות כי הוא ראוי שיכבד האדם הוריו מפני התועלת העצום שהועילוהו עם שבזה יתכן שידרוך אל השלמות בקבלו המוסר מהם ואולם שרשי זאת המצוה הם ששה:
@53 **השרש** הא' שיכבד הוריו בדבריו גם לאחר מיתה ובמשאו ובמתנו ויעמוד מפניה' וישמשם כשמוש העבד לרבו זהו כלו מגדר הכבוד ולזה ראוי שישמור מכלמ' הוריו ומשיצערם בצד הצדדים כי זה כלו הפך הכבוד כבר נתבאר זה בראשון מקדושין:
@53 **השרש** הב' הוא שיכבדם מהונו להאכילם להלבישם ולמה שיצטרך להם אם אין לאל ידם או מקנינם אם יש בידם כי המזון יקרא כבוד כאמרו כבד יי' מהונך כבר נתבאר זה בראשון מקדושין:
@53 **השרש** הג' שאין ראוי לאדם לכבד הוריו במה שהוא כנגד השם יתעלה כי הוא והוריו חייבים בכבוד השם יתעלה ולזה הוא מבואר שאם אמרו לו הוריו לעבור על דברי התורה אין ראוי לו לשמוע אל דבריהם:
@53 **השרש** הד' הוא שאם אי אפשר לאדם לכבד הוריו מפני שנשתטו ביותר באופן שלא יוכל לכבדם הנה עושה להם מה שיכול לעשות מהטוב והכבוד ע"י אחרים וישמט מהם כדי שלא יחטא כי התורה לא תצוה דברים בלתי אפשרים וזה מבואר בנפשו וכבר נתבאר זה בראשון מקדושין:
@53 **השרש** הה' הוא שראוי לאדם לכבד אשת אביו או בעל אמו ואע"פ שאינם הוריו וזה כי מזולת זה לא ינהג כבוד בהוריו וזה מבואר מאד כבר נתבא זה בראשון מקדושין:
@53 **השרש** הו' הוא שהעוסק במצוה אחת אין ראוי לו שיעזבה מפני כבוד הוריו אם אינו יכול קיים את שתיהן כי הוא והוריו חייבים במצוה ההיא וכל שכן אם היתה המצוה ההיא תלמוד תורה אין ראוי לבטל תלמוד תורה מפני כבוד ההורים כי תלמוד תורה בעצמו מביא לקיים כל המצול כבר נתבאר זה בראשון מקדושין וממגלה:
@53 **התועלת** הח' הוא במדות. והוא להודיע שכאשר יקרה הפסד הסדור בקבוץ הכי' ימסר הקבוץ המדיני ויביא זה המדינה ההיא לחרבן לרוע ההסכמה אשר בין אנשיה ולה אמר' התור' שאם ישתדלו בזה האופן בתקון הבית יאריכו הימים על הארץ שיורישם השם יתע' וזה מורה שאם לא יתוקן קבוץ הבית בזה האופן לא יאריכו ימים על הארץ לרוע ההסכמה אשר יהיה בין אנשי המדינה ולזה אמר הנביא לישראל אב ואם הקלו בך להודות על שהוא ראוי שיבא עליהם האויב ויגלו מהארץ:
@53 **התועלת** הט' הוא במצות והוא להמנע מהרציחה ותועלת זאת המצוה במדות מבואר:
@53 **התועלת** העשירי הוא הבמצות. והוא להמנע מהניאוף והנה תועלת ואת המצוה במדות הוא מבואר וזה שאם בא האדם אל אשת איש הנה יתכן שתקר' מה הרציחה עם מה שיקרה בזה מהקלקול בקבוץ המדיני וזה שאם תהיינה נקבות האדם בזה הענין במדרגת נקבות הב"ח שיבא עליהם או זה זכר שיזדמן הנה לא יודע מאיזו משפחה יהיו הנולדים ולא יהיה מקצתם לקצת העזר שיצטרך לאדם מפני המשפחה עם שלא יודע ג"כ מהנולד מי הוא אביו ולא יהיה בכאן איש משתדל בהנהגת הנולד ובמוסרו ויצאו מפני זה רוב הנולדים לתרבות רע לא ימלט מהם זולתי מעט מזער. ועוד שכבר יקרה מזה שימותו רב האנשים לטבת רוב המשגל לרבוי הנקבו' המוכנות להן ולזאת הסבה מנעה התורה רוב העריות כמו שיתבאר במה שיבא:
@53 **התועלת** הי"א הוא במצות והוא שלא לגנב ותועלת זאת המצוה במדות מבואר כי מזה יקרה מההפסד בקבוץ המדיני מה שלא יעלם:
@53 **התועלת** הי"ב הוא במצות והוא שלא להעיד עדות שקר ותועלת זאת המצוה במדות מבואר כי בזה יוטל העונש על הבלתי ראוי לו עם שכבר תרבנה בסבת זה הקטטות בין האנשים מצד החמס המחייב לזה העדות:
@53 **התועלת** הי"ג הוא במצות והוא שלא יתאוה האדם דבר מקניני רעהו ולא יחמוד אותם ויקחם לו אע"פ שיתן לו דמים והנה תועלת זאת המצוה במדות מבואר כי אין ראוי שיתאוה שיהיו קניינו רעהו לו כי זאת המדה פחותה מאד ויקרה ממנה הפסד רב בקבוץ המדיני וזה שכאשר התחזק התאוה בזה ישתדלו לגנבם ממנו או לגזלם או להרוג בעל הקניינים ההם. הלא תראה מה שקרה לאחאב מבני חמדו כרם נבות שהיה זה סבה שנהרג נבות מפני שלא רצה למכרו לו:
@53 **התועלת** הי"ד הוא להודיע הסבה אשר הביאה הש"י לחדש אלו הדברים הנפלאים המרעידים בעת השמעו לישראל עשרת הדברים האלה בקול המתחדש שהיה מתחדש על דרך פלא תוך האש והוא להראות להם עוצם גבורת הש"י כדי שייראו ממנו וילכו בתורתו אשר בה יהיה להם ההתנשאות וההתרוממות באופן שיהיו ממלכת כהנים וגוי קדוש וזהו אמרו אל תיראו כי לבעבור נסות אתכם בא האלהים ובעבור היה יראתו על פניכם לבלתי תחטאו:
@53 **התועלת** הט"ו הוא במצות והוא להזהיר מעשות צורות לנוי בבית המקדש ובשאר המקומות מהצורות אשר יתכן שיחשב בהם האלהות כמו צורות האדם וצורות הגרמי' השמימיים ומלאכי השרת וזהו אמרו לא תעשון אתי אלהי כסף ואלהי זהב לא תעשו לכם והנה התועלת בזאת המצוה הו' בדעות והוא להרחיק מנתינת האלהות לזולתו ולזה היתה זאת האזהרה תחת סוג דבור לא יהיה לך וגו':
@53 **התועלת** הי"ו הוא במצו' והוא שיהיה המזבח מחובר לאדמ' לא נפרד ממנה והנה התועלת בזאת המצוה הו' להודיע שהשגחת הש"י תמשך בשפלים ואע"פ שמדרגתו גבוהה עד אין חקר ולזה אמר בכל מקום אשר אזכיר את שמי אבא אליך וברכתיך. וכבר יתבאר במה שיבא בג"ה התועלת המגיע מהענינים אשר היו בבית המקדש ובעבודה הנעשית שם:
@53 **התועלת** הי"ז הוא במצות והוא לשחוט הקדשים בעזרה שנ' וזבחת עליו את עולתיך ואת שלמיך וגו' והנה התועלת בזאת המצוה הו' לישב בנפשותינו מעלת הקדשים כדי שנזה' בהם כפי מה שאפש' ואולם התועלת המגיע בעני' הקדשים יתבאר בג"ה במה שיבא. התועלת הי"ח הוא במצות והוא האזהרה מלבנות מזבח אבנים מאבני גזית אבל תהיינה האבנים ההם שלמות בזולת חסרון כלל. והנה התועלת בזאת המצוה הוא בדעות והוא להעיר על שהשלמות האמתי הוא בש"י ולזה תהיינה האבנים אר מהן יבנה המקום שיעבד בו הש"י שלמות ועוד כי מפני שהטוב והשלמות הוא בש"י מעצמותו. ולא מזולתו רצה להעיר על זה שלא יהיה התקון באבנים ההם באמצעות המלאכה כי אם מעצמותן ולזאת הסבה תהיה האבן ההיא נפסלת כשנהג בה הברזל לפסלה אע"פ שלא חסר ממנה דבר והנה שרשי זאת המצוה הם ארבעה:
@53 **השרש** הראשון הוא שאם לא היתה האבן שלמה אע"פ שלא הונף עליה ברזל וזה אמנם יהיה כשתהיה בה פגימה נכרת בחוץ והוא שתחגור בה הצפורן פסלה שהרי מורגש בה שאינה שלמה כבר נתבאר זה בא' מחולין:
@53 **השרש** הב' הוא שאם הניף עליה ברזל אע"פ שלא פגמה פסלה אותה האבן ולא המזבח שהיא בו שנ' כי חרבך הנפת עליה ותחללה ר"ל שהאבן מחוללת לא האבנים בכללם שזכר תחלה כבר נתבאר בג' מתמיד:
@53 **השרש** הג' הוא שכבש המזבח דינו בזה דין המזבח כי הוא חלק מהמזבח ולזה קראה אותו התורה מזבח שנ' ולא תעלה במעלות על מזבחי כבר נתבאר זה בג' מתמיד:
@53 **השרש** הרביעי הוא שלא נלמוד זה הדין בבנין ההיכל וקדשי הקדשים ואף על פי שהם יותר קדושים ממזבח העולה כי התורה אמרה לא תבנה אתהן גזית רמז בזה כי במזבח לבד יקפיד בזה וכן כשזכר זה במקום אחר לא זכרו כי אם במזבח אמר אבנים שלמות תבנה את מזבח יי' אלהיך וגו' והנה יתבאר זה עוד בבנין שלמה שהיו שם רבים פוסלין את האבנים ואולם מה שאמר שם ומקבו' והגרזן וכל כלי ברזל לא נשמע בבית בהבנותו אינו מורה שלא יהיו האבנים אבני גזית כי בבית לא נשמע אבל בחוץ נשמע:
@53 **התועלת** הי"ט הוא במצות והוא האזהרה מלעלות במעלות על המזבח כדי שלא תגלה ערותך עליו והנה התועלת בזאת המצוה הוא במדות ובדעות אולם במדות כי מזה יתבאר שענין גלוי הערו' הוא מגונה ולזה אין ראוי לאדם שתגלה במקומות הקדושים כמו הענין בכבש אשר בו יעלו על המזבח ולזה אין ראוי לאדם שימשך אחר פעולות הערוה כי הוא גנות לנו מצד גנות פעולותיה ואולם ישתמש בה בכרחי לבד לקיום המין ולדחיית המותר הזרעי ואולם התועלת ממנה בדעות הוא מהדברים היותר נפלאים שיהיו בדעות וזה שכבר התבאר במ"י כי הש"י יחסו מהנמצאו' בכללם יחס מושכל המלאכה אשר בנפש האומן אל העשוי במלאכה ההיא ולזה יהיה השם יתע' נימוסי הנמצאות בכללם וסדרם וישרם ושם התבאר בספר מ"י שהוא זה הנימוס בצד אשר הוא אחד פשוט לא בצד שהם רבים ולזה אין קצתו לקצת אצל הש"י במדרגת ההיולי כמו הענין בנמצאות העלילו' שהם קצתם לקצת במדרגת ההיולי והיה זה כן בנמצאות העלולות מזה הנימוס מהכרח החמר ר"ל שהחמר ישים מתחלק זה הנימוס הבלתי מתחלק מצד שלא יוכל לקבל מהשלמות והטוב יותר מזה השעור כאלו תאמר שהיסודות לא יקבלו מהשלמות כי אם חלק מועט והאדם קבל ממנו הרבה מפני שהחומר לא יוכל לקבל מהשלמות יותר והוא מבואר שכאשר נתבונן בנמצאות ונתחיל מהשפל נעלה מעלת אחר מעלה עד שנגיע אל הש"י והיה זה מביא לחשוב שיהיה הש"י רבים להיות אלו המושכלות אשר אצלו רבות ולה צוה שלא נעלה במעלות כאשר נעלה אל המזבח לעבוד בו השם יתע' להורות על שהעליה בהשגתו מאלו הדברים השפלים אינה במעלו' אצל השם יתע' ואם הם במעלות אצלנו אבל היה זה הנימוס אצלו דבר אחר בלתי מתחלק ואמנם קרה לנו שתהיה עליתינו לזאת ההשגה במעלות מצד ערות החומר וחסרונו אשר ישים מתחלק הנימוס הבלתי מתחלק מצד שלא יכול לקבל מהשלמו' יות' וזה הענין עמוק מאד ונפלא והטעות בו מדחיק האדם מהשלמות הרחקה נפלאה כמו שיתב' במעט עיון למי שראה דברינו בחלק הג' מהמאמר החמישי למ"י והנה אין הנה קום זאת החקירה:
